def create_simple_token(data: Dict[str, Any]) -> str:
    payload = {
        "data": data,
        "exp": int(time.time()) + 24*3600,
        "iat": int(time.time())
    }
    return base64.b64encode(json.dumps(payload).encode()).decode()

def verify_simple_token(token: str) -> Dict[str, Any]:
    try:
        payload = json.loads(base64.b64decode(token.encode()).decode())
        if payload.get("exp", 0) < int(time.time()):
            raise HTTPException(status_code=401, detail="Token expired")
        return payload.get("data", {})
    except Exception:
        raise HTTPException(status_code=401, detail="Invalid token")

def authenticate_admin(credentials: HTTPBasicCredentials = Depends(basic_auth)) -> str:
    # secrets.compare_digest for timing-safe compare
    cu = secrets.compare_digest(credentials.username, ADMIN_USERNAME)
    cp = secrets.compare_digest(credentials.password, ADMIN_PASSWORD)
    if not (cu and cp):
        raise HTTPException(
            status_code=401,
            detail="Invalid admin credentials",
            headers={"WWW-Authenticate": "Basic"}
        )
    return credentials.username

async def safe_edit_message(query, text: str, reply_markup=None, parse_mode=None):
    try:
        return await query.edit_message_text(text=text, reply_markup=reply_markup, parse_mode=parse_mode)
    except BadRequest as e:
        if "Message is not modified" in str(e):
            logger.debug("Message not modified; ignoring")
            return None
        logger.error(f"BadRequest in edit: {e}")
        return None
    except Exception as e:
        logger.error(f"Unexpected edit error: {e}")
        return None

async def safe_send_message(bot, chat_id: int, text: str, reply_markup=None, parse_mode=None):
    try:
        return await bot.send_message(chat_id=chat_id, text=text, reply_markup=reply_markup, parse_mode=parse_mode)
    except Exception as e:
        logger.error(f"Send message error to {chat_id}: {e}")
        return None

