class EnhancedUserModel:
    def __init__(self):
        self.collection_cache: Dict[str, Any] = {}

    def get_collection(self, name: str):
        if not db_client or not db_connected:
            logger.warning(f"DB not connected: collection '{name}' unavailable")
            return None
        if name not in self.collection_cache:
            self.collection_cache[name] = getattr(db_client.walletbot, name)
        return self.collection_cache[name]

    async def create_user(self, user_data: Dict[str, Any]) -> bool:
        col = self.get_collection("users")
        if col is None:
            return False
        user_id = user_data["user_id"]
        try:
            ex = await col.find_one({"user_id": user_id})
            if ex:
                return True
            doc = {
                "user_id": user_id,
                "username": user_data.get("username", "Unknown"),
                "first_name": user_data.get("first_name", "User"),
                "last_name": user_data.get("last_name", ""),
                "created_at": datetime.utcnow(),
                "last_activity": datetime.utcnow(),
                "device_verified": False,
                "device_fingerprint": None,
                "verification_status": "pending",
                "device_verified_at": None,
                "wallet_balance": 0.0,
                "total_earned": 0.0,
                "referral_earnings": 0.0,
                "withdrawal_total": 0.0,
                "pending_withdrawals": 0.0,
                "referred_by": user_data.get("referred_by"),
                "referral_code": str(uuid.uuid4())[:8].upper(),
                "total_referrals": 0,
                "active_referrals": 0,
                "is_active": True,
                "is_banned": False,
                "ban_reason": None,
                "warning_count": 0,
                "campaigns_completed": 0,
                "screenshots_submitted": 0,
                "screenshots_approved": 0,
                "screenshots_rejected": 0,
                "gift_codes_redeemed": 0,
                "gift_code_earnings": 0.0,
                "notification_enabled": True,
                "language": "en"
            }
            await col.insert_one(doc)
            logger.info(f"New user created: {user_id}")
            return True
        except Exception as e:
            logger.error(f"Create user error: {e}")
            return False

    async def get_user(self, user_id: int) -> Optional[Dict[str, Any]]:
        col = self.get_collection("users")
        if col is None:
            return None
        try:
            user = await col.find_one({"user_id": user_id})
            if user:
                await col.update_one({"user_id": user_id}, {"$set": {"last_activity": datetime.utcnow()}})
            return user
        except Exception as e:
            logger.error(f"Get user error: {e}")
            return None

    async def update_user(self, user_id: int, update: Dict[str, Any]) -> bool:
        col = self.get_collection("users")
        if col is None:
            return False
        try:
            update["updated_at"] = datetime.utcnow()
            res = await col.update_one({"user_id": user_id}, {"$set": update})
            return res.modified_count > 0
        except Exception as e:
            logger.error(f"Update user error: {e}")
            return False

    async def is_user_verified(self, user_id: int) -> bool:
        u = await self.get_user(user_id)
        if not u:
            return False
        return (
            u.get("device_verified", False)
            and u.get("device_fingerprint") is not None
            and u.get("verification_status") == "verified"
            and not u.get("is_banned", False)
            and u.get("is_active", True)
        )

    async def generate_device_fingerprint(self, device_data: Dict[str, Any]) -> str:
        try:
            components = [
                str(device_data.get('screen_resolution', '')),
                str(device_data.get('user_agent_hash', '')),
                str(device_data.get('timezone_offset', '')),
                str(device_data.get('platform', '')),
                str(device_data.get('language', '')),
                str(device_data.get('canvas_hash', '')),
                str(device_data.get('webgl_hash', '')),
                str(device_data.get('hardware_concurrency', '')),
                str(device_data.get('memory', '')),
                str(device_data.get('touch_support', '')),
                str(device_data.get('color_depth', '')),
                str(device_data.get('screen_orientation', ''))
            ]
            combined = '|'.join(filter(None, components))
            return hashlib.sha256(combined.encode('utf-8')).hexdigest()
        except Exception as e:
            logger.error(f"Fingerprint error: {e}")
            return hashlib.sha256(f"error_{datetime.utcnow().timestamp()}".encode()).hexdigest()

    async def check_device_already_used(self, fingerprint: str) -> Dict[str, Any]:
        dev_col = self.get_collection("device_fingerprints")
        if dev_col is None:
            return {"used": False, "reason": "database_error"}
        try:
            ex = await dev_col.find_one({"fingerprint": fingerprint})
            if ex:
                return {
                    "used": True,
                    "existing_user_id": ex.get("user_id"),
                    "message": "इस device पर पहले से ek verified account है. एक device पर एक ही account allowed है."
                }
            return {"used": False}
        except Exception as e:
            logger.error(f"Device check error: {e}")
            return {"used": True, "reason": "check_error", "message": "Technical error during device verification"}

    async def store_device_fingerprint(self, user_id: int, fingerprint: str, device_data: Dict[str, Any]):
        dev_col = self.get_collection("device_fingerprints")
        if dev_col is None:
            return
        try:
            await dev_col.insert_one({
                "user_id": user_id,
                "fingerprint": fingerprint,
                "device_data": device_data,
                "created_at": datetime.utcnow(),
                "last_used": datetime.utcnow(),
                "is_active": True,
                "verification_ip": device_data.get('ip_address', 'unknown'),
                "user_agent": device_data.get('user_agent', 'unknown')
            })
        except Exception as e:
            logger.error(f"Store fingerprint error: {e}")

    async def mark_user_verified(self, user_id: int, fingerprint: str):
        col = self.get_collection("users")
        if col is None:
            return
        try:
            res = await col.update_one(
                {"user_id": user_id},
                {"$set": {
                    "device_verified": True,
                    "device_fingerprint": fingerprint,
                    "verification_status": "verified",
                    "device_verified_at": datetime.utcnow()
                }}
            )
            if res.modified_count == 0:
                logger.warning(f"User verify mark not modified for {user_id}")
        except Exception as e:
            logger.error(f"Mark verified error: {e}")

    async def verify_device_strict(self, user_id: int, device_data: Dict[str, Any]) -> Dict[str, Any]:
        try:
            fp = await self.generate_device_fingerprint(device_data)
            chk = await self.check_device_already_used(fp)
            if chk.get("used"):
                return {"success": False, "message": chk.get("message")}
            await self.store_device_fingerprint(user_id, fp, device_data)
            await self.mark_user_verified(user_id, fp)
            return {"success": True, "message": "Device verified successfully!"}
        except Exception as e:
            logger.error(f"Verify device error: {e}")
            return {"success": False, "message": "Technical error occurred during device verification"}

    # ---------------------------- WALLET ----------------------------

    async def add_to_wallet(self, user_id: int, amount: float, txn_type: str, description: str):
        col = self.get_collection("users")
        txn = self.get_collection("transactions")
        if col is None or txn is None:
            return False
        try:
            await col.update_one(
                {"user_id": user_id},
                {"$inc": {"wallet_balance": amount, "total_earned": amount}}
            )
            await txn.insert_one({
                "user_id": user_id,
                "amount": amount,
                "type": txn_type,
                "description": description,
                "status": "success",
                "created_at": datetime.utcnow()
            })
            return True
        except Exception as e:
            logger.error(f"Add wallet error: {e}")
            return False

    async def subtract_from_wallet(self, user_id: int, amount: float, txn_type: str, description: str):
        col = self.get_collection("users")
        txn = self.get_collection("transactions")
        if col is None or txn is None:
            return False
        try:
            user = await col.find_one({"user_id": user_id})
            if not user:
                return False
            if user.get("wallet_balance", 0.0) < amount:
                return False
            await col.update_one(
                {"user_id": user_id},
                {"$inc": {"wallet_balance": -amount}}
            )
            await txn.insert_one({
                "user_id": user_id,
                "amount": -amount,
                "type": txn_type,
                "description": description,
                "status": "success",
                "created_at": datetime.utcnow()
            })
            return True
        except Exception as e:
            logger.error(f"Subtract wallet error: {e}")
            return False

    # ------------------------- Campaign/User helpers -------------------------

    async def get_campaign_by_id(self, campaign_id: str) -> Optional[Dict[str, Any]]:
        col = self.get_collection("campaigns")
        if col is None:
            return None
        try:
            return await col.find_one({"campaign_id": campaign_id})
        except Exception as e:
            logger.error(f"Get campaign error: {e}")
            return None

    async def submit_screenshot(self, user_id: int, campaign_id: str, file_info: Dict[str, Any]) -> Dict[str, Any]:
        col = self.get_collection("screenshots")
        if col is None:
            return {"success": False, "message": "Database error"}
        try:
            sub_id = str(uuid.uuid4())
            doc = {
                "submission_id": sub_id,
                "user_id": user_id,
                "campaign_id": campaign_id,
                "status": "pending",
                "file_path": file_info.get("file_path"),
                "filename": file_info.get("filename"),
                "file_size": file_info.get("file_size", 0),
                "created_at": datetime.utcnow(),
                "reviewed_at": None,
                "admin_notes": ""
            }
            await col.insert_one(doc)
            # Counters ($inc fixes done in ScreenshotManager after processing)
            return {"success": True, "submission_id": sub_id}
        except Exception as e:
            logger.error(f"Submit screenshot error: {e}")
            return {"success": False, "message": "Failed to create submission"}

user_model = EnhancedUserModel()

