class CampaignManager:
    def __init__(self, user_model_instance: EnhancedUserModel):
        self.user_model = user_model_instance

    async def can_user_participate(self, user_id: int, campaign_id: str) -> Dict[str, Any]:
        # Simple example rule: verified users only
        is_verified = await self.user_model.is_user_verified(user_id)
        if not is_verified:
            return {"can_participate": False, "reason": "Please verify device first."}
        campaign = await self.user_model.get_campaign_by_id(campaign_id)
        if not campaign:
            return {"can_participate": False, "reason": "Campaign not found"}
        # More rules can be implemented here (daily limits, time window, etc.)
        return {"can_participate": True}

class ScreenshotManager:
    def __init__(self, user_model_instance: EnhancedUserModel):
        self.user_model = user_model_instance
        self.upload_dir = "uploads/screenshots"
        os.makedirs(self.upload_dir, exist_ok=True)

    async def save_screenshot_file(self, file_content: bytes, user_id: int, campaign_id: str) -> Dict[str, Any]:
        try:
            ts = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
            filename = f"{user_id}_{campaign_id}_{ts}_{uuid.uuid4().hex[:8]}.jpg"
            path = os.path.join(self.upload_dir, filename)
            async with aiofiles.open(path, "wb") as f:
                await f.write(file_content)
            return {"success": True, "file_path": path, "filename": filename, "file_size": len(file_content)}
        except Exception as e:
            logger.error(f"Save screenshot error: {e}")
            return {"success": False, "message": "Failed to save file"}

    async def process_screenshot_submission(self, user_id: int, campaign_id: str, file_content: bytes) -> Dict[str, Any]:
        try:
            campaign_manager = CampaignManager(self.user_model)
            chk = await campaign_manager.can_user_participate(user_id, campaign_id)
            if not chk["can_participate"]:
                return {"success": False, "message": chk["reason"]}

            file_res = await self.save_screenshot_file(file_content, user_id, campaign_id)
            if not file_res["success"]:
                return file_res

            sub_res = await self.user_model.submit_screenshot(
                user_id, campaign_id, {
                    "file_path": file_res["file_path"],
                    "filename": file_res["filename"],
                    "file_size": file_res["file_size"]
                }
            )
            if not sub_res["success"]:
                return sub_res

            # Update campaign counters
            campaigns_col = self.user_model.get_collection("campaigns")
            if campaigns_col is not None:
                await campaigns_col.update_one(
                    {"campaign_id": campaign_id},
                    {"$inc": {"total_submissions": 1, "current_participants": 1}}
                )

            # FIX: Correctly increment user's screenshots_submitted
            users_col = self.user_model.get_collection("users")
            if users_col is not None:
                await users_col.update_one({"user_id": user_id}, {"$inc": {"screenshots_submitted": 1}})

            return {
                "success": True,
                "submission_id": sub_res["submission_id"],
                "message": "Screenshot submitted successfully! It will be reviewed soon."
            }
        except Exception as e:
            logger.error(f"Process submission error: {e}")
            return {"success": False, "message": "Technical error occurred"}

    async def approve_screenshot(self, submission_id: str, admin_notes: str = "") -> Dict[str, Any]:
        col = self.user_model.get_collection("screenshots")
        if col is None:
            return {"success": False, "message": "Database error"}
        try:
            ss = await col.find_one({"submission_id": submission_id})
            if not ss:
                return {"success": False, "message": "Screenshot not found"}
            if ss["status"] != "pending":
                return {"success": False, "message": "Already processed"}

            campaign = await self.user_model.get_campaign_by_id(ss["campaign_id"])
            if not campaign:
                return {"success": False, "message": "Campaign not found"}
            reward = campaign.get("reward_amount", 5.0)

            await col.update_one(
                {"submission_id": submission_id},
                {"$set": {"status": "approved", "reviewed_at": datetime.utcnow(), "admin_notes": admin_notes}}
            )

            await self.user_model.add_to_wallet(
                ss["user_id"], reward, "campaign",
                f"Screenshot approved for campaign: {campaign.get('name', ss['campaign_id'])}"
            )

            # FIX: increment screenshots_approved
            users_col = self.user_model.get_collection("users")
            if users_col is not None:
                await users_col.update_one({"user_id": ss["user_id"]}, {"$inc": {"screenshots_approved": 1}})

            campaigns_col = self.user_model.get_collection("campaigns")
            if campaigns_col is not None:
                await campaigns_col.update_one(
                    {"campaign_id": ss["campaign_id"]},
                    {"$inc": {"approved_submissions": 1}}
                )
            return {"success": True, "reward_amount": reward, "message": "Approved & rewarded"}
        except Exception as e:
            logger.error(f"Approve screenshot error: {e}")
            return {"success": False, "message": "Technical error occurred"}

    async def reject_screenshot(self, submission_id: str, admin_notes: str = "") -> Dict[str, Any]:
        col = self.user_model.get_collection("screenshots")
        if col is None:
            return {"success": False, "message": "Database error"}
        try:
            ss = await col.find_one({"submission_id": submission_id})
            if not ss:
                return {"success": False, "message": "Screenshot not found"}
            if ss["status"] != "pending":
                return {"success": False, "message": "Already processed"}

            await col.update_one(
                {"submission_id": submission_id},
                {"$set": {"status": "rejected", "reviewed_at": datetime.utcnow(), "admin_notes": admin_notes}}
            )

            # FIX: increment screenshots_rejected
            users_col = self.user_model.get_collection("users")
            if users_col is not None:
                await users_col.update_one({"user_id": ss["user_id"]}, {"$inc": {"screenshots_rejected": 1}})

            campaigns_col = self.user_model.get_collection("campaigns")
            if campaigns_col is not None:
                await campaigns_col.update_one(
                    {"campaign_id": ss["campaign_id"]},
                    {"$inc": {"rejected_submissions": 1}}
                )
            return {"success": True, "message": "Rejected"}
        except Exception as e:
            logger.error(f"Reject screenshot error: {e}")
            return {"success": False, "message": "Technical error occurred"}

screenshot_manager = ScreenshotManager(user_model)

