class PaymentGatewayBase:
    def __init__(self, api_key: str, is_test_mode: bool = False):
        self.api_key = api_key
        self.is_test_mode = is_test_mode

    async def process_payment(self, amount: float, recipient_details: Dict[str, Any]) -> Dict[str, Any]:
        raise NotImplementedError

    def get_supported_methods(self) -> List[str]:
        return []

class RazorpayGateway(PaymentGatewayBase):
    def __init__(self, api_key: str, api_secret: str, is_test_mode: bool = False):
        super().__init__(api_key, is_test_mode)
        self.api_secret = api_secret
        self.gateway_name = "razorpay"

    async def process_payment(self, amount: float, recipient_details: Dict[str, Any]) -> Dict[str, Any]:
        try:
            method = recipient_details.get("method", "upi")
            if method not in ("upi", "bank"):
                return {"success": False, "message": "Unsupported payment method"}
            if self.is_test_mode:
                return {
                    "success": True,
                    "transaction_id": f"rzp_test_{uuid.uuid4().hex[:12]}",
                    "message": "Payment processed successfully (TEST MODE)"
                }
            # FIX: Live mode not implemented => do not fake success
            return {"success": False, "message": "Live payouts not enabled or API integration disabled"}
        except Exception as e:
            logger.error(f"Razorpay error: {e}")
            return {"success": False, "message": "Payment gateway error"}

    def get_supported_methods(self) -> List[str]:
        return ["upi", "bank"]

class PaytmGateway(PaymentGatewayBase):
    def __init__(self, api_key: str, merchant_id: str, is_test_mode: bool = False):
        super().__init__(api_key, is_test_mode)
        self.merchant_id = merchant_id
        self.gateway_name = "paytm"

    async def process_payment(self, amount: float, recipient_details: Dict[str, Any]) -> Dict[str, Any]:
        try:
            method = recipient_details.get("method", "wallet")
            if method != "wallet":
                return {"success": False, "message": "Unsupported method for Paytm"}
            if self.is_test_mode:
                return {
                    "success": True,
                    "transaction_id": f"ptm_test_{uuid.uuid4().hex[:12]}",
                    "message": "Paytm payment processed successfully (TEST MODE)"
                }
            # FIX: live not implemented
            return {"success": False, "message": "Live payouts not enabled or API integration disabled"}
        except Exception as e:
            logger.error(f"Paytm error: {e}")
            return {"success": False, "message": "Paytm gateway error"}

    def get_supported_methods(self) -> List[str]:
        return ["wallet"]

class ManualPaymentProcessor:
    def __init__(self, user_model_instance: EnhancedUserModel):
        self.user_model = user_model_instance

    async def send_approval_request(self, user_id: int, amount: float, method: str, details: Dict[str, Any]) -> Dict[str, Any]:
        col = self.user_model.get_collection("withdrawal_requests")
        if col is None:
            return {"success": False, "message": "Database error"}
        try:
            req_id = str(uuid.uuid4())
            doc = {
                "request_id": req_id,
                "user_id": user_id,
                "amount": amount,
                "method": method,
                "details": details,
                "status": "pending",
                "created_at": datetime.utcnow(),
                "processed_time": None,
                "admin_notes": ""
            }
            await col.insert_one(doc)
            # mark user's pending withdrawals
            await self.user_model.update_user(user_id, {"pending_withdrawals": amount})
            return {"success": True, "request_id": req_id}
        except Exception as e:
            logger.error(f"Create withdrawal request error: {e}")
            return {"success": False, "message": "Failed to create request"}

    async def process_admin_decision(self, request_id: str, action: str, admin_notes: str = "") -> Dict[str, Any]:
        col = self.user_model.get_collection("withdrawal_requests")
        if col is None:
            return {"success": False, "message": "Database error"}
        try:
            wd = await col.find_one({"request_id": request_id})
            if not wd:
                return {"success": False, "message": "Withdrawal request not found"}
            if wd["status"] != "pending":
                return {"success": False, "message": "Request already processed"}

            now = datetime.utcnow()

            if action == "approve":
                await col.update_one({"request_id": request_id}, {"$set": {"status": "approved", "processed_time": now, "admin_notes": admin_notes}})
                await self.user_model.subtract_from_wallet(
                    wd["user_id"], wd["amount"], "withdrawal", f"Manual withdrawal approved: {request_id}"
                )
                # FIX: proper $inc + $set
                users_col = self.user_model.get_collection("users")
                if users_col is not None:
                    await users_col.update_one(
                        {"user_id": wd["user_id"]},
                        {"$inc": {"withdrawal_total": wd["amount"]},
                         "$set": {"pending_withdrawals": 0}}
                    )
                return {"success": True, "message": "Withdrawal approved", "action": "approved"}

            if action == "reject":
                await col.update_one({"request_id": request_id}, {"$set": {"status": "rejected", "processed_time": now, "admin_notes": admin_notes}})
                await self.user_model.update_user(wd["user_id"], {"pending_withdrawals": 0})
                return {"success": True, "message": "Withdrawal rejected", "action": "rejected"}

            return {"success": False, "message": "Invalid action"}
        except Exception as e:
            logger.error(f"Process admin decision error: {e}")
            return {"success": False, "message": "Technical error occurred"}

class PaymentManager:
    def __init__(self, user_model_instance: EnhancedUserModel):
        self.user_model = user_model_instance
        self.razorpay: Optional[RazorpayGateway] = None
        self.paytm: Optional[PaytmGateway] = None
        self.manual = ManualPaymentProcessor(self.user_model)

    async def initialize_gateways(self):
        settings_col = self.user_model.get_collection("bot_settings")
        cfg = None
        if settings_col is not None:
            cfg = await settings_col.find_one({"type": "main_config"})
        cfg = cfg or {}
        pg = (cfg.get("payment_gateways") or {})
        rzp_cfg = pg.get("razorpay") or {}
        ptm_cfg = pg.get("paytm") or {}

        if rzp_cfg.get("enabled"):
            self.razorpay = RazorpayGateway(
                api_key=rzp_cfg.get("api_key", ""),
                api_secret=rzp_cfg.get("secret", ""),
                is_test_mode=rzp_cfg.get("test_mode", True)
            )
        if ptm_cfg.get("enabled"):
            self.paytm = PaytmGateway(
                api_key=ptm_cfg.get("api_key", ""),
                merchant_id=ptm_cfg.get("merchant_id", ""),
                is_test_mode=ptm_cfg.get("test_mode", True)
            )

    async def payout(self, user_id: int, amount: float, method: str, details: Dict[str, Any]) -> Dict[str, Any]:
        mode = (await self._get_payment_mode()) or "manual"
        if mode == "manual" or (method == "manual"):
            return await self.manual.send_approval_request(user_id, amount, method, details)
        if method == "upi" and self.razorpay:
            return await self.razorpay.process_payment(amount, details)
        if method == "bank" and self.razorpay:
            return await self.razorpay.process_payment(amount, details)
        if method == "wallet" and self.paytm:
            return await self.paytm.process_payment(amount, details)
        return {"success": False, "message": "Unsupported payout method or gateway disabled"}

    async def _get_payment_mode(self) -> str:
        col = self.user_model.get_collection("bot_settings")
        if col is None:
            return "manual"
        cfg = await col.find_one({"type": "main_config"})
        if not cfg:
            return "manual"
        return cfg.get("payment_mode", "manual")

payment_manager = PaymentManager(user_model)

