class ChannelManager:
    def __init__(self, user_model_instance: EnhancedUserModel):
        self.user_model = user_model_instance

    async def update_channel_member_count(self, channel_id: str, bot_instance: Optional[Bot]):
        try:
            col = self.user_model.get_collection("force_join_channels")
            if col is None:
                return
            channel = await col.find_one({"channel_id": channel_id})
            if not channel:
                return
            # FIX: safe fallback (avoid PTB v20 get_member_count which doesn't exist)
            member_count = channel.get("member_count", 0)
            await col.update_one(
                {"channel_id": channel_id},
                {"$set": {"member_count": member_count, "last_updated": datetime.utcnow()}}
            )
        except Exception as e:
            logger.error(f"Channel member count error: {e}")

    async def get_channels_statistics(self) -> Dict[str, Any]:
        col = self.user_model.get_collection("force_join_channels")
        if col is None:
            return {"total": 0, "active": 0, "sum_members": 0}
        total = await col.count_documents({})
        active = await col.count_documents({"is_active": True})
        agg = col.aggregate([
            {"$group": {"_id": None, "sum": {"$sum": {"$ifNull": ["$member_count", 0]}}}}
        ])
        doc = await agg.to_list(length=1)
        sum_members = (doc[0]["sum"] if doc else 0)
        return {"total": total, "active": active, "sum_members": sum_members}

