@app.post("/api/verify-device")
async def verify_device(
    user_id: int = Form(...),
    screen_resolution: str = Form(...),
    user_agent_hash: str = Form(...),
    timezone_offset: str = Form(...),
    platform: str = Form(...),
    language: str = Form(...),
    canvas_hash: str = Form(...),
    webgl_hash: str = Form(...),
    hardware_concurrency: str = Form(...),
    memory: str = Form(...),
    touch_support: str = Form(...),
    color_depth: str = Form(...),
    screen_orientation: str = Form(...),
    user_agent: str = Form("unknown"),
    ip_address: str = Form("unknown"),
):
    device_data = {
        "screen_resolution": screen_resolution,
        "user_agent_hash": user_agent_hash,
        "timezone_offset": timezone_offset,
        "platform": platform,
        "language": language,
        "canvas_hash": canvas_hash,
        "webgl_hash": webgl_hash,
        "hardware_concurrency": hardware_concurrency,
        "memory": memory,
        "touch_support": touch_support,
        "color_depth": color_depth,
        "screen_orientation": screen_orientation,
        "user_agent": user_agent,
        "ip_address": ip_address,
    }
    try:
        # Ensure user exists
        await user_model.create_user({"user_id": user_id})
        res = await user_model.verify_device_strict(user_id, device_data)
        if res.get("success") and wallet_bot and wallet_bot.initialized and wallet_bot.bot:
            try:
                await wallet_bot.bot.send_message(chat_id=user_id, text="/device_verified")
            except Exception as e:
                logger.warning(f"Could not notify user {user_id} after verification: {e}")
        return res
    except Exception as e:
        logger.error(f"Verify device endpoint error: {e}")
        raise HTTPException(status_code=500, detail="Internal error")

@app.get("/verify")
async def verification_page(user_id: int):
    html_content = f"""
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Enterprise Wallet Bot - Device Verification</title>
<style>
  body {{ font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji"; background: #0f172a; color: #e2e8f0; margin:0; }}
  .container {{ max-width: 720px; margin: 0 auto; padding: 24px; }}
  .card {{ background: linear-gradient(180deg, rgba(30,41,59,0.8), rgba(15,23,42,0.8)); border: 1px solid rgba(148,163,184,0.12); border-radius: 16px; padding: 24px; box-shadow: 0 10px 30px rgba(0,0,0,0.3); }}
  .title {{ font-size: 22px; font-weight: 700; margin-bottom: 12px; display:flex; align-items:center; gap:10px; }}
  .desc {{ font-size: 14px; color: #94a3b8; line-height: 1.6; margin-bottom: 20px; }}
  .btn {{ width: 100%; padding: 14px 16px; background: linear-gradient(90deg, #22c55e, #16a34a); color: white; border: none; border-radius: 12px; font-weight: 700; letter-spacing: .3px; cursor: pointer; transition: transform .08s ease-in-out, filter .2s; }}
  .btn:active {{ transform: scale(0.98); }}
  .status {{ margin-top: 14px; font-size: 13px; color: #94a3b8; }}
  .success {{ color: #34d399; font-weight: 600; }}
  .error {{ color: #f87171; font-weight: 600; }}
</style>
</head>
<body>
<div class="container">
  <div class="card">
    <div class="title">🛡️ Device Verification</div>
    <div class="desc">Verify this device to secure the account and unlock all features. One verified account per device is allowed.</div>
    <button id="verifyBtn" class="btn">Verify my device</button>
    <div id="status" class="status">Ready.</div>
  </div>
</div>
<script>
const USER_ID = {user_id};
const BOT_USERNAME = ''; // optional fallback; not required if Telegram WebApp is available
let verificationInProgress = false;

function sha256(str) {{
  const enc = new TextEncoder();
  return crypto.subtle.digest("SHA-256", enc.encode(str)).then(buf => {{
    return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
  }});
}}

async function getCanvasHash() {{
  try {{
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    canvas.width = 180; canvas.height = 40;
    ctx.textBaseline = "top";
    ctx.font = "16px 'Arial'";
    ctx.textBaseline = "alphabetic";
    ctx.fillStyle = "#f60";
    ctx.fillRect(125, 1, 62, 20);
    ctx.fillStyle = "#069";
    ctx.fillText("device-fingerprint", 2, 15);
    ctx.strokeStyle = "rgba(102, 204, 0, 0.7)";
    ctx.strokeRect(125, 1, 62, 20);
    const data = canvas.toDataURL();
    return await sha256(data);
  }} catch (e) {{
    return "canvas_error";
  }}
}}

async function getWebGLHash() {{
  try {{
    const canvas = document.createElement("canvas");
    const gl = canvas.getContext("webgl") || canvas.getContext("experimental-webgl");
    if (!gl) return "webgl_unavailable";
    const debugInfo = gl.getExtension("WEBGL_debug_renderer_info");
    const vendor = debugInfo ? gl.getParameter(debugInfo.UNMASKED_VENDOR_WEBGL) : "unknown_vendor";
    const renderer = debugInfo ? gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL) : "unknown_renderer";
    return await sha256(vendor + "|" + renderer);
  }} catch (e) {{
    return "webgl_error";
  }}
}}

async function getUserAgentHash() {{
  try {{
    const ua = navigator.userAgent || "unknown";
    return await sha256(ua);
  }} catch (e) {{
    return "ua_error";
  }}
}}

function getInfo() {{
  const dpr = window.devicePixelRatio || 1;
  return {{
    screen_resolution: (window.screen.width * dpr) + "x" + (window.screen.height * dpr),
    timezone_offset: String(new Date().getTimezoneOffset()),
    platform: navigator.platform || "unknown",
    language: navigator.language || "en",
    hardware_concurrency: String(navigator.hardwareConcurrency || "0"),
    memory: String(navigator.deviceMemory || "0"),
    touch_support: ("ontouchstart" in window) ? "1" : "0",
    color_depth: String(screen.colorDepth || 24),
    screen_orientation: (screen.orientation && screen.orientation.type) ? screen.orientation.type : "unknown",
    user_agent: navigator.userAgent || "unknown"
  }};
}}

async function initiateVerification() {{
  if (verificationInProgress) return;
  verificationInProgress = true;
  const btn = document.getElementById("verifyBtn");
  const status = document.getElementById("status");
  btn.disabled = true;
  btn.innerText = "Verifying...";
  status.innerText = "Collecting device signals...";
  try {{
    const info = getInfo();
    const canvas_hash = await getCanvasHash();
    const webgl_hash = await getWebGLHash();
    const ua_hash = await getUserAgentHash();
    status.innerText = "Submitting to server...";
    const form = new FormData();
    form.append("user_id", USER_ID);
    form.append("screen_resolution", info.screen_resolution);
    form.append("user_agent_hash", ua_hash);
    form.append("timezone_offset", info.timezone_offset);
    form.append("platform", info.platform);
    form.append("language", info.language);
    form.append("canvas_hash", canvas_hash);
    form.append("webgl_hash", webgl_hash);
    form.append("hardware_concurrency", info.hardware_concurrency);
    form.append("memory", info.memory);
    form.append("touch_support", info.touch_support);
    form.append("color_depth", info.color_depth);
    form.append("screen_orientation", info.screen_orientation);
    form.append("user_agent", info.user_agent);
    try {{
      const ip = await fetch("https://api.ipify.org?format=json").then(r=>r.json()).then(j=>j.ip).catch(()=> "unknown");
      form.append("ip_address", ip || "unknown");
    }} catch (e) {{
      form.append("ip_address", "unknown");
    }}
    const resp = await fetch("/api/verify-device", {{ method: "POST", body: form }});
    if (!resp.ok) throw new Error("Server error: " + resp.status);
    const data = await resp.json();
    if (data.success) {{
      status.classList.add("success");
      status.innerText = "Device verified successfully.";
      if (window.Telegram && window.Telegram.WebApp) {{
        window.Telegram.WebApp.close();
      }} else if (BOT_USERNAME) {{
        window.location.href = "https://t.me/" + BOT_USERNAME;
      }}
    }} else {{
      status.classList.add("error");
      status.innerText = data.message || "Verification failed.";
      btn.disabled = false; btn.innerText = "Try again";
      verificationInProgress = false;
    }}
  }} catch (e) {{
    status.classList.add("error");
    status.innerText = "Error: " + e.message;
    btn.disabled = false; btn.innerText = "Try again";
    verificationInProgress = false;
  }}
}}

document.getElementById("verifyBtn").addEventListener("click", initiateVerification);
</script>
</body>
</html>
"""
    return HTMLResponse(content=html_content)

