@app.get("/api/admin/dashboard")
async def admin_dashboard_api(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot if db_client else None
        total_users = await db.users.count_documents({}) if db else 0
        verified_users = await db.users.count_documents({"device_verified": True}) if db else 0
        total_campaigns = await db.campaigns.count_documents({}) if db else 0
        pending_screenshots = await db.screenshots.count_documents({"status": "pending"}) if db else 0
        approved_screenshots = await db.screenshots.count_documents({"status": "approved"}) if db else 0
        rejected_screenshots = await db.screenshots.count_documents({"status": "rejected"}) if db else 0
        pending_withdrawals = await db.withdrawal_requests.count_documents({"status": "pending"}) if db else 0
        total_withdrawals = await db.withdrawal_requests.count_documents({}) if db else 0
        channels_stats = await channel_manager.get_channels_statistics()
        return {
            "success": True,
            "data": {
                "users": {"total": total_users, "verified": verified_users},
                "campaigns": {"total": total_campaigns},
                "screenshots": {
                    "pending": pending_screenshots,
                    "approved": approved_screenshots,
                    "rejected": rejected_screenshots
                },
                "withdrawals": {
                    "pending": pending_withdrawals,
                    "total": total_withdrawals
                },
                "channels": channels_stats
            }
        }
    except Exception as e:
        logger.error(f"Admin dashboard API error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load dashboard")

@app.get("/api/admin/users")
async def admin_list_users(
    page: int = 1,
    page_size: int = 20,
    search: Optional[str] = None,
    username: str = Depends(authenticate_admin)
):
    try:
        page = max(1, page)
        page_size = min(100, max(1, page_size))
        db = db_client.walletbot
        query = {}
        if search:
            # Simple search: username contains OR exact user_id if numeric
            search_or = [{"username": {"$regex": str(search), "$options": "i"}}]
            # Try parse numeric id
            try:
                num = int(search)
                search_or.append({"user_id": num})
            except Exception:
                pass
            query = {"$or": search_or}
        total = await db.users.count_documents(query)
        cursor = db.users.find(query).sort("created_at", -1).skip((page - 1) * page_size).limit(page_size)
        users = await cursor.to_list(length=page_size)
        return {
            "success": True,
            "data": {
                "users": users,
                "pagination": {"page": page, "page_size": page_size, "total": total}
            }
        }
    except Exception as e:
        logger.error(f"Admin list users error: {e}")
        raise HTTPException(status_code=500, detail="Failed to list users")

@app.get("/api/admin/users/{user_id}")
async def admin_get_user_details(user_id: int, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        user = await db.users.find_one({"user_id": user_id})
        if not user:
            raise HTTPException(status_code=404, detail="User not found")
        tx_cursor = db.transactions.find({"user_id": user_id}).sort("created_at", -1).limit(50)
        tx = await tx_cursor.to_list(length=50)
        return {"success": True, "data": {"user": user, "transactions": tx}}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Admin get user details error: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch user details")

@app.post("/api/admin/users/{user_id}/wallet")
async def admin_update_wallet(
    user_id: int,
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        amount = to_float_safe(body.get("amount", 0))
        action = (body.get("action") or "add").lower()
        reason = body.get("reason") or "admin adjustment"
        if action == "add":
            ok = await user_model.add_to_wallet(user_id, amount, "admin_adjustment", reason)
        elif action == "subtract":
            ok = await user_model.subtract_from_wallet(user_id, amount, "admin_adjustment", reason)
        else:
            return {"success": False, "message": "Invalid action"}
        return {"success": bool(ok)}
    except Exception as e:
        logger.error(f"Admin update wallet error: {e}")
        raise HTTPException(status_code=500, detail="Failed to update wallet")

@app.post("/api/admin/users/{user_id}/ban")
async def admin_ban_user(
    user_id: int,
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        ban = bool(body.get("ban", True))
        reason = body.get("reason") or "violation"
        await db.users.update_one(
            {"user_id": user_id},
            {"$set": {"is_banned": ban, "ban_reason": reason}}
        )
        return {"success": True}
    except Exception as e:
        logger.error(f"Admin ban user error: {e}")
        raise HTTPException(status_code=500, detail="Failed to update user status")

