@app.put("/api/admin/campaigns/{campaign_id}")
async def admin_update_campaign(
    campaign_id: str,
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        update = {k: v for k, v in body.items() if k in ["name", "reward_amount", "description", "image_url", "active"]}
        if "reward_amount" in update:
            update["reward_amount"] = to_float_safe(update["reward_amount"], 5.0)
        update["updated_at"] = datetime.utcnow()
        res = await db.campaigns.update_one({"campaign_id": campaign_id}, {"$set": update})
        return {"success": res.modified_count > 0}
    except Exception as e:
        logger.error(f"Admin update campaign error: {e}")
        raise HTTPException(status_code=500, detail="Failed to update campaign")

