@app.get("/admin/dashboard")
async def admin_dashboard_page():
    html = """
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Enterprise Wallet Bot - Admin Dashboard</title>
<link href="https://unpkg.com/tailwindcss@^2/dist/tailwind.min.css" rel="stylesheet">
<script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
<script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
<script src="https://unpkg.com/@babel/standalone@7.22.5/babel.min.js"></script>
<style>
  body { background: #0f172a; color: #e2e8f0; }
  .card { background: #111827; border: 1px solid rgba(148,163,184,.12); }
  .table-head { background: #0b1220; }
</style>
</head>
<body>
<div id="root" class="p-6"></div>
<script type="text/babel">
const { useState, useEffect, useCallback } = React;

const useAPI = () => {
  const getAuth = () => sessionStorage.getItem('adminAuth');
  const request = useCallback(async (url, options = {}) => {
    const auth = getAuth();
    if(!auth){ window.location.href = '/admin'; return null; }
    const resp = await fetch(url, { ...options, headers: { 'Authorization': 'Basic ' + auth, 'Content-Type': 'application/json', ...(options.headers||{}) }});
    if(resp.status === 401){ sessionStorage.removeItem('adminAuth'); window.location.href = '/admin'; return null; }
    if(!resp.ok){ throw new Error('HTTP ' + resp.status); }
    return await resp.json();
  }, []);
  return {
    getDashboard: () => request('/api/admin/dashboard'),
    getUsers: (p={}) => request('/api/admin/users?' + new URLSearchParams(p)),
    getUserDetails: (id) => request('/api/admin/users/' + id),
    updateUserWallet: (id, d) => request('/api/admin/users/' + id + '/wallet', { method:'POST', body: JSON.stringify(d)}),
    banUser: (id, d) => request('/api/admin/users/' + id + '/ban', { method:'POST', body: JSON.stringify(d)}),
    getCampaigns: (p={}) => request('/api/admin/campaigns?' + new URLSearchParams(p)),
    createCampaign: (d) => request('/api/admin/campaigns', { method:'POST', body: JSON.stringify(d)}),
    updateCampaign: (id, d) => request('/api/admin/campaigns/' + id, { method:'PUT', body: JSON.stringify(d)}),
    deleteCampaign: (id) => request('/api/admin/campaigns/' + id, { method:'DELETE' }),
    getScreenshots: (p={}) => request('/api/admin/screenshots?' + new URLSearchParams(p)),
    approveScreenshot: (id, notes='') => request('/api/admin/screenshots/' + id + '/approve', { method:'POST', body: JSON.stringify({ admin_notes: notes })}),
    rejectScreenshot: (id, notes='') => request('/api/admin/screenshots/' + id + '/reject', { method:'POST', body: JSON.stringify({ admin_notes: notes })}),
    bulkApproveScreenshots: (ids=[]) => request('/api/admin/screenshots/bulk-approve', { method:'POST', body: JSON.stringify({ submission_ids: ids })}),
    getWithdrawals: (p={}) => request('/api/admin/withdrawals?' + new URLSearchParams(p)),
    approveWithdrawal: (id, notes='') => request('/api/admin/withdrawals/' + id + '/approve', { method:'POST', body: JSON.stringify({ admin_notes: notes })}),
    rejectWithdrawal: (id, notes='') => request('/api/admin/withdrawals/' + id + '/reject', { method:'POST', body: JSON.stringify({ admin_notes: notes })}),
    request // EXPOSED so components can make custom calls
  };
};

const Card = ({ title, children }) => (
  <div className="card rounded-lg p-4 shadow mb-6">
    <h2 className="text-lg font-semibold mb-3">{title}</h2>
    {children}
  </div>
);

const UsersTable = ({ items }) => (
  <div className="overflow-x-auto">
    <table className="min-w-full text-sm">
      <thead className="table-head text-gray-300">
        <tr>
          <th className="px-3 py-2 text-left">User ID</th>
          <th className="px-3 py-2 text-left">Username</th>
          <th className="px-3 py-2 text-left">Verified</th>
          <th className="px-3 py-2 text-right">Wallet</th>
          <th className="px-3 py-2 text-right">Screenshots</th>
        </tr>
      </thead>
      <tbody>
        {items.map(u => (
          <tr key={u.user_id} className="border-b border-gray-800">
            <td className="px-3 py-2">{u.user_id}</td>
            <td className="px-3 py-2">{u.username || '—'}</td>
            <td className="px-3 py-2">{u.device_verified ? 'Yes' : 'No'}</td>
            <td className="px-3 py-2 text-right">{(u.wallet_balance || 0).toFixed(2)}</td>
            <td className="px-3 py-2 text-right">{(u.screenshots_submitted || 0)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

const DashboardApp = () => {
  const api = useAPI();
  const [stats, setStats] = useState(null);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      const d = await api.getDashboard();
      setStats(d?.data || null);
      const u = await api.getUsers({ page: 1, page_size: 20 });
      setUsers(u?.data?.users || []);
    } catch (e) {
      console.error(e);
      alert('Failed to load dashboard.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, []);

  if (loading) return <div className="text-gray-400">Loading...</div>;

  return (
    <div className="max-w-7xl mx-auto">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card title="Users">
          <div className="text-2xl font-bold">{stats?.users?.total || 0}</div>
          <div className="text-green-400 text-sm">{stats?.users?.verified || 0} verified</div>
        </Card>
        <Card title="Screenshots">
          <div className="text-2xl font-bold">{(stats?.screenshots?.pending || 0) + (stats?.screenshots?.approved || 0) + (stats?.screenshots?.rejected || 0)}</div>
          <div className="text-yellow-400 text-sm">{stats?.screenshots?.pending || 0} pending</div>
        </Card>
        <Card title="Withdrawals">
          <div className="text-2xl font-bold">{stats?.withdrawals?.total || 0}</div>
          <div className="text-yellow-400 text-sm">{stats?.withdrawals?.pending || 0} pending</div>
        </Card>
      </div>

      <Card title="Recent Users">
        <UsersTable items={users} />
      </Card>
    </div>
  );
};

ReactDOM.render(<DashboardApp />, document.getElementById('root'));
</script>
</body>
</html>
"""
    return HTMLResponse(content=html)

# -------------------------------- Webhook Setup & Handler --------------------------------

async def setup_telegram_webhook():
    if not wallet_bot or not wallet_bot.initialized or not wallet_bot.bot:
        logger.error("Cannot setup webhook: bot not initialized")
        return False
    try:
        await wallet_bot.bot.delete_webhook(drop_pending_updates=True)
        await asyncio.sleep(1)
        webhook_url = f"{RENDER_EXTERNAL_URL}/webhook"
        res = await wallet_bot.bot.set_webhook(
            url=webhook_url,
            allowed_updates=["message", "callback_query", "inline_query"],
            drop_pending_updates=True,
            max_connections=100,
            secret_token=WEBHOOK_SECRET_TOKEN  # optional
        )
        if res:
            info = await wallet_bot.bot.get_webhook_info()
            if info and info.url == webhook_url:
                wallet_bot.webhook_set = True
                logger.info("Webhook configured")
                return True
        wallet_bot.webhook_set = False
        logger.error("Failed to set webhook")
        return False
    except Exception as e:
        wallet_bot.webhook_set = False
        logger.error(f"Webhook setup error: {e}")
        return False

@app.post("/webhook")
async def telegram_webhook_handler(request: Request):
    try:
        if not wallet_bot or not wallet_bot.application or not wallet_bot.bot:
            logger.error("Webhook hit but bot not ready")
            return {"status": "error", "message": "Bot not initialized"}
        payload = await request.json()
        update = Update.de_json(payload, wallet_bot.bot)
        if update:
            await wallet_bot.application.process_update(update)
            return {"status": "ok"}
        return {"status": "error", "message": "Invalid update"}
    except Exception as e:
        logger.error(f"Webhook processing error: {e}")
        return {"status": "error"}

# -------------------------------- Startup & Shutdown -------------------------------------

@app.on_event("startup")
async def startup_event():
    logger.info("==== STARTUP: Enterprise Wallet Bot ====")

    logger.info("Step 1: Database")
    db_ok = await init_database()
    if not db_ok:
        logger.error("Database connection failed (continuing in degraded mode)")

    logger.info("Step 2: Telegram bot")
    try:
        if not BOT_TOKEN or BOT_TOKEN == "REPLACE_ME":
            logger.error("BOT_TOKEN missing; bot will not start")
            wallet_bot.initialized = False
        else:
            wallet_bot.bot = Bot(token=BOT_TOKEN)
            wallet_bot.application = ApplicationBuilder().token(BOT_TOKEN).build()
            # Setup handlers
            bot_impl = EnterpriseWalletBot()
            bot_impl.bot = wallet_bot.bot
            bot_impl.application = wallet_bot.application
            bot_impl.setup_handlers()
            # FIX: All awaits inside try
            await wallet_bot.bot.initialize()
            await wallet_bot.application.initialize()
            await wallet_bot.application.start()
            wallet_bot.initialized = True
            logger.info("Telegram bot initialized")
    except Exception as e:
        logger.error(f"Bot init error: {e}")
        wallet_bot.initialized = False

    logger.info("Step 3: Payment gateways")
    try:
        await payment_manager.initialize_gateways()
        logger.info("Payment gateways ready")
    except Exception as e:
        logger.error(f"Payment init error: {e}")

    logger.info("Step 4: Filesystem ensure")
    for d in ["uploads/screenshots", "uploads/campaign_images", "uploads/admin_images", "static"]:
        try:
            os.makedirs(d, exist_ok=True)
        except Exception as e:
            logger.error(f"Dir ensure failed for {d}: {e}")

    logger.info("Step 5: Webhook")
    if RENDER_EXTERNAL_URL and RENDER_EXTERNAL_URL != "https://example.com":
        ok = await setup_telegram_webhook()
        if not ok:
            logger.error("Webhook configuration failed")
    else:
        logger.warning("RENDER_EXTERNAL_URL not set; webhook skipped")

    logger.info("==== STARTUP COMPLETE ====")

@app.on_event("shutdown")
async def shutdown_event():
    logger.info("==== SHUTDOWN: Enterprise Wallet Bot ====")
    try:
        if wallet_bot and wallet_bot.application:
            await wallet_bot.application.stop()
            await wallet_bot.application.shutdown()
        if wallet_bot and wallet_bot.bot:
            await wallet_bot.bot.shutdown()
        logger.info("Bot shutdown complete")
    except Exception as e:
        logger.error(f"Bot shutdown error: {e}")
    try:
        if db_client:
            db_client.close()
            logger.info("DB connection closed")
    except Exception as e:
        logger.error(f"DB close error: {e}")
    logger.info("==== SHUTDOWN COMPLETE ====")

