# -------------------------------- Utility: Signed file download for screenshots ----------

@app.get("/api/admin/screenshots/{submission_id}/download")
async def admin_download_screenshot(submission_id: str, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        ss = await db.screenshots.find_one({"submission_id": submission_id})
        if not ss:
            raise HTTPException(status_code=404, detail="Not found")
        path = ss.get("file_path")
        if not path or not os.path.isfile(path):
            raise HTTPException(status_code=404, detail="File missing")
        filename = os.path.basename(path)
        return FileResponse(path, filename=filename, media_type="image/jpeg")
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Download screenshot error: {e}")
        raise HTTPException(status_code=500, detail="Failed to download")

# -------------------------------- Utility: Campaign banner upload (optional) -------------

@app.post("/api/admin/campaigns/{campaign_id}/banner")
async def admin_upload_campaign_banner(
    campaign_id: str,
    file: UploadFile = File(...),
    username: str = Depends(authenticate_admin)
):
    try:
        ext = os.path.splitext(file.filename or "")[1].lower()
        if ext not in [".jpg", ".jpeg", ".png", ".webp"]:
            raise HTTPException(status_code=400, detail="Unsupported file type")
        content = await file.read()
        os.makedirs("uploads/campaign_images", exist_ok=True)
        out_name = f"{campaign_id}_{uuid.uuid4().hex[:8]}{ext}"
        out_path = os.path.join("uploads/campaign_images", out_name)
        async with aiofiles.open(out_path, "wb") as f:
            await f.write(content)
        db = db_client.walletbot
        file_url = f"/uploads/campaign_images/{out_name}"
        await db.campaigns.update_one({"campaign_id": campaign_id}, {"$set": {"image_url": file_url, "updated_at": datetime.utcnow()}})
        return {"success": True, "image_url": file_url}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Campaign banner upload error: {e}")
        raise HTTPException(status_code=500, detail="Upload failed")

