# -------------------------------- In-memory logs ring buffer (optional) ------------------

class RingLogHandler(logging.Handler):
    def __init__(self, capacity=500):
        super().__init__()
        self.capacity = max(50, int(capacity))
        self.buffer = []
    def emit(self, record):
        try:
            msg = self.format(record)
            self.buffer.append({
                "t": datetime.utcnow().isoformat(),
                "lvl": record.levelname,
                "name": record.name,
                "msg": msg
            })
            if len(self.buffer) > self.capacity:
                self.buffer = self.buffer[-self.capacity:]
        except Exception:
            pass
    def get_logs(self):
        return list(self.buffer)

ring_handler = RingLogHandler(capacity=800)
ring_handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(name)s: %(message)s"))
logging.getLogger().addHandler(ring_handler)

@app.get("/api/admin/logs")
async def get_admin_logs(username: str = Depends(authenticate_admin)):
    try:
        return {"success": True, "data": ring_handler.get_logs()}
    except Exception as e:
        logger.error(f"Logs fetch error: {e}")
        return {"success": False, "data": []}

# -------------------------------- Users detail: helper endpoints -------------------------

@app.get("/api/admin/users/{user_id}/transactions")
async def admin_user_transactions(user_id: int, limit: int = 50, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        limit = min(200, max(1, int(limit)))
        cur = db.transactions.find({"user_id": user_id}).sort("created_at", -1).limit(limit)
        tx = await cur.to_list(length=limit)
        return {"success": True, "data": {"transactions": tx}}
    except Exception as e:
        logger.error(f"Admin user tx error: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch transactions")

@app.post("/api/admin/users/{user_id}/warn")
async def admin_user_warn(user_id: int, body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        reason = body.get("reason") or "policy violation"
        db = db_client.walletbot
        await db.users.update_one({"user_id": user_id}, {"$inc": {"warning_count": 1}, "$set": {"last_warning_reason": reason}})
        return {"success": True}
    except Exception as e:
        logger.error(f"Admin user warn error: {e}")
        raise HTTPException(status_code=500, detail="Failed to warn user")

# -------------------------------- Force-join channels: helper endpoints ------------------

@app.get("/api/admin/channels")
async def admin_channels_list(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cur = db.force_join_channels.find({}).sort("created_at", -1)
        items = await cur.to_list(length=1000)
        stats = await channel_manager.get_channels_statistics()
        return {"success": True, "data": {"channels": items, "stats": stats}}
    except Exception as e:
        logger.error(f"Channels list error: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch channels")

@app.post("/api/admin/channels/{channel_id}/refresh")
async def admin_channel_refresh(channel_id: str, username: str = Depends(authenticate_admin)):
    try:
        await channel_manager.update_channel_member_count(channel_id, wallet_bot.bot if wallet_bot else None)
        return {"success": True}
    except Exception as e:
        logger.error(f"Channel refresh error: {e}")
        raise HTTPException(status_code=500, detail="Failed to refresh channel")

