# -------------------------------- Gift Codes: Helper APIs --------------------------------

@app.get("/api/admin/gift-codes")
async def admin_list_gift_codes(
    page: int = 1,
    page_size: int = 20,
    search: str = "",
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        page = max(1, page); page_size = min(200, max(1, page_size))
        q = {}
        if search:
            q = {"$or": [
                {"code": {"$regex": str(search), "$options": "i"}},
                {"created_by": {"$regex": str(search), "$options": "i"}},
            ]}
        total = await db.gift_codes.count_documents(q)
        cursor = db.gift_codes.find(q).sort("created_at", -1).skip((page - 1) * page_size).limit(page_size)
        items = await cursor.to_list(length=page_size)
        stats = {
            "total": await db.gift_codes.count_documents({}),
            "active": await db.gift_codes.count_documents({"is_active": True}),
            "redeemed": await db.gift_codes.count_documents({"redeemed": True}),
        }
        return {"success": True, "data": {"gift_codes": items, "pagination": {"page": page, "page_size": page_size, "total": total}, "stats": stats}}
    except Exception as e:
        logger.error(f"Admin list gift codes error: {e}")
        raise HTTPException(status_code=500, detail="Failed to list gift codes")

@app.post("/api/admin/gift-codes")
async def admin_create_gift_code(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        code = (body.get("code") or str(uuid.uuid4())[:10].upper()).strip()
        amount = float(body.get("amount", 5.0))
        max_uses = int(body.get("max_uses", 1))
        expires_at = body.get("expires_at")  # ISO string optional
        doc = {
            "code": code,
            "amount": amount,
            "max_uses": max_uses,
            "uses": 0,
            "is_active": True,
            "redeemed": False,
            "created_by": username,
            "created_at": datetime.utcnow(),
            "expires_at": expires_at,
            "notes": body.get("notes") or ""
        }
        await db.gift_codes.insert_one(doc)
        return {"success": True, "data": doc}
    except Exception as e:
        logger.error(f"Create gift code error: {e}")
        if "duplicate" in str(e).lower():
            raise HTTPException(status_code=409, detail="Code already exists")
        raise HTTPException(status_code=500, detail="Failed to create gift code")

@app.put("/api/admin/gift-codes/{code}")
async def admin_update_gift_code(code: str, body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        update = {}
        for k in ["amount", "max_uses", "is_active", "notes", "expires_at"]:
            if k in body:
                update[k] = body[k]
        update["updated_at"] = datetime.utcnow()
        res = await db.gift_codes.update_one({"code": code}, {"$set": update})
        return {"success": res.matched_count > 0}
    except Exception as e:
        logger.error(f"Update gift code error: {e}")
        raise HTTPException(status_code=500, detail="Failed to update gift code")

@app.delete("/api/admin/gift-codes/{code}")
async def admin_delete_gift_code(code: str, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        res = await db.gift_codes.delete_one({"code": code})
        return {"success": res.deleted_count > 0}
    except Exception as e:
        logger.error(f"Delete gift code error: {e}")
        raise HTTPException(status_code=500, detail="Failed to delete gift code")

@app.post("/api/admin/gift-codes/{code}/toggle")
async def admin_toggle_gift_code(code: str, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        gc = await db.gift_codes.find_one({"code": code})
        if not gc:
            raise HTTPException(status_code=404, detail="Not found")
        new_state = not bool(gc.get("is_active", True))
        await db.gift_codes.update_one({"code": code}, {"$set": {"is_active": new_state, "updated_at": datetime.utcnow()}})
        return {"success": True, "is_active": new_state}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Toggle gift code error: {e}")
        raise HTTPException(status_code=500, detail="Failed to toggle gift code")

