@app.get("/api/admin/settings")
async def admin_get_settings(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type": "main_config"})
        return {"success": True, "data": cfg or {}}
    except Exception as e:
        logger.error(f"Get settings error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load settings")

@app.post("/api/admin/settings")
async def admin_update_settings(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type": "main_config"})
        if not cfg:
            cfg = {"type": "main_config", "created_at": datetime.utcnow()}
        # Only allow updating known fields safely
        allowed = {
            "screenshot_reward": float,
            "min_withdrawal": float,
            "referral_bonus": float,
            "payment_mode": str,
            "force_join_channels": list,
            "button_texts": dict,
            "button_responses": dict,
            "payment_gateways": dict
        }
        update = {}
        for k, caster in allowed.items():
            if k in body:
                try:
                    update[k] = caster(body[k]) if caster in (float, int, str) else body[k]
                except Exception:
                    update[k] = body[k]
        update["updated_at"] = datetime.utcnow()
        await db.bot_settings.update_one({"type": "main_config"}, {"$set": update}, upsert=True)
        return {"success": True}
    except Exception as e:
        logger.error(f"Update settings error: {e}")
        raise HTTPException(status_code=500, detail="Failed to update settings")

# -------------------------------- CSV Export Endpoints -----------------------------------

def _csv_line(fields: List[Any]) -> str:
    def esc(v):
        s = "" if v is None else str(v)
        s = s.replace('"', '""')
        return f'"{s}"'
    return ",".join(esc(f) for f in fields) + "\n"

@app.get("/api/admin/export/users.csv")
async def export_users_csv(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cur = db.users.find({}).sort("created_at", -1)
        rows = ["user_id,username,first_name,last_name,verified,wallet,total_earned,created_at,last_activity\n"]
        async for u in cur:
            rows.append(_csv_line([
                u.get("user_id"),
                u.get("username"),
                u.get("first_name"),
                u.get("last_name"),
                1 if u.get("device_verified") else 0,
                u.get("wallet_balance", 0.0),
                u.get("total_earned", 0.0),
                u.get("created_at"),
                u.get("last_activity")
            ]))
        data = "".join(rows).encode("utf-8")
        return StreamingResponse(io.BytesIO(data), media_type="text/csv", headers={"Content-Disposition": "attachment; filename=users.csv"})
    except Exception as e:
        logger.error(f"Export users csv error: {e}")
        raise HTTPException(status_code=500, detail="Failed to export users")

@app.get("/api/admin/export/transactions.csv")
async def export_transactions_csv(
    start: Optional[str] = None,
    end: Optional[str] = None,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        q = {}
        if start or end:
            q["created_at"] = {}
            if start:
                try: q["created_at"]["$gte"] = datetime.fromisoformat(start)
                except Exception: pass
            if end:
                try: q["created_at"]["$lte"] = datetime.fromisoformat(end)
                except Exception: pass
            if not q["created_at"]:
                q.pop("created_at", None)
        cur = db.transactions.find(q).sort("created_at", -1)
        rows = ["user_id,type,amount,description,status,created_at\n"]
        async for t in cur:
            rows.append(_csv_line([
                t.get("user_id"),
                t.get("type"),
                t.get("amount"),
                t.get("description"),
                t.get("status"),
                t.get("created_at")
            ]))
        data = "".join(rows).encode("utf-8")
        return StreamingResponse(io.BytesIO(data), media_type="text/csv", headers={"Content-Disposition": "attachment; filename=transactions.csv"})
    except Exception as e:
        logger.error(f"Export tx csv error: {e}")
        raise HTTPException(status_code=500, detail="Failed to export transactions")

