# ========================================================================================
#  Enterprise Wallet Bot - Single File Build (Fixed Minimal Edition)
#  CHUNK F: Transactions Explorer UI, Admin Roles (env), Support Tools, Audit Logs, Hardening
#  Notes:
#    - No refactor; builds on prior chunks
#    - Adds a second “auditor” user (optional, read-only) via environment variables
#    - Adds admin endpoints for DM resend, manual webhook test, and audit logging
# ========================================================================================

# -------------------------------- Admin Roles (env-based) --------------------------------
# Primary admin remains via ADMIN_USERNAME/ADMIN_PASSWORD.
# Optional auditor (read-only) can be enabled via:
#   AUDITOR_USERNAME, AUDITOR_PASSWORD
# These creds allow GET endpoints but block POST/PUT/DELETE.

AUDITOR_USERNAME = os.getenv("AUDITOR_USERNAME", "").strip()
AUDITOR_PASSWORD = os.getenv("AUDITOR_PASSWORD", "").strip()

def authenticate_any(credentials: HTTPBasicCredentials = Depends(basic_auth)) -> Dict[str, Any]:
    user = credentials.username
    pwd = credentials.password
    # primary admin
    if secrets.compare_digest(user, ADMIN_USERNAME) and secrets.compare_digest(pwd, ADMIN_PASSWORD):
        return {"role": "admin", "username": user}
    # optional auditor
    if AUDITOR_USERNAME and AUDITOR_PASSWORD:
        if secrets.compare_digest(user, AUDITOR_USERNAME) and secrets.compare_digest(pwd, AUDITOR_PASSWORD):
            return {"role": "auditor", "username": user}
    # deny
    raise HTTPException(status_code=401, detail="Unauthorized", headers={"WWW-Authenticate": "Basic"})

def require_admin(auth_ctx: Dict[str, Any]):
    if auth_ctx.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Forbidden (admin only)")

# -------------------------------- Audit Logs (DB + ring buffer) --------------------------
# We’ll add a DB collection 'audit_logs' to persist important admin actions.

async def write_audit_log(action: str, actor: str, meta: Dict[str, Any]):
    try:
        col = getattr(db_client.walletbot, "audit_logs") if db_client else None
        if col:
            await col.insert_one({
                "action": action,
                "actor": actor,
                "meta": meta,
                "created_at": datetime.utcnow()
            })
        logger.info(f"[AUDIT] {action} by {actor} :: {meta}")
    except Exception as e:
        logger.error(f"Audit log write error: {e}")

@app.get("/api/admin/audit-logs")
async def list_audit_logs(
    page: int = 1,
    page_size: int = 50,
    auth_ctx: Dict[str, Any] = Depends(authenticate_any)
):
    try:
        # auditor and admin can read
        db = db_client.walletbot
        page = max(1, page); page_size = min(200, max(1, page_size))
        total = await db.audit_logs.count_documents({})
        cur = db.audit_logs.find({}).sort("created_at", -1).skip((page-1)*page_size).limit(page_size)
        items = await cur.to_list(length=page_size)
        return {
            "success": True,
            "data": {
                "audit_logs": items,
                "pagination": {"page": page, "page_size": page_size, "total": total}
            }
        }
    except Exception as e:
        logger.error(f"List audit logs error: {e}")
        raise HTTPException(status_code=500, detail="Failed to list audit logs")

# -------------------------------- Support Tools (DM resend, webhook poke) ----------------

@app.post("/api/admin/support/resend-verified-dm/{user_id}")
async def support_resend_verified_dm(
    user_id: int,
    body: Dict[str, Any],
    auth_ctx: Dict[str, Any] = Depends(authenticate_any)
):
    try:
        require_admin(auth_ctx)
        if not wallet_bot or not wallet_bot.initialized or not wallet_bot.bot:
            raise HTTPException(status_code=503, detail="Bot not ready")
        msg = body.get("message") or "Your device is verified. Enjoy full access!"
        await wallet_bot.bot.send_message(chat_id=user_id, text=msg)
        await write_audit_log("resend_verified_dm", auth_ctx["username"], {"user_id": user_id, "message": msg})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Resend DM error: {e}")
        raise HTTPException(status_code=500, detail="DM failed")

@app.post("/api/admin/support/ping-webhook")
async def support_ping_webhook(auth_ctx: Dict[str, Any] = Depends(authenticate_any)):
    try:
        require_admin(auth_ctx)
        # If bot/app ready, just respond success; actual inbound webhook depends on Telegram servers
        ready = bool(wallet_bot and wallet_bot.initialized)
        await write_audit_log("ping_webhook", auth_ctx["username"], {"bot_initialized": ready})
        return {"success": True, "bot_initialized": ready, "webhook_set": bool(wallet_bot and wallet_bot.webhook_set)}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Ping webhook error: {e}")
        raise HTTPException(status_code=500, detail="Webhook ping failed")

# -------------------------------- Transactions Explorer APIs -----------------------------

@app.get("/api/admin/transactions")
async def admin_list_transactions(
    page: int = 1,
    page_size: int = 50,
    type: Optional[str] = None,
    user_id: Optional[int] = None,
    start: Optional[str] = None,
    end: Optional[str] = None,
    auth_ctx: Dict[str, Any] = Depends(authenticate_any)
):
    try:
        db = db_client.walletbot
        page = max(1, page); page_size = min(200, max(1, page_size))
        q = {}
        if type:
            q["type"] = type
        if user_id:
            q["user_id"] = int(user_id)
        if start or end:
            q["created_at"] = {}
            if start:
                try: q["created_at"]["$gte"] = datetime.fromisoformat(start)
                except Exception: pass
            if end:
                try: q["created_at"]["$lte"] = datetime.fromisoformat(end)
                except Exception: pass
            if not q["created_at"]:
                q.pop("created_at", None)
        total = await db.transactions.count_documents(q)
        cur = db.transactions.find(q).sort("created_at", -1).skip((page-1)*page_size).limit(page_size)
        items = await cur.to_list(length=page_size)
        return {"success": True, "data": {"transactions": items, "pagination": {"page": page, "page_size": page_size, "total": total}}}
    except Exception as e:
        logger.error(f"Transactions list error: {e}")
        raise HTTPException(status_code=500, detail="Failed to list transactions")

