# ========================================================================================
#  Enterprise Wallet Bot - Single File Build (Fixed Minimal Edition)
#  CHUNK G: Advanced User Search, Batch Actions, Screenshot Preview Modal, Light Rate Limiting
#  Notes:
#    - No refactor; builds on previous chunks and collections
#    - Adds a protective rate limit (very light, in-memory) for a few public endpoints
#    - Batch actions call existing admin APIs
# ========================================================================================

# -------------------------------- Light Rate Limiting (in-memory) ------------------------
# Very lightweight, per-IP windowed counter. Only for a couple of public endpoints.

from collections import defaultdict, deque

RATE_LIMIT_CONFIG = {
    "verify_device": {"window_sec": 60, "max_calls": 25},       # /api/verify-device
    "withdraw": {"window_sec": 60, "max_calls": 20},            # /api/withdraw
    "submit_screenshot": {"window_sec": 60, "max_calls": 30},   # /api/campaigns/.../submit
}
_rate_state = {
    "verify_device": defaultdict(lambda: deque()),
    "withdraw": defaultdict(lambda: deque()),
    "submit_screenshot": defaultdict(lambda: deque()),
}

def _rate_check(kind: str, ip: str) -> bool:
    conf = RATE_LIMIT_CONFIG.get(kind)
    if not conf:
        return True
    now = time.time()
    dq = _rate_state[kind][ip]
    # purge old
    while dq and now - dq[0] > conf["window_sec"]:
        dq.popleft()
    if len(dq) >= conf["max_calls"]:
        return False
    dq.append(now)
    return True

def _get_ip(request: Request) -> str:
    try:
        fwd = request.headers.get("x-forwarded-for", "")
        if fwd:
            # may contain list of IPs
            ip = fwd.split(",").strip()
            return ip or request.client.host
        return request.client.host
    except Exception:
        return "unknown"

# Wrap public endpoints: verify-device, withdraw, submit screenshot
# We will create thin wrappers that enforce rate limit and then delegate.

@app.post("/api/verify-device-rl")
async def verify_device_rate_limited(request: Request):
    ip = _get_ip(request)
    if not _rate_check("verify_device", ip):
        raise HTTPException(status_code=429, detail="Too many requests. Please try again in a minute.")
    # forward to original endpoint handler
    form = await request.form()
    return await verify_device(
        user_id=int(form.get("user_id")),
        screen_resolution=form.get("screen_resolution"),
        user_agent_hash=form.get("user_agent_hash"),
        timezone_offset=form.get("timezone_offset"),
        platform=form.get("platform"),
        language=form.get("language"),
        canvas_hash=form.get("canvas_hash"),
        webgl_hash=form.get("webgl_hash"),
        hardware_concurrency=form.get("hardware_concurrency"),
        memory=form.get("memory"),
        touch_support=form.get("touch_support"),
        color_depth=form.get("color_depth"),
        screen_orientation=form.get("screen_orientation"),
        user_agent=form.get("user_agent", "unknown"),
        ip_address=form.get("ip_address", ip),
    )

@app.post("/api/withdraw-rl")
async def request_withdrawal_rate_limited(request: Request):
    ip = _get_ip(request)
    if not _rate_check("withdraw", ip):
        raise HTTPException(status_code=429, detail="Too many requests. Please try again later.")
    form = await request.form()
    return await request_withdrawal(
        user_id=int(form.get("user_id")),
        amount=float(form.get("amount")),
        method=form.get("method"),
        upi_id=form.get("upi_id"),
        account_name=form.get("account_name"),
        account_number=form.get("account_number"),
        ifsc_code=form.get("ifsc_code"),
        mobile_number=form.get("mobile_number"),
    )

@app.post("/api/campaigns/{campaign_id}/submit-rl")
async def submit_screenshot_rate_limited(campaign_id: str, request: Request):
    ip = _get_ip(request)
    if not _rate_check("submit_screenshot", ip):
        raise HTTPException(status_code=429, detail="Submission rate exceeded. Please wait.")
    form = await request.form()
    user_id = int(form.get("user_id"))
    file = await request.form()
    fileobj = form.get("file")
    if not hasattr(fileobj, "read"):
        raise HTTPException(status_code=400, detail="File missing")
    content = await fileobj.read()
    return await submit_screenshot_api(campaign_id, user_id=user_id, file=UploadFile(filename=getattr(fileobj, "filename", "upload.jpg")))

