@app.post("/api/admin/export/users-selected.csv")
async def export_selected_users_csv(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        ids = body.get("user_ids") or []
        if not isinstance(ids, list) or not ids:
            raise HTTPException(status_code=400, detail="No user_ids provided")
        q = {"user_id": {"$in": [int(x) for x in ids if isinstance(x, (int, str))]}}
        cur = db.users.find(q)
        rows = ["user_id,username,first_name,last_name,verified,wallet,total_earned,created_at,last_activity\n"]
        async for u in cur:
            rows.append(",".join([
                str(u.get("user_id", "")),
                '"' + str((u.get("username") or "")).replace('"', '""') + '"',
                '"' + str((u.get("first_name") or "")).replace('"', '""') + '"',
                '"' + str((u.get("last_name") or "")).replace('"', '""') + '"',
                "1" if u.get("device_verified") else "0",
                str(u.get("wallet_balance", 0.0)),
                str(u.get("total_earned", 0.0)),
                '"' + str(u.get("created_at", "")) + '"',
                '"' + str(u.get("last_activity", "")) + '"'
            ]) + "\n")
        data = "".join(rows).encode("utf-8")
        return StreamingResponse(io.BytesIO(data), media_type="text/csv", headers={"Content-Disposition": "attachment; filename=users_selected.csv"})
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Export selected users csv error: {e}")
        raise HTTPException(status_code=500, detail="Failed to export selected users")

# -------------------------------- Advanced Users Search API ------------------------------

@app.get("/api/admin/users-search")
async def admin_users_search(
    page: int = 1,
    page_size: int = 50,
    verified: Optional[str] = None,  # 'true', 'false', or None
    banned: Optional[str] = None,    # 'true', 'false', or None
    start: Optional[str] = None,     # ISO
    end: Optional[str] = None,       # ISO
    min_balance: Optional[float] = None,
    max_balance: Optional[float] = None,
    username_or_code: Optional[str] = None,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        page = max(1, page); page_size = min(200, max(1, page_size))
        q = {}
        # boolean filters
        if verified in ("true", "false"):
            q["device_verified"] = True if verified == "true" else False
        if banned in ("true", "false"):
            q["is_banned"] = True if banned == "true" else False
        # date range by created_at
        if start or end:
            q["created_at"] = {}
            if start:
                try: q["created_at"]["$gte"] = datetime.fromisoformat(start)
                except Exception: pass
            if end:
                try: q["created_at"]["$lte"] = datetime.fromisoformat(end)
                except Exception: pass
            if not q["created_at"]:
                q.pop("created_at", None)
        # balance range
        bal = {}
        if isinstance(min_balance, (int, float)):
            bal["$gte"] = float(min_balance)
        if isinstance(max_balance, (int, float)):
            bal["$lte"] = float(max_balance)
        if bal:
            q["wallet_balance"] = bal
        # username or referral_code fuzzy
        if username_or_code:
            q["$or"] = [
                {"username": {"$regex": str(username_or_code), "$options": "i"}},
                {"referral_code": {"$regex": str(username_or_code), "$options": "i"}}
            ]
        total = await db.users.count_documents(q)
        cur = db.users.find(q).sort("created_at", -1).skip((page-1)*page_size).limit(page_size)
        users = await cur.to_list(length=page_size)
        return {"success": True, "data": {"users": users, "pagination": {"page": page, "page_size": page_size, "total": total}}}
    except Exception as e:
        logger.error(f"Advanced users search error: {e}")
        raise HTTPException(status_code=500, detail="Failed to search users")

