@app.get("/admin/screenshots-inline")
async def admin_screenshots_inline_page():
    html = """
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Admin - Screenshots (Inline Preview)</title>
<link href="https://unpkg.com/tailwindcss@^2/dist/tailwind.min.css" rel="stylesheet">
<script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
<script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
<script src="https://unpkg.com/@babel/standalone@7.22.5/babel.min.js"></script>
<style>
  body { background: #0f172a; color: #e2e8f0; }
  .card { background: #111827; border: 1px solid rgba(148,163,184,.12); }
  .btn { padding: 6px 10px; border-radius: 8px; }
  .btn-green { background: #16a34a; color: white; }
  .btn-red { background: #dc2626; color: white; }
  .overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.7); display:flex; align-items:center; justify-content:center; z-index: 50; }
  .modal { background:#0b1220; border:1px solid rgba(148,163,184,.12); border-radius: 12px; max-width: 90vw; max-height: 90vh; overflow:auto; }
  .modal img { max-width: 90vw; max-height: 80vh; display:block; }
</style>
</head>
<body>
<div id="root" class="p-6"></div>
<script type="text/babel">
const { useState, useEffect, useCallback } = React;

const useAPI = () => {
  const getAuth = () => sessionStorage.getItem('adminAuth');
  const request = useCallback(async (url, options = {}) => {
    const auth = getAuth(); if(!auth){ window.location.href = '/admin'; return null; }
    const resp = await fetch(url, { ...options, headers: { 'Authorization': 'Basic ' + auth, 'Content-Type': 'application/json', ...(options.headers||{}) }});
    if(resp.status === 401){ sessionStorage.removeItem('adminAuth'); window.location.href = '/admin'; return null; }
    if(!resp.ok){ throw new Error('HTTP ' + resp.status); }
    return await resp.json();
  }, []);
  return {
    getScreenshots: (p={}) => request('/api/admin/screenshots?' + new URLSearchParams(p)),
    approve: (id, notes='') => request('/api/admin/screenshots/' + id + '/approve', { method:'POST', body: JSON.stringify({ admin_notes: notes })}),
    reject: (id, notes='') => request('/api/admin/screenshots/' + id + '/reject', { method:'POST', body: JSON.stringify({ admin_notes: notes })}),
  };
};

const App = () => {
  const api = useAPI();
  const [items, setItems] = useState([]);
  const [status, setStatus] = useState('pending');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [pageSize, setPageSize] = useState(20);
  const [preview, setPreview] = useState(null); // { submission_id, src }

  const load = useCallback(async () => {
    try {
      const r = await api.getScreenshots({ status, page, page_size: pageSize });
      setItems(r?.data?.screenshots || []);
      setTotal(r?.data?.pagination?.total || 0);
    } catch (e) {
      alert('Failed to load screenshots');
    }
  }, [status, page, pageSize]);

  useEffect(() => { load(); }, [load]);

  const openPreview = (s) => {
    // We rely on the same download endpoint, but to show in modal we can set the src relative.
    setPreview({ submission_id: s.submission_id, src: '/api/admin/screenshots/' + s.submission_id + '/download' });
  };

  const approve = async (id) => { try { await api.approve(id); await load(); } catch { alert('Approve failed'); } };
  const reject = async (id) => { try { await api.reject(id); await load(); } catch { alert('Reject failed'); } };

  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  return (
    <div className="max-w-7xl mx-auto">
      <div className="flex items-center justify-between mb-4">
        <h1 className="text-2xl font-bold">Screenshots (Inline Preview)</h1>
        <a className="text-blue-400 underline" href="/admin/index-pro">Back to Admin Index</a>
      </div>
      <div className="flex items-center gap-2 mb-3">
        <select value={status} onChange={e=>setStatus(e.target.value)} className="bg-gray-800 border border-gray-700 rounded px-2 py-1">
          <option value="pending">Pending</option>
          <option value="approved">Approved</option>
          <option value="rejected">Rejected</option>
          <option value="all">All</option>
        </select>
      </div>

      <div className="overflow-x-auto">
        <table className="min-w-full text-sm">
          <thead className="bg-gray-900 text-gray-300">
            <tr>
              <th className="px-3 py-2 text-left">Submission</th>
              <th className="px-3 py-2 text-left">User</th>
              <th className="px-3 py-2 text-left">Campaign</th>
              <th className="px-3 py-2 text-left">Status</th>
              <th className="px-3 py-2 text-left">Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map(s => (
              <tr key={s.submission_id} className="border-b border-gray-800">
                <td className="px-3 py-2">{s.submission_id}</td>
                <td className="px-3 py-2">{s.user_id}</td>
                <td className="px-3 py-2">{s.campaign_id}</td>
                <td className="px-3 py-2">{s.status}</td>
                <td className="px-3 py-2">
                  <button className="btn mr-2" onClick={() => openPreview(s)}>Preview</button>
                  <button className="btn btn-green mr-2" onClick={() => approve(s.submission_id)}>Approve</button>
                  <button className="btn btn-red" onClick={() => reject(s.submission_id)}>Reject</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {preview && (
        <div className="overlay" onClick={() => setPreview(null)}>
          <div className="modal p-4" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-3">
              <div className="text-lg font-semibold">Submission: {preview.submission_id}</div>
              <button className="btn" onClick={() => setPreview(null)}>Close</button>
            </div>
            <img src={preview.src} alt="screenshot" />
          </div>
        </div>
      )}

      <div className="flex items-center justify-between mt-4">
        <div>Page {page} of {totalPages} (Total: {total})</div>
        <div className="flex items-center gap-2">
          <button className="btn" disabled={page<=1} onClick={()=>setPage(p=>Math.max(1,p-1))}>Prev</button>
          <button className="btn" disabled={page>=totalPages} onClick={()=>setPage(p=>Math.min(totalPages,p+1))}>Next</button>
        </div>
      </div>
    </div>
  );
};

ReactDOM.render(<App />, document.getElementById('root'));
</script>
</body>
</html>
"""
    return HTMLResponse(content=html)

