@app.get("/api/admin/settings/backup")
async def admin_settings_backup(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
        # Strip Mongo _id for export
        cfg.pop("_id", None)
        payload = json.dumps(cfg, default=str, indent=2).encode("utf-8")
        return StreamingResponse(io.BytesIO(payload), media_type="application/json",
                                 headers={"Content-Disposition": "attachment; filename=settings_backup.json"})
    except Exception as e:
        logger.error(f"Settings backup error: {e}")
        raise HTTPException(status_code=500, detail="Backup failed")

@app.post("/api/admin/settings/restore")
async def admin_settings_restore(file: UploadFile = File(...), username: str = Depends(authenticate_admin)):
    try:
        content = await file.read()
        data = json.loads(content.decode("utf-8"))
        if not isinstance(data, dict):
            raise HTTPException(status_code=400, detail="Invalid JSON structure")
        data["type"] = "main_config"
        data["updated_at"] = datetime.utcnow()
        # Basic validation for key sections
        for must in ["button_texts", "button_responses", "payment_gateways"]:
            if must not in data:
                data[must] = {}
        db = db_client.walletbot
        await db.bot_settings.update_one({"type": "main_config"}, {"$set": data}, upsert=True)
        await write_audit_log("settings_restore", username, {"filename": file.filename})
        return {"success": True, "message": "Settings restored"}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Settings restore error: {e}")
        raise HTTPException(status_code=500, detail="Restore failed")

