# -------------------------------- Background Task Runner (in-memory) --------------------

class TaskRunner:
    def __init__(self):
        self.tasks = []  # list of (name, interval_sec, last_run_ts, coro_func)
        self.running = False

    def add_task(self, name: str, interval_sec: int, coro_func):
        self.tasks.append({"name": name, "interval": int(interval_sec), "last": 0.0, "func": coro_func})

    async def run_forever(self):
        self.running = True
        logger.info("Background TaskRunner started")
        try:
            while self.running:
                now = time.time()
                for t in self.tasks:
                    if now - t["last"] >= t["interval"]:
                        t["last"] = now
                        try:
                            await t["func"]()
                        except Exception as e:
                            logger.error(f"Task '{t['name']}' error: {e}")
                await asyncio.sleep(2)
        except asyncio.CancelledError:
            logger.info("TaskRunner cancelled")
        except Exception as e:
            logger.error(f"TaskRunner fatal: {e}")
        finally:
            self.running = False

task_runner = TaskRunner()
_task_runner_task = None

async def cleanup_expired_gift_codes():
    try:
        db = db_client.walletbot if db_client else None
        if not db:
            return
        now = datetime.utcnow()
        # Deactivate expired active gift codes (expires_at < now)
        res = await db.gift_codes.update_many(
            {"is_active": True, "expires_at": {"$lt": now.isoformat()}},
            {"$set": {"is_active": False, "updated_at": now, "expired_auto": True}}
        )
        if res and res.modified_count:
            logger.info(f"Cleanup: deactivated {res.modified_count} expired gift codes")
    except Exception as e:
        logger.error(f"Cleanup gift codes error: {e}")

async def deactivate_stale_campaigns():
    try:
        db = db_client.walletbot if db_client else None
        if not db:
            return
        now = datetime.utcnow()
        cutoff = now - timedelta(days=120)  # if not updated in 120 days, deactivate
        res = await db.campaigns.update_many(
            {"active": True, "updated_at": {"$lt": cutoff}},
            {"$set": {"active": False, "updated_at": now, "auto_deactivated": True}}
        )
        if res and res.modified_count:
            logger.info(f"Cleanup: auto-deactivated {res.modified_count} stale campaigns")
    except Exception as e:
        logger.error(f"Cleanup campaigns error: {e}")

# Register tasks (every 10 minutes for gift codes; every 60 minutes for campaigns)
task_runner.add_task("cleanup_expired_gift_codes", interval_sec=600, coro_func=cleanup_expired_gift_codes)
task_runner.add_task("deactivate_stale_campaigns", interval_sec=3600, coro_func=deactivate_stale_campaigns)

# Hook into startup/shutdown without refactor; create separate startup handlers if needed

@app.on_event("startup")
async def _start_task_runner():
    global _task_runner_task
    try:
        loop = asyncio.get_event_loop()
        _task_runner_task = loop.create_task(task_runner.run_forever())
    except Exception as e:
        logger.error(f"Failed to start TaskRunner: {e}")

@app.on_event("shutdown")
async def _stop_task_runner():
    global _task_runner_task
    try:
        if _task_runner_task:
            _task_runner_task.cancel()
    except Exception as e:
        logger.error(f"Failed to cancel TaskRunner: {e}")

