# --------------------------------- Referral Tree APIs ------------------------------------

# Assumes users collection has 'referred_by' and 'referral_code'
# Build a simple adjacency data structure for admin viewing.

@app.get("/api/admin/referrals/{user_id}")
async def get_user_referrals(
    user_id: int,
    depth: int = 2,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        depth = max(1, min(5, depth))
        user = await db.users.find_one({"user_id": user_id}, {"_id": 0, "user_id": 1, "username": 1, "referral_code": 1})
        if not user:
            raise HTTPException(status_code=404, detail="User not found")

        result = {"root": user, "tree": []}
        current_codes = [user.get("referral_code")]
        visited = set([user_id])

        for level in range(depth):
            if not current_codes:
                break
            cursor = db.users.find({"referred_by": {"$in": current_codes}}, {"_id": 0, "user_id": 1, "username": 1, "referral_code": 1, "referred_by": 1})
            children = await cursor.to_list(length=10000)
            result["tree"].append(children)
            current_codes = [c.get("referral_code") for c in children if c.get("referral_code")]
            for c in children:
                visited.add(c.get("user_id"))
        return {"success": True, "data": result}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Referrals API error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build referral tree")

