# ------------------------------ Campaign Performance APIs --------------------------------

@app.get("/api/admin/campaigns/performance")
async def campaign_performance(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(1, min(180, days))
        since = datetime.utcnow() - timedelta(days=days)
        # Aggregate screenshots by day and status
        pipeline = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {
                "_id": {
                    "day": {"$dateToString": {"format": "%Y-%m-%d", "date": "$created_at"}},
                    "status": "$status"
                },
                "count": {"$sum": 1}
            }},
            {"$sort": {"_id.day": 1}}
        ]
        ss_col = db.screenshots
        agg = ss_col.aggregate(pipeline)
        rows = await agg.to_list(length=5000)
        # Also campaign totals
        curs = db.campaigns.find({}, {"_id": 0, "campaign_id": 1, "name": 1, "total_submissions": 1, "approved_submissions": 1, "rejected_submissions": 1})
        campaigns = await curs.to_list(length=5000)
        return {"success": True, "data": {"timeseries": rows, "campaigns": campaigns}}
    except Exception as e:
        logger.error(f"Campaign performance error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute performance")

