# ------------------------------ Screenshot Dedup Report (read-only) ----------------------

# We compute a hash for each screenshot filename to detect duplicates by content path/name.
# For a more robust dedup you could hash file bytes, but we’ll do a DB-driven lightweight report.

@app.get("/api/admin/screenshots/dedup-report")
async def screenshots_dedup_report(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cur = db.screenshots.find({}, {"_id": 0, "submission_id": 1, "filename": 1, "user_id": 1, "campaign_id": 1, "created_at": 1})
        items = await cur.to_list(length=50000)
        from collections import defaultdict
        groups = defaultdict(list)
        for it in items:
            key = (it.get("filename") or "").lower().strip()
            groups[key].append(it)
        # Filter groups with count > 1
        dup = {k: v for k, v in groups.items() if k and len(v) > 1}
        # Return a compact structure
        report = [{"filename": k, "count": len(v), "items": v} for k, v in sorted(dup.items(), key=lambda x: -len(x[1]))]
        return {"success": True, "data": {"duplicates": report, "total_groups": len(report)}}
    except Exception as e:
        logger.error(f"Dedup report error: {e}")
        raise HTTPException(status_code=500, detail="Failed to generate report")

