# ------------------------------ Announcements Broadcast (admin-only) ---------------------

# Sends a simple text announcement to verified users in small batches to avoid hitting rate limits.

@app.post("/api/admin/announce")
async def admin_broadcast_announcement(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        if not wallet_bot or not wallet_bot.initialized or not wallet_bot.bot:
            raise HTTPException(status_code=503, detail="Bot not ready")
        message = (body.get("message") or "").strip()
        limit = int(body.get("limit", 1000))
        batch_size = int(body.get("batch_size", 25))
        sleep_ms = int(body.get("sleep_ms", 400))
        if not message:
            raise HTTPException(status_code=400, detail="Message required")

        db = db_client.walletbot
        # Target verified, active, not banned
        cursor = db.users.find({"device_verified": True, "is_active": True, "is_banned": False}, {"_id": 0, "user_id": 1})
        count = 0; success = 0; failed = 0
        async for u in cursor:
            if count >= limit:
                break
            uid = int(u.get("user_id"))
            try:
                await wallet_bot.bot.send_message(chat_id=uid, text=message)
                success += 1
            except Exception as e:
                failed += 1
                if failed % 50 == 0:
                    logger.warning(f"Broadcast failures so far: {failed} (last: {e})")
            count += 1
            if count % batch_size == 0:
                await asyncio.sleep(sleep_ms/1000.0)
        await write_audit_log("announcement_broadcast", username, {"message_len": len(message), "attempted": count, "success": success, "failed": failed})
        return {"success": True, "attempted": count, "delivered": success, "failed": failed}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Announcement error: {e}")
        raise HTTPException(status_code=500, detail="Broadcast failed")

