# -------------------------------- Config Helpers ----------------------------------------

async def get_main_config() -> Dict[str, Any]:
    try:
        if not db_client:
            return {}
        cfg = await db_client.walletbot.bot_settings.find_one({"type": "main_config"}) or {}
        return cfg
    except Exception as e:
        logger.error(f"get_main_config error: {e}")
        return {}

def mask_token(token: Optional[str]) -> str:
    if not token or len(token) < 8:
        return "********"
    return token[:4] + "*" * (len(token) - 8) + token[-4:]

# -------------------------------- Security Audits APIs ----------------------------------

@app.get("/api/admin/security/audits")
async def admin_security_audits(
    page: int = 1,
    page_size: int = 50,
    only_recent_days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Returns recent security-related datapoints:
    - Recent bans (users with is_banned true updated recently)
    - Device verification conflicts (same fingerprint mapped to >1, but we guard uniqueness anyway)
    - Warning spikes (users with warning_count >= 3)
    """
    try:
        db = db_client.walletbot
        page = max(1, page); page_size = min(200, max(1, page_size))
        since = datetime.utcnow() - timedelta(days=max(1, min(365, only_recent_days)))

        # Recent bans
        banned_cur = db.users.find({"is_banned": True, "last_activity": {"$gte": since}}).sort("last_activity", -1).limit(200)
        banned = await banned_cur.to_list(length=200)

        # Warnings (3 or more)
        warn_cur = db.users.find({"warning_count": {"$gte": 3}}).sort("warning_count", -1).limit(200)
        warned = await warn_cur.to_list(length=200)

        # Fingerprint duplicates (unlikely if unique index is present, but report anyway)
        dev = db.device_fingerprints
        pipe = [
            {"$group": {"_id": "$fingerprint", "count": {"$sum": 1}, "users": {"$addToSet": "$user_id"}}},
            {"$match": {"count": {"$gt": 1}}},
            {"$sort": {"count": -1}},
            {"$limit": 200}
        ]
        dup = await dev.aggregate(pipe).to_list(length=200)

        # Summaries
        summary = {
            "recent_banned_count": len(banned),
            "warned_users_count": len(warned),
            "duplicate_fingerprints_groups": len(dup),
        }

        # simple pagination only for banned list (primary)
        total_banned = await db.users.count_documents({"is_banned": True, "last_activity": {"$gte": since}})
        banned_page = await db.users.find({"is_banned": True, "last_activity": {"$gte": since}})\
            .sort("last_activity", -1)\
            .skip((page-1)*page_size)\
            .limit(page_size).to_list(length=page_size)

        return {
            "success": True,
            "data": {
                "summary": summary,
                "banned": banned_page,
                "banned_pagination": {"page": page, "page_size": page_size, "total": total_banned},
                "warned": warned[:100],
                "duplicate_fingerprints": dup
            }
        }
    except Exception as e:
        logger.error(f"Security audits error: {e}")
        raise HTTPException(status_code=500, detail="Failed to generate security audits")

