# -------------------------------- Wallet Reconciliation Report ---------------------------

@app.get("/api/admin/reconciliation")
async def admin_wallet_reconciliation(
    page: int = 1,
    page_size: int = 200,
    username: str = Depends(authenticate_admin)
):
    """
    Compares user.wallet_balance vs. sum of transactions amounts for that user (last 12 months).
    Report-only: does not modify anything.
    """
    try:
        db = db_client.walletbot
        page = max(1, page); page_size = min(500, max(50, page_size))
        since = datetime.utcnow() - timedelta(days=365)
        q = {}
        total = await db.users.count_documents(q)
        users = await db.users.find(q).sort("created_at", -1).skip((page-1)*page_size).limit(page_size)\
            .to_list(length=page_size)

        report = []
        for u in users:
            uid = u.get("user_id")
            wb = float(u.get("wallet_balance", 0.0) or 0.0)
            tx_cur = db.transactions.find({"user_id": uid, "created_at": {"$gte": since}}, {"_id": 0, "amount": 1})
            total_tx = 0.0
            async for t in tx_cur:
                try:
                    total_tx += float(t.get("amount", 0.0) or 0.0)
                except Exception:
                    pass
            delta = round(wb - total_tx, 2)
            report.append({
                "user_id": uid,
                "username": u.get("username"),
                "wallet_balance": wb,
                "tx_sum_12m": round(total_tx, 2),
                "delta": delta
            })
        # Sort by absolute delta desc (largest mismatch first)
        report.sort(key=lambda r: abs(r.get("delta", 0.0)), reverse=True)
        return {"success": True, "data": {"report": report, "pagination": {"page": page, "page_size": page_size, "total": total}}}
    except Exception as e:
        logger.error(f"Reconciliation error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build reconciliation report")

