async def qa_tools_enabled() -> bool:
    cfg = await get_main_config()
    return bool((cfg.get("qa_tools_enabled") or False) or (cfg.get("payment_gateways", {}).get("razorpay", {}).get("test_mode", True)))

@app.post("/api/admin/qa/seed-users")
async def qa_seed_users(
    count: int = 50,
    prefix: str = "qa_user_",
    username: str = Depends(authenticate_admin)
):
    """
    Seeds N lightweight users (unverified) for QA. Only in test mode (qa_tools_enabled).
    """
    try:
        if not await qa_tools_enabled():
            raise HTTPException(status_code=403, detail="QA tools are disabled in production")
        db = db_client.walletbot
        count = max(1, min(500, int(count)))
        docs = []
        base = int(time.time())
        for i in range(count):
            uid = base * 1000 + i
            docs.append({
                "user_id": uid,
                "username": f"{prefix}{i}",
                "first_name": "QA",
                "last_name": f"User{i}",
                "created_at": datetime.utcnow(),
                "last_activity": datetime.utcnow(),
                "device_verified": False,
                "verification_status": "pending",
                "wallet_balance": 0.0,
                "total_earned": 0.0,
                "is_active": True,
                "is_banned": False,
                "warning_count": 0
            })
        if docs:
            await db.users.insert_many(docs, ordered=False)
        await write_audit_log("qa_seed_users", username, {"count": count})
        return {"success": True, "inserted": len(docs)}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"QA seed users error: {e}")
        raise HTTPException(status_code=500, detail="Seeding failed")

@app.post("/api/admin/qa/simulate-approvals")
async def qa_simulate_approvals(
    campaign_id: str,
    limit: int = 50,
    username: str = Depends(authenticate_admin)
):
    """
    Randomly approves up to N pending screenshots in test mode.
    """
    try:
        if not await qa_tools_enabled():
            raise HTTPException(status_code=403, detail="QA tools are disabled in production")
        db = db_client.walletbot
        limit = max(1, min(200, int(limit)))
        cur = db.screenshots.find({"campaign_id": campaign_id, "status": "pending"}).limit(limit)
        items = await cur.to_list(length=limit)
        ok = 0
        for it in items:
            sid = it.get("submission_id")
            res = await screenshot_manager.approve_screenshot(sid, admin_notes="QA auto approve")
            if res.get("success"):
                ok += 1
        await write_audit_log("qa_simulate_approvals", username, {"campaign_id": campaign_id, "approved": ok})
        return {"success": True, "approved": ok, "requested": len(items)}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"QA simulate approvals error: {e}")
        raise HTTPException(status_code=500, detail="QA approvals failed")

