@app.get("/api/admin/ratelimits")
async def admin_ratelimit_snapshot(username: str = Depends(authenticate_admin)):
    try:
        snap = {}
        now = time.time()
        for kind, store in _rate_state.items():
            items = []
            for ip, dq in store.items():
                # copy only fresh counts
                fresh = [t for t in list(dq) if now - t <= RATE_LIMIT_CONFIG[kind]["window_sec"]]
                if fresh:
                    items.append({"ip": ip, "count": len(fresh)})
            items.sort(key=lambda x: -x["count"])
            snap[kind] = items[:25]
        return {"success": True, "data": snap}
    except Exception as e:
        logger.error(f"Ratelimit snapshot error: {e}")
        raise HTTPException(status_code=500, detail="Failed to get ratelimit snapshot")

