# -------------------------------- Maintenance Mode (read-only toggle) --------------------

_maintenance_mode = {"enabled": False, "reason": "Maintenance in progress"}

@app.get("/api/admin/maintenance")
async def get_maintenance_mode(username: str = Depends(authenticate_admin)):
    return {"success": True, "data": _maintenance_mode}

@app.post("/api/admin/maintenance/toggle")
async def toggle_maintenance_mode(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        enabled = bool(body.get("enabled", False))
        reason = (body.get("reason") or "Maintenance in progress").strip()
        _maintenance_mode["enabled"] = enabled
        _maintenance_mode["reason"] = reason
        await write_audit_log("maintenance_toggle", username, {"enabled": enabled, "reason": reason})
        return {"success": True, "data": _maintenance_mode}
    except Exception as e:
        logger.error(f"Maintenance toggle error: {e}")
        raise HTTPException(status_code=500, detail="Failed to toggle maintenance mode")

def maintenance_guard():
    if _maintenance_mode.get("enabled"):
        raise HTTPException(status_code=503, detail=_maintenance_mode.get("reason", "Maintenance"))

# Gate public write endpoints with maintenance mode (wrappers that call original handlers)
@app.post("/api/verify-device-mm")
async def verify_device_with_mm(request: Request):
    maintenance_guard()
    form = await request.form()
    return await verify_device(
        user_id=int(form.get("user_id")),
        screen_resolution=form.get("screen_resolution"),
        user_agent_hash=form.get("user_agent_hash"),
        timezone_offset=form.get("timezone_offset"),
        platform=form.get("platform"),
        language=form.get("language"),
        canvas_hash=form.get("canvas_hash"),
        webgl_hash=form.get("webgl_hash"),
        hardware_concurrency=form.get("hardware_concurrency"),
        memory=form.get("memory"),
        touch_support=form.get("touch_support"),
        color_depth=form.get("color_depth"),
        screen_orientation=form.get("screen_orientation"),
        user_agent=form.get("user_agent", "unknown"),
        ip_address=form.get("ip_address", "unknown"),
    )

@app.post("/api/withdraw-mm")
async def withdraw_with_mm(request: Request):
    maintenance_guard()
    form = await request.form()
    return await request_withdrawal(
        user_id=int(form.get("user_id")),
        amount=float(form.get("amount")),
        method=form.get("method"),
        upi_id=form.get("upi_id"),
        account_name=form.get("account_name"),
        account_number=form.get("account_number"),
        ifsc_code=form.get("ifsc_code"),
        mobile_number=form.get("mobile_number"),
    )

@app.post("/api/campaigns/{campaign_id}/submit-mm")
async def submit_screenshot_with_mm(campaign_id: str, request: Request):
    maintenance_guard()
    form = await request.form()
    fileobj = form.get("file")
    if not hasattr(fileobj, "read"):
        raise HTTPException(status_code=400, detail="File missing")
    content = await fileobj.read()
    return await screenshot_manager.process_screenshot_submission(int(form.get("user_id")), campaign_id, content)

