# -------------------------------- True Dedup (SHA256 of file bytes) ----------------------

async def compute_file_sha256(path: str) -> Optional[str]:
    try:
        import hashlib
        h = hashlib.sha256()
        # Use standard file read (aiofiles for async can be used, but hashing is CPU-bound, so synchronous is OK here)
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                h.update(chunk)
        return h.hexdigest()
    except Exception as e:
        logger.error(f"SHA256 compute error for {path}: {e}")
        return None

async def backfill_screenshot_hashes(batch: int = 50) -> Dict[str, Any]:
    try:
        db = db_client.walletbot
        cur = db.screenshots.find({"hash_sha256": {"$exists": False}}, {"_id": 0, "submission_id": 1, "file_path": 1}).limit(batch)
        items = await cur.to_list(length=batch)
        updated = 0; missing = 0; errors = 0
        for it in items:
            p = it.get("file_path")
            sid = it.get("submission_id")
            if not p or not os.path.isfile(p):
                missing += 1
                continue
            sha = await compute_file_sha256(p)
            if not sha:
                errors += 1
                continue
            await db.screenshots.update_one({"submission_id": sid}, {"$set": {"hash_sha256": sha}})
            updated += 1
        return {"updated": updated, "missing": missing, "errors": errors, "scanned": len(items)}
    except Exception as e:
        logger.error(f"Backfill screenshot hashes error: {e}")
        return {"updated": 0, "missing": 0, "errors": 1, "scanned": 0}

@app.post("/api/admin/screenshots/hash-backfill")
async def admin_hash_backfill(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    batch = int(body.get("batch", 50))
    res = await backfill_screenshot_hashes(batch=batch)
    await write_audit_log("hash_backfill", username, res)
    return {"success": True, "data": res}

@app.get("/api/admin/screenshots/true-dedup")
async def admin_true_dedup(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        pipe = [
            {"$match": {"hash_sha256": {"$exists": True}}},
            {"$group": {"_id": "$hash_sha256", "count": {"$sum": 1}, "subs": {"$push": {"submission_id": "$submission_id", "user_id": "$user_id", "campaign_id": "$campaign_id"}}}},
            {"$match": {"count": {"$gt": 1}}},
            {"$sort": {"count": -1}},
            {"$limit": 200}
        ]
        dup = await db.screenshots.aggregate(pipe).to_list(length=200)
        return {"success": True, "data": {"duplicates": dup}}
    except Exception as e:
        logger.error(f"True dedup report error: {e}")
        raise HTTPException(status_code=500, detail="Failed to generate true dedup report")

