# Register background task to continuously backfill hashes at a low rate
async def periodic_hash_backfill():
    res = await backfill_screenshot_hashes(batch=20)
    if res.get("updated"):
        logger.info(f"Hash backfill: {res}")

# Add task to existing task_runner if available
try:
    task_runner.add_task("backfill_screenshot_hashes", interval_sec=300, coro_func=periodic_hash_backfill)
except Exception as _e:
    logger.debug("Task runner not available yet for hash backfill; will rely on manual trigger.")

