@app.get("/api/admin/withdrawals/sla")
async def admin_withdrawals_sla(username: str = Depends(authenticate_admin)):
    """
    Buckets pending withdrawals by age:
      0-1d, 1-2d, 2-3d, 3-7d, 7+d
    Provides counts and total amounts per bucket.
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        buckets = {
            "0_1d": {"count": 0, "amount": 0.0},
            "1_2d": {"count": 0, "amount": 0.0},
            "2_3d": {"count": 0, "amount": 0.0},
            "3_7d": {"count": 0, "amount": 0.0},
            "7p_d": {"count": 0, "amount": 0.0}
        }
        cur = db.withdrawal_requests.find({"status": "pending"})
        async for w in cur:
            created = w.get("created_at") or now
            try:
                if isinstance(created, dict) and "$date" in created:
                    created = datetime.fromtimestamp(created["$date"]/1000.0)
            except Exception:
                pass
            days = max(0.0, (now - created).total_seconds() / 86400.0)
            amt = float(w.get("amount", 0.0) or 0.0)
            if days < 1: buckets["0_1d"]["count"] += 1; buckets["0_1d"]["amount"] += amt
            elif days < 2: buckets["1_2d"]["count"] += 1; buckets["1_2d"]["amount"] += amt
            elif days < 3: buckets["2_3d"]["count"] += 1; buckets["2_3d"]["amount"] += amt
            elif days < 7: buckets["3_7d"]["count"] += 1; buckets["3_7d"]["amount"] += amt
            else: buckets["7p_d"]["count"] += 1; buckets["7p_d"]["amount"] += amt
        # Totals
        total_count = sum(b["count"] for b in buckets.values())
        total_amount = round(sum(b["amount"] for b in buckets.values()), 2)
        return {"success": True, "data": {"buckets": buckets, "totals": {"count": total_count, "amount": total_amount}}}
    except Exception as e:
        logger.error(f"SLA compute error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute SLA")

