# -------------------------------- File Integrity Checker (uploads vs DB) -----------------

@app.get("/api/admin/integrity/uploads")
async def admin_integrity_uploads(username: str = Depends(authenticate_admin)):
    """
    Scans uploads directories and DB to report:
    - Files present on disk but not referenced in DB (orphans)
    - DB records referencing missing files (broken refs)
    """
    try:
        db = db_client.walletbot
        dirs = [
            ("screenshots", "uploads/screenshots"),
            ("campaign_images", "uploads/campaign_images"),
            ("admin_images", "uploads/admin_images")
        ]
        result = {"orphan_files": [], "missing_refs": []}

        # Collect DB referenced files (screenshots, campaigns images, admin uploads if tracked)
        ref_files = set()
        # Screenshots
        cur = db.screenshots.find({}, {"_id": 0, "file_path": 1})
        async for s in cur:
            fp = s.get("file_path")
            if fp:
                ref_files.add(os.path.abspath(fp))
        # Campaign images
        cur2 = db.campaigns.find({}, {"_id": 0, "image_url": 1})
        async for c in cur2:
            url = c.get("image_url")
            if url and url.startswith("/uploads/"):
                local_path = url.lstrip("/")
                ref_files.add(os.path.abspath(local_path))

        # Crawl disk
        for label, d in dirs:
            try:
                if not os.path.isdir(d):
                    continue
                for root, _, files in os.walk(d):
                    for name in files:
                        path = os.path.abspath(os.path.join(root, name))
                        if path not in ref_files:
                            result["orphan_files"].append({"path": path, "size": os.path.getsize(path)})
            except Exception as e:
                logger.warning(f"Integrity crawl warning for {d}: {e}")

        # Find missing DB refs (screenshots)
        cur3 = db.screenshots.find({}, {"_id": 0, "submission_id": 1, "file_path": 1})
        async for s in cur3:
            fp = s.get("file_path")
            if fp and not os.path.isfile(fp):
                result["missing_refs"].append({"submission_id": s.get("submission_id"), "file_path": fp})

        # Limit report sizes
        result["orphan_files"] = result["orphan_files"][:5000]
        result["missing_refs"] = result["missing_refs"][:5000]

        return {"success": True, "data": result}
    except Exception as e:
        logger.error(f"Integrity uploads error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute integrity report")

