# -------------------------------- Campaign Auto‑Archival (bulk deactivate) ---------------

@app.post("/api/admin/campaigns/archive")
async def admin_campaigns_archive(
    start: Optional[str] = None,
    end: Optional[str] = None,
    username: str = Depends(authenticate_admin)
):
    """
    Bulk deactivates campaigns with created_at within [start, end] (ISO strings).
    """
    try:
        db = db_client.walletbot
        q = {}
        if start or end:
            q["created_at"] = {}
            if start:
                try: q["created_at"]["$gte"] = datetime.fromisoformat(start)
                except Exception: pass
            if end:
                try: q["created_at"]["$lte"] = datetime.fromisoformat(end)
                except Exception: pass
            if not q["created_at"]:
                q.pop("created_at", None)
        res = await db.campaigns.update_many(q, {"$set": {"active": False, "updated_at": datetime.utcnow(), "archived_auto": True}})
        await write_audit_log("campaigns_archive", username, {"matched": getattr(res, "matched_count", 0), "modified": getattr(res, "modified_count", 0)})
        return {"success": True, "matched": getattr(res, "matched_count", 0), "modified": getattr(res, "modified_count", 0)}
    except Exception as e:
        logger.error(f"Campaigns archive error: {e}")
        raise HTTPException(status_code=500, detail="Archival failed")

