# -------------------------------- Uploads Backup ZIP (streamed, size guard) --------------

@app.get("/api/admin/uploads/backup.zip")
async def admin_uploads_backup_zip(
    max_total_mb: int = 200,
    username: str = Depends(authenticate_admin)
):
    """
    Streams a ZIP of uploads directories with a total size guard (default 200MB).
    Avoids loading entire zip into memory—streams incrementally.
    """
    try:
        max_bytes = max(10, int(max_total_mb)) * 1024 * 1024
        folders = ["uploads/screenshots", "uploads/campaign_images", "uploads/admin_images"]
        # Collect file list and compute total size
        files = []
        total = 0
        for d in folders:
            if not os.path.isdir(d):
                continue
            for root, _, fs in os.walk(d):
                for name in fs:
                    path = os.path.join(root, name)
                    try:
                        sz = os.path.getsize(path)
                        total += sz
                        files.append((path, os.path.relpath(path, start=".")))
                        if total > max_bytes:
                            raise HTTPException(status_code=413, detail=f"Backup size exceeds limit ({max_total_mb}MB). Reduce files or lower retention.")
                    except FileNotFoundError:
                        continue

        def iter_zip():
            import zipfile
            buf = io.BytesIO()
            with zipfile.ZipFile(buf, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
                for path, arc in files:
                    try:
                        zf.write(path, arcname=arc)
                        # flush chunk
                        buf.seek(0)
                        chunk = buf.read()
                        if chunk:
                            yield chunk
                        buf.seek(0); buf.truncate(0)
                    except Exception as e:
                        logger.warning(f"Zip write warning for {path}: {e}")
                # finalize
                zf.close()
                buf.seek(0)
                rest = buf.read()
                if rest:
                    yield rest

        headers = {"Content-Disposition": "attachment; filename=uploads_backup.zip"}
        return StreamingResponse(iter_zip(), media_type="application/zip", headers=headers)
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Uploads backup error: {e}")
        raise HTTPException(status_code=500, detail="Failed to create backup")

