# ========================================================================================
#  Enterprise Wallet Bot - Single File Build (Fixed Minimal Edition)
#  CHUNK M: Per-user Audit Trail, API Keys Manager (masked), Bulk Email Export,
#           Data Retention Cleaner (previews + explicit confirm)
#  Notes:
#    - No refactor; builds on existing collections and admin-only pattern
#    - API Keys manager stores masked configs in bot_settings; never echoes secrets fully
#    - Retention cleaner offers preview endpoints and explicit confirm endpoint
# ========================================================================================

# -------------------------------- Utilities ---------------------------------------------

def _mask_value(val: Optional[str], head: int = 3, tail: int = 2) -> str:
    if not val:
        return ""
    if len(val) <= head + tail:
        return "*" * len(val)
    return val[:head] + "*" * (len(val) - head - tail) + val[-tail:]

# -------------------------------- Per-user Audit Trail APIs ------------------------------

@app.get("/api/admin/users/{user_id}/audit-trail")
async def admin_user_audit_trail(
    user_id: int,
    limit: int = 100,
    username: str = Depends(authenticate_admin)
):
    """
    Aggregates a user's recent audit logs, transactions, and screenshots into a single feed.
    """
    try:
        db = db_client.walletbot
        limit = max(10, min(300, int(limit)))
        # recent audit logs by actor mentions user_id in meta (best-effort; also include actions targeting this user if structured)
        audit_cur = db.audit_logs.find(
            {"$or": [{"meta.user_id": user_id}, {"meta.existing_user_id": user_id}]}
        ).sort("created_at", -1).limit(limit)
        audits = await audit_cur.to_list(length=limit)

        tx_cur = db.transactions.find({"user_id": user_id}).sort("created_at", -1).limit(limit)
        txs = await tx_cur.to_list(length=limit)

        ss_cur = db.screenshots.find({"user_id": user_id}).sort("created_at", -1).limit(limit)
        shots = await ss_cur.to_list(length=limit)

        # merge feed (client can render separately; we also produce merged with tags)
        merged = []
        for a in audits:
            merged.append({"kind": "audit", "time": a.get("created_at"), "doc": a})
        for t in txs:
            merged.append({"kind": "tx", "time": t.get("created_at"), "doc": t})
        for s in shots:
            merged.append({"kind": "screenshot", "time": s.get("created_at"), "doc": s})
        # sort by time desc (best-effort)
        def _ts(x):
            v = x.get("time")
            try:
                if isinstance(v, dict) and "$date" in v:
                    return v["$date"]
                return v
            except Exception:
                return None
        merged.sort(key=_ts, reverse=True)
        return {"success": True, "data": {"audits": audits, "transactions": txs, "screenshots": shots, "merged": merged[:limit]}}
    except Exception as e:
        logger.error(f"User audit trail error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build audit trail")

