# -------------------------------- Admin API Keys Manager (masked) ------------------------

@app.get("/api/admin/apikeys")
async def admin_apikeys_get(username: str = Depends(authenticate_admin)):
    """
    Returns masked payment gateway keys from bot_settings.main_config.
    """
    try:
        cfg = await get_main_config()
        pg = cfg.get("payment_gateways", {}) or {}
        rzp = pg.get("razorpay", {}) or {}
        ptm = pg.get("paytm", {}) or {}
        # Mask sensitive fields
        result = {
            "razorpay": {
                "enabled": bool(rzp.get("enabled")),
                "api_key_masked": _mask_value(rzp.get("api_key") or "", 4, 2),
                "secret_masked": _mask_value(rzp.get("secret") or "", 3, 2),
                "test_mode": bool(rzp.get("test_mode", True))
            },
            "paytm": {
                "enabled": bool(ptm.get("enabled")),
                "api_key_masked": _mask_value(ptm.get("api_key") or "", 4, 2),
                "merchant_id_masked": _mask_value(ptm.get("merchant_id") or "", 4, 2),
                "test_mode": bool(ptm.get("test_mode", True))
            }
        }
        return {"success": True, "data": result}
    except Exception as e:
        logger.error(f"API keys get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load API keys")

@app.post("/api/admin/apikeys")
async def admin_apikeys_update(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    """
    Updates payment gateway keys. Accepts partial updates. Never returns raw secrets.
    Body examples:
      { "razorpay": { "api_key": "...", "secret": "...", "enabled": true, "test_mode": true } }
      { "paytm": { "api_key": "...", "merchant_id": "...", "enabled": false, "test_mode": true } }
    """
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {"type": "main_config"}
        pg = cfg.get("payment_gateways", {}) or {}
        new_pg = {**pg}
        for gw in ["razorpay", "paytm"]:
            if gw in body and isinstance(body[gw], dict):
                current = new_pg.get(gw, {}) or {}
                updated = {**current}
                for k, v in body[gw].items():
                    if k in ("api_key", "secret", "merchant_id", "enabled", "test_mode"):
                        updated[k] = v
                new_pg[gw] = updated
        await db.bot_settings.update_one({"type": "main_config"}, {"$set": {"payment_gateways": new_pg, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("apikeys_update", username, {"gateways": [k for k in body.keys()]})
        return {"success": True}
    except Exception as e:
        logger.error(f"API keys update error: {e}")
        raise HTTPException(status_code=500, detail="Failed to update API keys")

