@app.get("/api/admin/export/emails.csv")
async def admin_export_emails_csv(
    include_unverified: bool = False,
    username: str = Depends(authenticate_admin)
):
    """
    Exports a CSV of user contact placeholders (email field is hypothetical/placeholder).
    If your schema doesn't have email, this will output empty values but keeps format consistent.
    """
    try:
        db = db_client.walletbot
        q = {} if include_unverified else {"device_verified": True}
        cur = db.users.find(q, {"_id": 0, "user_id": 1, "username": 1, "email": 1, "device_verified": 1}).sort("created_at", -1)
        rows = ["user_id,username,email,verified\n"]
        async for u in cur:
            rows.append(",".join([
                str(u.get("user_id", "")),
                '"' + str(u.get("username", "")).replace('"', '""') + '"',
                '"' + str(u.get("email", "")).replace('"', '""') + '"',
                "1" if u.get("device_verified") else "0"
            ]) + "\n")
        data = "".join(rows).encode("utf-8")
        return StreamingResponse(io.BytesIO(data), media_type="text/csv", headers={"Content-Disposition": "attachment; filename=emails.csv"})
    except Exception as e:
        logger.error(f"Export emails csv error: {e}")
        raise HTTPException(status_code=500, detail="Failed to export emails")

