# -------------------------------- Data Retention Cleaner (previews + confirm) ------------

@app.get("/api/admin/retention/preview")
async def admin_retention_preview(
    logs_days: int = 90,
    screenshots_days: int = 365,
    username: str = Depends(authenticate_admin)
):
    """
    Preview counts of items older than thresholds:
    - audit_logs older than logs_days
    - screenshots older than screenshots_days (only DB entries; file deletion is a separate, explicit action)
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        old_logs_cutoff = now - timedelta(days=max(7, min(3650, logs_days)))
        old_ss_cutoff = now - timedelta(days=max(30, min(3650, screenshots_days)))

        logs_count = await db.audit_logs.count_documents({"created_at": {"$lt": old_logs_cutoff}})
        ss_count = await db.screenshots.count_documents({"created_at": {"$lt": old_ss_cutoff}})
        return {"success": True, "data": {"audit_logs_older": logs_count, "screenshots_older": ss_count}}
    except Exception as e:
        logger.error(f"Retention preview error: {e}")
        raise HTTPException(status_code=500, detail="Failed to preview retention")

@app.post("/api/admin/retention/cleanup")
async def admin_retention_cleanup(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Cleanup with explicit confirm flags:
      body: { confirm_logs: true/false, logs_days: N, confirm_screenshots: true/false, screenshots_days: M }
    Screenshots cleanup only removes DB entries (NOT files) to avoid accidental data loss.
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        confirm_logs = bool(body.get("confirm_logs"))
        logs_days = int(body.get("logs_days", 90))
        confirm_ss = bool(body.get("confirm_screenshots"))
        ss_days = int(body.get("screenshots_days", 365))

        deleted = {"audit_logs": 0, "screenshots": 0}

        if confirm_logs:
            cutoff = now - timedelta(days=max(7, min(3650, logs_days)))
            res = await db.audit_logs.delete_many({"created_at": {"$lt": cutoff}})
            deleted["audit_logs"] = getattr(res, "deleted_count", 0)

        if confirm_ss:
            cutoff = now - timedelta(days=max(30, min(3650, ss_days)))
            res = await db.screenshots.delete_many({"created_at": {"$lt": cutoff}})
            deleted["screenshots"] = getattr(res, "deleted_count", 0)

        await write_audit_log("retention_cleanup", username, {"deleted": deleted})
        return {"success": True, "data": deleted}
    except Exception as e:
        logger.error(f"Retention cleanup error: {e}")
        raise HTTPException(status_code=500, detail="Cleanup failed")

