#    - Profiler logs per-route latency samples in-memory and (optionally) in DB
#    - Reviewer metrics based on screenshots collection transitions
#    - Anomalies scan users/transactions to flag potential risks
#    - Campaign bundle import/export for portability
# ========================================================================================

# -------------------------------- In-memory Performance Profiler -------------------------

import time as _time
from functools import wraps

_perf_samples = []  # list of dicts {path, method, ms, ts}
_PERF_MAX = 5000

def profile_endpoint(path_override: str = None):
    def deco(fn):
        @wraps(fn)
        async def wrapper(*args, **kwargs):
            t0 = _time.perf_counter()
            try:
                return await fn(*args, **kwargs)
            finally:
                ms = int((_time.perf_counter() - t0) * 1000)
                sample = {
                    "path": path_override or f"{getattr(fn, '__name__', 'unknown')}",
                    "method": "AUTO",
                    "ms": ms,
                    "ts": int(_time.time())
                }
                _perf_samples.append(sample)
                if len(_perf_samples) > _PERF_MAX:
                    del _perf_samples[:len(_perf_samples) - _PERF_MAX]
        return wrapper
    return deco

@app.get("/api/admin/profiler/samples")
async def profiler_samples(username: str = Depends(authenticate_admin)):
    # Return recent samples grouped by path
    try:
        from collections import defaultdict
        groups = defaultdict(list)
        for s in _perf_samples:
            groups[s["path"]].append(s["ms"])
        out = []
        for p, arr in groups.items():
            if not arr:
                continue
            arr_sorted = sorted(arr)
            n = len(arr_sorted)
            p50 = arr_sorted[n//2]
            p90 = arr_sorted[int(n*0.9)-1] if n>1 else arr_sorted[-1]
            p99 = arr_sorted[int(n*0.99)-1] if n>1 else arr_sorted[-1]
            out.append({
                "path": p,
                "count": n,
                "avg": sum(arr_sorted)/n,
                "p50": p50,
                "p90": p90,
                "p99": p99,
                "max": arr_sorted[-1]
            })
        out.sort(key=lambda x: -x["p90"])
        return {"success": True, "data": out[:200]}
    except Exception as e:
        logger.error(f"Profiler samples error: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch samples")

