# -------------------------------- Reviewer Productivity Metrics --------------------------

@app.get("/api/admin/reviewer/metrics")
async def reviewer_metrics(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Computes daily counts of approvals/rejections and top reviewers (by admin_notes actor hint).
    We assume admin notes may include a marker like 'by:username' (optional).
    """
    try:
        db = db_client.walletbot
        days = max(1, min(180, days))
        since = datetime.utcnow() - timedelta(days=days)

        # Daily counts by status
        pipe = [
            {"$match": {"reviewed_at": {"$gte": since}}},
            {"$group": {
                "_id": {
                    "day": {"$dateToString": {"format": "%Y-%m-%d", "date": "$reviewed_at"}},
                    "status": "$status"
                },
                "cnt": {"$sum": 1}
            }},
            {"$sort": {"_id.day": 1}}
        ]
        daily = await db.screenshots.aggregate(pipe).to_list(length=5000)

        # Extract reviewer name heuristically from admin_notes "by:xyz"
        cur = db.screenshots.find({"reviewed_at": {"$gte": since}, "status": {"$in": ["approved", "rejected"]}},
                                  {"_id": 0, "admin_notes": 1})
        from collections import Counter
        c = Counter()
        async for s in cur:
            notes = s.get("admin_notes") or ""
            # crude parse
            idx = notes.find("by:")
            if idx >= 0:
                tail = notes[idx+3:].strip()
                name = tail.split()[0].strip(",.;:")[:32]
                if name:
                    c[name] += 1
        top = [{"reviewer": k, "count": v} for k, v in c.most_common(20)]

        return {"success": True, "data": {"daily": daily, "top_reviewers": top}}
    except Exception as e:
        logger.error(f"Reviewer metrics error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute metrics")

