# -------------------------------- Transaction Anomalies Finder ---------------------------

@app.get("/api/admin/transactions/anomalies")
async def tx_anomalies(
    min_abs_delta: float = 1.0,
    window_days: int = 14,
    username: str = Depends(authenticate_admin)
):
    """
    Finds users with negative wallet_balance or high oscillation (sum of |amount| > threshold).
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        since = now - timedelta(days=max(1, min(90, window_days)))

        # Users with negative wallet
        neg_cur = db.users.find({"wallet_balance": {"$lt": 0}}, {"_id": 0, "user_id": 1, "username": 1, "wallet_balance": 1}).limit(200)
        negatives = await neg_cur.to_list(length=200)

        # Oscillation: sum of absolute amounts in window
        cur = db.transactions.find({"created_at": {"$gte": since}}, {"_id": 0, "user_id": 1, "amount": 1})
        from collections import defaultdict
        abs_sum = defaultdict(float)
        async for t in cur:
            try:
                uid = t.get("user_id")
                amt = float(t.get("amount", 0) or 0)
                abs_sum[uid] += abs(amt)
            except Exception:
                pass
        threshold = max(10.0, float(min_abs_delta))
        oscillators = [{"user_id": k, "abs_sum": round(v,2)} for k, v in abs_sum.items() if v >= threshold]
        oscillators.sort(key=lambda x: -x["abs_sum"])
        return {"success": True, "data": {"negatives": negatives, "oscillators": oscillators[:500], "window_days": window_days, "threshold": threshold}}
    except Exception as e:
        logger.error(f"TX anomalies error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute anomalies")

