@app.get("/api/admin/campaigns/export.json")
async def campaigns_export_json(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cur = db.campaigns.find({}, {"_id": 0})
        items = await cur.to_list(length=5000)
        payload = json.dumps({"campaigns": items}, default=str, indent=2).encode("utf-8")
        return StreamingResponse(io.BytesIO(payload), media_type="application/json",
                                 headers={"Content-Disposition": "attachment; filename=campaigns_export.json"})
    except Exception as e:
        logger.error(f"Campaigns export error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

@app.post("/api/admin/campaigns/import")
async def campaigns_import_json(file: UploadFile = File(...), username: str = Depends(authenticate_admin)):
    try:
        content = await file.read()
        data = json.loads(content.decode("utf-8"))
        arr = data.get("campaigns") or []
        if not isinstance(arr, list):
            raise HTTPException(status_code=400, detail="Invalid bundle")
        db = db_client.walletbot
        inserted = 0
        for c in arr:
            if not isinstance(c, dict):
                continue
            cid = c.get("campaign_id") or str(uuid.uuid4())
            c["campaign_id"] = cid
            c["updated_at"] = datetime.utcnow()
            if "created_at" not in c:
                c["created_at"] = datetime.utcnow()
            try:
                await db.campaigns.update_one({"campaign_id": cid}, {"$set": c}, upsert=True)
                inserted += 1
            except Exception:
                pass
        await write_audit_log("campaigns_import", username, {"count": inserted, "file": file.filename})
        return {"success": True, "imported_or_updated": inserted}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Campaigns import error: {e}")
        raise HTTPException(status_code=500, detail="Import failed")

