# -------------------------------- Withdrawals Reconciliation (Test Stubs) ----------------

async def test_mode_upi_verify(upi_id: str) -> Dict[str, Any]:
    # Stub verification (TEST ONLY) – checks simple format and returns deterministic hash id
    try:
        if not upi_id or "@" not in upi_id:
            return {"valid": False, "message": "Invalid UPI format"}
        h = hashlib.sha256(upi_id.encode()).hexdigest()[:8]
        return {"valid": True, "ref": f"upi_test_{h}"}
    except Exception:
        return {"valid": False, "message": "Verification error"}

async def test_mode_bank_verify(account_number: str, ifsc: str, name: str) -> Dict[str, Any]:
    try:
        if not account_number or not ifsc or len(ifsc) < 4:
            return {"valid": False, "message": "Invalid bank details"}
        base = f"{account_number}|{ifsc}|{name}".lower()
        h = hashlib.sha256(base.encode()).hexdigest()[:8]
        return {"valid": True, "ref": f"bank_test_{h}"}
    except Exception:
        return {"valid": False, "message": "Verification error"}

@app.post("/api/admin/withdrawals/reconcile/{request_id}")
async def admin_withdrawal_reconcile(
    request_id: str,
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Attempts to verify requested payout details (TEST MODE ONLY).
    Returns a reconciliation note that admins can store manually in admin_notes of the request.
    """
    try:
        db = db_client.walletbot
        req = await db.withdrawal_requests.find_one({"request_id": request_id})
        if not req:
            raise HTTPException(status_code=404, detail="Request not found")
        method = req.get("method")
        details = req.get("details", {})
        if method == "upi":
            res = await test_mode_upi_verify(details.get("upi_id", ""))
        elif method == "bank":
            res = await test_mode_bank_verify(
                details.get("account_number", ""),
                details.get("ifsc_code", ""),
                details.get("account_name", "")
            )
        else:
            res = {"valid": False, "message": "Unsupported method for recon"}
        note = f"Reconciliation (TEST): {json.dumps(res)}"
        return {"success": True, "data": {"note": note}}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Withdrawal reconcile error: {e}")
        raise HTTPException(status_code=500, detail="Failed to reconcile")

