# -------------------------------- Reviewer Assignment Fairness ---------------------------

@app.get("/api/admin/reviewer/fairness")
async def reviewer_fairness(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Computes distribution of assignments and completions per reviewer in the window.
    assignments: screenshots with assigned_to set within window (by created_at or assigned_at if present)
    completed: reviewed_at within window, grouped by assigned_to if present (fallback to notes by:..)
    """
    try:
        db = db_client.walletbot
        days = max(1, min(180, days))
        since = datetime.utcnow() - timedelta(days=days)

        # Assignments by assigned_to
        assn_cur = db.screenshots.find(
            {"$or": [{"assigned_at": {"$gte": since}}, {"created_at": {"$gte": since}}], "assigned_to": {"$exists": True, "$ne": None, "$ne": ""}},
            {"_id": 0, "assigned_to": 1}
        )
        from collections import Counter
        assigned = Counter()
        async for s in assn_cur:
            assigned[s.get("assigned_to")] += 1

        # Completed by assigned_to (fallback to admin_notes "by:")
        comp_cur = db.screenshots.find({"reviewed_at": {"$gte": since}, "status": {"$in": ["approved", "rejected"]}},
                                       {"_id": 0, "assigned_to": 1, "admin_notes": 1})
        completed = Counter()
        async for s in comp_cur:
            who = s.get("assigned_to")
            if not who:
                notes = s.get("admin_notes") or ""
                ix = notes.find("by:")
                if ix >= 0:
                    tail = notes[ix+3:].strip()
                    who = tail.split()[0].strip(",.;:")[:32]
            if who:
                completed[who] += 1

        fair = []
        reviewers = set(list(assigned.keys()) + list(completed.keys()))
        for r in reviewers:
            fair.append({
                "reviewer": r or "unknown",
                "assigned": assigned.get(r, 0),
                "completed": completed.get(r, 0),
                "completion_rate": round((completed.get(r, 0) / assigned.get(r, 1)) * 100, 1) if assigned.get(r, 0) else 0.0
            })
        fair.sort(key=lambda x: (-x["completed"], -x["assigned"]))
        return {"success": True, "data": {"window_days": days, "reviewers": fair}}
    except Exception as e:
        logger.error(f"Reviewer fairness error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute fairness")

