# -------------------------------- Screenshot Similarity Clusters (lightweight) -----------

@app.get("/api/admin/screenshots/similarity")
async def screenshots_similarity(username: str = Depends(authenticate_admin)):
    """
    Groups screenshots by a simple similarity key: filename base (lowercased, without uid/campaign suffix) + size bucket.
    This is a heuristic aid; for true dedup, use SHA256 page added earlier.
    """
    try:
        db = db_client.walletbot
        cur = db.screenshots.find({}, {"_id": 0, "submission_id": 1, "filename": 1, "file_size": 1, "user_id": 1, "campaign_id": 1}).limit(50000)
        from collections import defaultdict
        groups = defaultdict(list)
        async for s in cur:
            name = (s.get("filename") or "").lower()
            # heuristic: strip typical uid/campaign tokens split by '_'
            base = name.split("_")[0] if "_" in name else name
            size = int(s.get("file_size") or 0)
            bucket = f"{(size//50000)*50}k"  # 50KB bucket
            key = f"{base}:{bucket}"
            groups[key].append(s)
        clusters = [{"key": k, "count": len(v), "items": v[:50]} for k, v in groups.items() if len(v) > 3]
        clusters.sort(key=lambda x: -x["count"])
        return {"success": True, "data": {"clusters": clusters[:500]}}
    except Exception as e:
        logger.error(f"Similarity clusters error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute clusters")

