@app.get("/api/admin/unified/export.json")
async def unified_export(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        settings = await db.bot_settings.find_one({"type": "main_config"}) or {}
        settings.pop("_id", None)
        chans = await db.force_join_channels.find({}, {"_id": 0}).to_list(length=2000)
        gifts = await db.gift_codes.find({}, {"_id": 0}).to_list(length=10000)
        payload = {"settings": settings, "channels": chans, "gift_codes": gifts, "exported_at": datetime.utcnow().isoformat()}
        data = json.dumps(payload, default=str, indent=2).encode("utf-8")
        return StreamingResponse(io.BytesIO(data), media_type="application/json",
                                 headers={"Content-Disposition": "attachment; filename=unified_export.json"})
    except Exception as e:
        logger.error(f"Unified export error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

@app.post("/api/admin/unified/import")
async def unified_import(file: UploadFile = File(...), username: str = Depends(authenticate_admin)):
    try:
        content = await file.read()
        data = json.loads(content.decode("utf-8"))
        if not isinstance(data, dict):
            raise HTTPException(status_code=400, detail="Invalid bundle")
        db = db_client.walletbot
        # settings
        settings = data.get("settings")
        if isinstance(settings, dict):
            settings["type"] = "main_config"
            settings["updated_at"] = datetime.utcnow()
            await db.bot_settings.update_one({"type": "main_config"}, {"$set": settings}, upsert=True)
        # channels
        channels = data.get("channels") or []
        if isinstance(channels, list):
            for c in channels:
                cid = c.get("channel_id")
                if not cid:
                    continue
                c["updated_at"] = datetime.utcnow()
                await db.force_join_channels.update_one({"channel_id": cid}, {"$set": c}, upsert=True)
        # gift codes
        gift_codes = data.get("gift_codes") or []
        if isinstance(gift_codes, list):
            for g in gift_codes:
                code = g.get("code")
                if not code:
                    continue
                g["updated_at"] = datetime.utcnow()
                await db.gift_codes.update_one({"code": code}, {"$set": g}, upsert=True)
        await write_audit_log("unified_import", username, {"channels": len(channels or []), "gift_codes": len(gift_codes or [])})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Unified import error: {e}")
        raise HTTPException(status_code=500, detail="Import failed")

