# ========================================================================================

# -------------------------------- Reviewer Auto-Assign (optional) ------------------------

_reviewer_load = {}  # { reviewer_username: score }, lower is better

def _decay_reviewer_load():
    # decay scores to naturally rebalance over time
    for k in list(_reviewer_load.keys()):
        _reviewer_load[k] = max(0.0, _reviewer_load[k] * 0.9)

async def _get_reviewer_candidates(db):
    # Collect distinct assigned_to and admin usernames seen in audit logs (best-effort)
    try:
        cur = db.screenshots.distinct("assigned_to")
        assignees = [a for a in await cur if a]
    except Exception:
        assignees = []
    # Fallback: if none, return empty; admins will be those who interact soon
    return list(sorted(set(assignees)))

@app.get("/api/admin/mod/auto-assign/next")
async def mod_auto_assign_next(
    username: str = Depends(authenticate_admin)
):
    """
    Picks the next pending screenshot and assigns to the least-loaded reviewer (including the caller).
    Load metric is in-memory, decayed; DB ties are acceptable.
    """
    try:
        db = db_client.walletbot
        # fetch one pending, unassigned
        s = await db.screenshots.find_one({
            "status": "pending",
            "$or": [{"assigned_to": {"$exists": False}}, {"assigned_to": None}, {"assigned_to": ""}]
        }, sort=[("created_at", 1)])
        if not s:
            return {"success": False, "message": "No pending items"}

        # choose candidate reviewers: known + caller
        candidates = await _get_reviewer_candidates(db)
        if username not in candidates:
            candidates.append(username)
        if not candidates:
            candidates = [username]

        # decay and compute load
        _decay_reviewer_load()
        for c in candidates:
            _reviewer_load.setdefault(c, 0.0)

        # pick min load
        winner = min(candidates, key=lambda u: _reviewer_load.get(u, 0.0))
        # assign
        res = await db.screenshots.update_one(
            {"submission_id": s["submission_id"], "status": "pending"},
            {"$set": {"assigned_to": winner, "assigned_at": datetime.utcnow()}}
        )
        if res.matched_count == 0:
            return {"success": False, "message": "Race condition; try again"}

        # bump load slightly
        _reviewer_load[winner] = _reviewer_load.get(winner, 0.0) + 1.0
        await write_audit_log("mod_auto_assign", winner, {"submission_id": s["submission_id"]})
        return {"success": True, "submission_id": s["submission_id"], "assigned_to": winner}
    except Exception as e:
        logger.error(f"Auto-assign error: {e}")
        raise HTTPException(status_code=500, detail="Auto-assign failed")

