# -------------------------------- S3-Compatible Upload Backend (stubs) -------------------

class S3StorageStub:
    def __init__(self, cfg: Dict[str, Any]):
        self.enabled = bool(cfg.get("enabled", False))
        self.bucket = cfg.get("bucket")
        self.endpoint = cfg.get("endpoint")
        self.access_key = cfg.get("access_key")
        self.secret_key = cfg.get("secret_key")
        self.region = cfg.get("region", "auto")
        # This is a stub; in real use, an S3 client library would be initialized here.

    async def upload_bytes(self, key: str, data: bytes, content_type: str = "application/octet-stream") -> str:
        if not self.enabled:
            raise RuntimeError("S3 storage disabled")
        # Stub: simulate remote URL
        return f"https://{self.bucket}.example-s3/{key}"

async def get_storage_backend() -> Optional[S3StorageStub]:
    cfg = await get_main_config()
    storage = (cfg.get("storage") or {}).get("s3") or {}
    backend = S3StorageStub(storage)
    return backend if backend.enabled else None

@app.post("/api/admin/storage/test-upload")
async def admin_storage_test_upload(
    file: UploadFile = File(...),
    username: str = Depends(authenticate_admin)
):
    """
    Attempts to upload a file to S3-compatible backend if enabled. Falls back to local save in /uploads/admin_images.
    """
    try:
        data = await file.read()
        backend = await get_storage_backend()
        if backend:
            key = f"admin_tests/{uuid.uuid4().hex}_{file.filename or 'upload.bin'}"
            try:
                url = await backend.upload_bytes(key, data, content_type=file.content_type or "application/octet-stream")
                await write_audit_log("storage_test_upload", username, {"remote_key": key})
                return {"success": True, "storage": "s3", "url": url}
            except Exception as e:
                logger.warning(f"S3 upload stub failed, falling back to local: {e}")
        # fallback local
        os.makedirs("uploads/admin_images", exist_ok=True)
        out_name = f"test_{uuid.uuid4().hex}_{file.filename or 'upload.bin'}"
        out_path = os.path.join("uploads/admin_images", out_name)
        with open(out_path, "wb") as f:
            f.write(data)
        await write_audit_log("storage_test_upload", username, {"local_path": out_path})
        return {"success": True, "storage": "local", "path": f"/uploads/admin_images/{out_name}"}
    except Exception as e:
        logger.error(f"Storage test upload error: {e}")
        raise HTTPException(status_code=500, detail="Test upload failed")

