# -------------------------------- Screenshot Review Tags Dashboard -----------------------

@app.get("/api/admin/tags/summary")
async def admin_tags_summary(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Returns:
    - counts per tag (overall)
    - time-series by day for top tags
    Tags are read from screenshots.flags (array of strings), restricted to reviewed items in window.
    """
    try:
        db = db_client.walletbot
        days = max(1, min(180, days))
        since = datetime.utcnow() - timedelta(days=days)

        # Gather tag counts overall
        cur = db.screenshots.find(
            {"reviewed_at": {"$gte": since}, "flags": {"$exists": True, "$ne": []}},
            {"_id": 0, "flags": 1}
        )
        from collections import Counter, defaultdict
        counts = Counter()
        async for s in cur:
            for f in s.get("flags") or []:
                if isinstance(f, str) and f.strip():
                    counts[f.strip().lower()] += 1
        overall = [{"tag": k, "count": v} for k, v in counts.most_common(100)]

        # Determine top tags to track in time-series (up to 8)
        top_tags = [x["tag"] for x in overall[:8]]

        # Build time-series by reviewed_at day
        ts = defaultdict(lambda: {"day": ""})
        if top_tags:
            cur2 = db.screenshots.find(
                {"reviewed_at": {"$gte": since}, "flags": {"$exists": True, "$ne": []}},
                {"_id": 0, "flags": 1, "reviewed_at": 1}
            )
            async for s in cur2:
                t = s.get("reviewed_at")
                day = t.date().isoformat() if hasattr(t, "date") else str(t)[:10]
                row = ts[day]
                row["day"] = day
                fs = [f.strip().lower() for f in (s.get("flags") or []) if isinstance(f, str)]
                for tag in top_tags:
                    if tag in fs:
                        row[tag] = (row.get(tag, 0) + 1)

        series = list(ts.values())
        series.sort(key=lambda x: x["day"])

        return {"success": True, "data": {"overall": overall, "series": series, "top_tags": top_tags, "window_days": days}}
    except Exception as e:
        logger.error(f"Tags summary error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute tags summary")

