# -------------------------------- Reviewer SLA Alerts -----------------------------------

@app.get("/api/admin/reviewer/sla")
async def reviewer_sla(
    max_age_hours: int = 24,
    username: str = Depends(authenticate_admin)
):
    """
    Lists assigned pending screenshots older than thresholds per reviewer.
    Buckets: 0-2h, 2-6h, 6-24h, 24-48h, 48+h
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        cur = db.screenshots.find({"status": "pending", "assigned_to": {"$exists": True, "$ne": None, "$ne": ""}},
                                  {"_id": 0, "submission_id": 1, "assigned_to": 1, "assigned_at": 1})
        from collections import defaultdict
        buckets = defaultdict(lambda: {"reviewer": "", "b_0_2": 0, "b_2_6": 0, "b_6_24": 0, "b_24_48": 0, "b_48p": 0, "total": 0})
        async for s in cur:
            who = s.get("assigned_to") or "unknown"
            t = s.get("assigned_at") or now
            age_h = max(0.0, (now - t).total_seconds() / 3600.0)
            row = buckets[who]
            row["reviewer"] = who
            row["total"] += 1
            if age_h < 2: row["b_0_2"] += 1
            elif age_h < 6: row["b_2_6"] += 1
            elif age_h < 24: row["b_6_24"] += 1
            elif age_h < 48: row["b_24_48"] += 1
            else: row["b_48p"] += 1
        rows = list(buckets.values())
        rows.sort(key=lambda x: -x["b_24_48"] - x["b_48p"])
        return {"success": True, "data": {"rows": rows, "as_of": now.isoformat()}}
    except Exception as e:
        logger.error(f"Reviewer SLA error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute SLA")

