# -------------------------------- Campaign Pacing Monitor --------------------------------

@app.get("/api/admin/campaigns/pacing")
async def campaign_pacing(
    days: int = 14,
    username: str = Depends(authenticate_admin)
):
    """
    Compares daily submissions vs targets.
    Targets:
      - pacing.daily_target_total (overall)
      - pacing.per_campaign[campaign_id] (optional overrides)
    """
    try:
        db = db_client.walletbot
        days = max(1, min(60, days))
        since = datetime.utcnow() - timedelta(days=days)
        targets = await get_pacing_targets()
        per_campaign_targets = (targets.get("per_campaign") or {})
        total_target = float(targets.get("daily_target_total") or 0.0)

        # Daily totals overall
        pipe = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {"_id": {"day": {"$dateToString": {"format":"%Y-%m-%d","date":"$created_at"}}}, "count": {"$sum": 1}}},
            {"$sort": {"_id.day": 1}}
        ]
        daily = await db.screenshots.aggregate(pipe).to_list(length=1000)
        overall_series = [{"day": r["_id"]["day"], "actual": r["count"], "target": total_target} for r in daily]

        # Per campaign (only show top 10 most active)
        pipe2 = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {"_id": {"day": {"$dateToString": {"format":"%Y-%m-%d","date":"$created_at"}}, "campaign_id": "$campaign_id"}, "count": {"$sum": 1}}},
            {"$sort": {"_id.day": 1}}
        ]
        per = await db.screenshots.aggregate(pipe2).to_list(length=5000)
        from collections import defaultdict
        # collect totals by campaign to pick top
        totals = defaultdict(int)
        for r in per:
            totals[r["_id"]["campaign_id"]] += r["count"]
        top_campaigns = [cid for cid,_ in sorted(totals.items(), key=lambda x: -x[1])[:10]]

        per_map = defaultdict(list)
        for r in per:
            cid = r["_id"]["campaign_id"]
            if cid in top_campaigns:
                per_map[cid].append({"day": r["_id"]["day"], "actual": r["count"], "target": float(per_campaign_targets.get(cid) or 0.0)})

        return {"success": True, "data": {"overall": overall_series, "per_campaign": per_map, "window_days": days}}
    except Exception as e:
        logger.error(f"Pacing compute error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute pacing")

