# -------------------------------- Webhook Signature Verification Switch ------------------

# If enabled in settings.webhook_security, inbound webhook handler should validate the shared secret header.
# This chunk provides a wrapper endpoint for secure handling while preserving original logic.

def verify_webhook_signature(request: Request, conf: Dict[str, Any]) -> bool:
    try:
        if not conf.get("enabled"):
            return True
        header = conf.get("header") or "X-Webhook-Signature"
        secret = conf.get("secret") or ""
        provided = request.headers.get(header) or ""
        # Simple constant-time compare of raw secret
        return secrets.compare_digest(provided, secret)
    except Exception:
        return False

@app.post("/webhook/secure")
async def telegram_webhook_secure(request: Request):
    conf = await get_webhook_sig_config()
    if not verify_webhook_signature(request, conf):
        raise HTTPException(status_code=401, detail="Invalid signature")
    # handover to the original webhook logic if present
    try:
        body = await request.body()
        # Assuming an existing function process_telegram_update(raw_bytes) exists in prior chunks
        # Replace with your actual bot update processor
        if wallet_bot and wallet_bot.initialized:
            await wallet_bot.process_raw_update(body)
            return {"ok": True}
        return {"ok": False, "error": "bot not ready"}
    except Exception as e:
        logger.error(f"Secure webhook error: {e}")
        raise HTTPException(status_code=500, detail="Webhook processing failed")

