# -------------------------------- Escalation Inbox (flags-based) -------------------------

@app.get("/api/admin/mod/escalations")
async def mod_escalations_list(
    flag: Optional[str] = None,
    status: str = "pending",
    limit: int = 100,
    username: str = Depends(authenticate_admin)
):
    """
    List escalated screenshots filtered by a specific flag (e.g., 'possible_duplicate').
    Defaults to pending status; pass status=all to ignore.
    """
    try:
        db = db_client.walletbot
        limit = max(1, min(300, int(limit)))
        q: Dict[str, Any] = {"flags": {"$exists": True, "$ne": []}}
        if flag:
            q["flags"] = {"$in": [flag]}
        if status != "all":
            q["status"] = status
        cur = db.screenshots.find(q).sort("created_at", 1).limit(limit)
        items = await cur.to_list(length=limit)
        # Aggregate top flags for sidebar
        pipe = [
            {"$match": {"flags": {"$exists": True, "$ne": []}}},
            {"$unwind": "$flags"},
            {"$group": {"_id": {"flag": "$flags"}, "count": {"$sum": 1}}},
            {"$sort": {"count": -1}},
            {"$limit": 30}
        ]
        top = await db.screenshots.aggregate(pipe).to_list(length=100)
        return {"success": True, "data": {"items": items, "top_flags": [{"flag": t["_id"]["flag"], "count": t["count"]} for t in top]}}
    except Exception as e:
        logger.error(f"Escalations list error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load escalations")

