# -------------------------------- Stale Assignment Nudge (optional DM) -------------------

@app.post("/api/admin/mod/nudge/{reviewer_username}")
async def mod_nudge_reviewer(
    reviewer_username: str,
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Sends a polite DM to reviewer if bot is ready; otherwise returns the message to send.
    Includes count of pending assignments over 24h for that reviewer.
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        cutoff = now - timedelta(hours=24)
        count = await db.screenshots.count_documents({"status": "pending", "assigned_to": reviewer_username, "assigned_at": {"$lte": cutoff}})
        msg = (body.get("message") or f"Reminder: You have {count} pending assigned reviews older than 24h. Please take a look when possible.").strip()
        delivered = False
        error = None
        # If a mapping from admin username -> Telegram user_id exists in users collection, we’ll try DM.
        u = await db.users.find_one({"username": reviewer_username}, {"_id": 0, "user_id": 1})
        if wallet_bot and wallet_bot.initialized and wallet_bot.bot and u and u.get("user_id"):
            try:
                await wallet_bot.bot.send_message(chat_id=int(u["user_id"]), text=msg)
                delivered = True
            except Exception as e:
                error = str(e)
        await write_audit_log("mod_nudge", username, {"to": reviewer_username, "pending_24h": count, "delivered": delivered})
        return {"success": True, "delivered": delivered, "pending_over_24h": count, "fallback_message": msg, "error": error}
    except Exception as e:
        logger.error(f"Nudge reviewer error: {e}")
        raise HTTPException(status_code=500, detail="Nudge failed")

