# -------------------------------- Payout Ledger Audit ------------------------------------

@app.get("/api/admin/payouts/ledger")
async def payouts_ledger_audit(
    days: int = 60,
    username: str = Depends(authenticate_admin)
):
    """
    Compares withdrawals by method: pending vs approved vs rejected, amounts and counts.
    Also provides simple deltas: approved - pending.
    """
    try:
        db = db_client.walletbot
        days = max(1, min(365, days))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.withdrawal_requests.find({"created_at": {"$gte": since}}, {"_id": 0, "status": 1, "amount": 1, "method": 1})
        from collections import defaultdict
        summary = defaultdict(lambda: {"pending_amt": 0.0, "pending_cnt": 0, "approved_amt": 0.0, "approved_cnt": 0, "rejected_amt": 0.0, "rejected_cnt": 0})
        async for w in cur:
            m = (w.get("method") or "unknown").lower()
            amt = float(w.get("amount", 0.0) or 0.0)
            st = (w.get("status") or "pending").lower()
            if st == "pending":
                summary[m]["pending_amt"] += amt; summary[m]["pending_cnt"] += 1
            elif st == "approved":
                summary[m]["approved_amt"] += amt; summary[m]["approved_cnt"] += 1
            elif st == "rejected":
                summary[m]["rejected_amt"] += amt; summary[m]["rejected_cnt"] += 1
        # Build rows with deltas
        rows = []
        for method, s in summary.items():
            rows.append({
                "method": method,
                "pending_cnt": s["pending_cnt"],
                "pending_amt": round(s["pending_amt"], 2),
                "approved_cnt": s["approved_cnt"],
                "approved_amt": round(s["approved_amt"], 2),
                "rejected_cnt": s["rejected_cnt"],
                "rejected_amt": round(s["rejected_amt"], 2),
                "delta_amt": round(s["approved_amt"] - s["pending_amt"], 2)
            })
        rows.sort((lambda x, y: 0), reverse=False)  # stable
        return {"success": True, "data": {"rows": rows, "window_days": days}}
    except Exception as e:
        logger.error(f"Payout ledger audit error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute payout ledger")

