# Optional integration: enforce cap in auto-assign (non-refactor, small gate inside endpoint)
# Adjust the previously defined mod_auto_assign_next to respect caps if auto_assign_limit true.
# Since we avoid refactor, we add a small helper and call it before assignment:

async def _can_assign_reviewer(name: str) -> bool:
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
        if not cfg.get("auto_assign_limit"):
            return True
        caps = cfg.get("reviewer_caps") or {}
        cap = int(caps.get(name, 0) or 0)
        if cap <= 0:
            return True
        start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        cnt = await db.screenshots.count_documents({"assigned_to": name, "assigned_at": {"$gte": start}})
        return cnt < cap
    except Exception:
        return True

# We cannot rewrite mod_auto_assign_next here entirely (no refactor), but if you wish, insert:
#   if not await _can_assign_reviewer(winner): pick next candidate with available capacity.

# -------------------------------- Withdrawals Batch Approve/Reject (with safeguards) -----

@app.post("/api/admin/withdrawals/batch")
async def withdrawals_batch_action(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    body: {
      action: "approve" | "reject",
      request_ids: [ "req1", "req2", ... ],
      checklist: { risk_checked: true, details_verified: true, ledger_ok: true },
      note: "optional reason"
    }
    This endpoint assumes you already have single-item approve/reject endpoints; here we simulate the calls.
    """
    try:
        action = body.get("action")
        ids = body.get("request_ids") or []
        checklist = body.get("checklist") or {}
        note = (body.get("note") or "").strip()

        required = ["risk_checked", "details_verified", "ledger_ok"]
        for k in required:
            if not checklist.get(k):
                raise HTTPException(status_code=400, detail=f"Checklist item '{k}' must be true")

        if action not in ("approve", "reject"):
            raise HTTPException(status_code=400, detail="Invalid action")
        if not ids:
            raise HTTPException(status_code=400, detail="No request_ids provided")

        db = db_client.walletbot
        updated = 0
        res_notes = []
        for rid in ids:
            q = {"request_id": rid, "status": "pending"}
            if action == "approve":
                upd = await db.withdrawal_requests.update_one(q, {"$set": {"status": "approved", "processed_time": datetime.utcnow(), "admin_notes": note}})
            else:
                upd = await db.withdrawal_requests.update_one(q, {"$set": {"status": "rejected", "processed_time": datetime.utcnow(), "admin_notes": note or "rejected via batch"}})
            if getattr(upd, "modified_count", 0) > 0:
                updated += 1
                res_notes.append(rid)
        await write_audit_log("withdrawals_batch", username, {"action": action, "count": updated})
        return {"success": True, "updated": updated, "ids": res_notes}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Batch withdrawals error: {e}")
        raise HTTPException(status_code=500, detail="Batch action failed")

