# ---------- 1) Quick Actions: assign-to-me endpoint ----------
@app.post("/api/admin/mod/assign-me/{submission_id}")
async def mod_assign_me(submission_id: str, auth_ctx: Dict[str, Any] = Depends(authenticate_any)):
    try:
        require_admin(auth_ctx)
        db = db_client.walletbot
        who = auth_ctx.get("username", "admin")
        res = await db.screenshots.update_one(
            {"submission_id": submission_id, "status": "pending"},
            {"$set": {"assigned_to": who, "assigned_at": datetime.utcnow()}}
        )
        await write_audit_log("mod_assign_me", who, {"submission_id": submission_id})
        return {"success": res.matched_count > 0, "assigned_to": who}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Assign-me error: {e}")
        raise HTTPException(status_code=500, detail="Assign failed")

