# ---------- 4) Withdrawals Exception Queue (rule-based) ----------
@app.get("/api/admin/withdrawals/exceptions")
async def withdrawals_exceptions(
    amount_threshold: float = 500.0,
    window_days: int = 30,
    repeat_rejects: int = 2,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(365, window_days)))
        cur = db.withdrawal_requests.find(
            {"created_at": {"$gte": since}},
            {"_id": 0, "request_id": 1, "user_id": 1, "amount": 1, "status": 1, "method": 1}
        )
        from collections import defaultdict
        user_counts = defaultdict(int)
        user_rejects = defaultdict(int)
        items = []
        async for w in cur:
            uid = w.get("user_id")
            user_counts[uid] += 1
            if (w.get("status") or "").lower() == "rejected":
                user_rejects[uid] += 1
            if float(w.get("amount", 0.0)) >= amount_threshold:
                items.append({**w, "flag": "high_amount"})
        for uid, cnt in user_counts.items():
            if cnt >= 5:
                items.append({"user_id": uid, "flag": "many_requests", "count": cnt})
        for uid, rej in user_rejects.items():
            if rej >= repeat_rejects:
                items.append({"user_id": uid, "flag": "repeated_rejections", "count": rej})
        return {"success": True, "data": {"items": items, "window_days": window_days, "amount_threshold": amount_threshold}}
    except Exception as e:
        logger.error(f"Withdrawals exceptions error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute exceptions")

