# ---------- 2) Reviewer Goals: weekly/monthly ----------
@app.get("/api/admin/reviewer/goals-range")
async def reviewer_goals_range(
    period: str = "weekly",  # "weekly" | "monthly"
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
        goals = cfg.get("reviewer_goals") or {}
        now = datetime.utcnow()
        if period == "monthly":
            start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        else:
            # weekly: last 7 days
            start = now - timedelta(days=7)
        cur = db.screenshots.find(
            {"reviewed_at": {"$gte": start}, "status": {"$in": ["approved", "rejected"]}},
            {"_id": 0, "assigned_to": 1, "admin_notes": 1}
        )
        from collections import Counter
        done = Counter()
        async for s in cur:
            who = s.get("assigned_to")
            if not who:
                notes = s.get("admin_notes") or ""
                ix = notes.find("by:")
                if ix >= 0:
                    who = (notes[ix+3:].strip().split()[0] or "")[:32]
            if who:
                done[who] += 1
        rows = []
        all_names = set(list(goals.keys()) + list(done.keys()))
        # derive range goal = daily goal * days_in_range (best-effort)
        days_in_range = (now - start).days or 1
        for name in sorted(all_names):
            daily_goal = int(goals.get(name, 0) or 0)
            rng_goal = daily_goal * days_in_range
            d = int(done.get(name, 0))
            pct = round((d / rng_goal * 100), 1) if rng_goal > 0 else 0.0
            rows.append({"reviewer": name, "range_goal": rng_goal, "done": d, "pct": pct, "period": period, "days": days_in_range})
        rows.sort(key=lambda x: -x["pct"])
        return {"success": True, "data": rows}
    except Exception as e:
        logger.error(f"Reviewer goals range error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute range goals")

