# ---------- 3) Withdrawals Exceptions: quick actions (approve/reject single) ----------
@app.post("/api/admin/withdrawals/quick")
async def withdrawals_quick_action(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        request_id = (body.get("request_id") or "").strip()
        action = (body.get("action") or "").strip().lower()  # approve | reject
        note = (body.get("note") or "").strip()
        if not request_id or action not in ("approve","reject"):
            raise HTTPException(status_code=400, detail="Invalid request_id or action")
        q = {"request_id": request_id, "status": "pending"}
        upd = {"$set": {"status": "approved" if action=="approve" else "rejected", "processed_time": datetime.utcnow(), "admin_notes": note or f"quick-{action}"}}
        res = await db.withdrawal_requests.update_one(q, upd)
        ok = getattr(res, "modified_count", 0) > 0
        await write_audit_log("withdrawals_quick_action", username, {"request_id": request_id, "action": action, "ok": ok})
        return {"success": ok}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Withdrawals quick action error: {e}")
        raise HTTPException(status_code=500, detail="Quick action failed")

