# ---------- 4) Safer Markdown renderer: extra sanitization ----------
def _md_to_html_safer(md: str) -> str:
    import re, html
    text = md or ""
    # escape all first
    text = html.escape(text)
    # headings
    lines = []
    for ln in text.splitlines():
        if ln.startswith("#### "):
            lines.append(f"<h4>{ln[5:]}</h4>")
        elif ln.startswith("### "):
            lines.append(f"<h3>{ln[4:]}</h3>")
        elif ln.startswith("## "):
            lines.append(f"<h2>{ln[3:]}</h2>")
        elif ln.startswith("# "):
            lines.append(f"<h1>{ln[2:]}</h1>")
        else:
            lines.append(ln)
    html_text = "\n".join(lines)
    # bold/italic (non-greedy)
    html_text = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", html_text)
    html_text = re.sub(r"(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)", r"<em>\1</em>", html_text)
    # links safe
    def _link(m):
        t = m.group(1)
        u = m.group(2)
        ul = u.lower().strip()
        if ul.startswith("javascript:") or ul.startswith("data:"):
            return t
        return f'<a href="{u}" target="_blank" rel="noopener noreferrer">{t}</a>'
    html_text = re.sub(r"\[([^\]]+)\]\(([^)]+)\)", _link, html_text)
    # line breaks
    html_text = html_text.replace("\n\n", "<br/><br/>")
    return html_text

