# ---------- 1) Reviewer Time-on-Task (assignment → review duration percentiles) ----------
@app.get("/api/admin/reviewer/time-on-task")
async def reviewer_time_on_task(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Computes durations (minutes) between assigned_at and reviewed_at for approved/rejected items within window.
    Returns overall distribution percentiles and per-reviewer aggregates.
    """
    try:
        db = db_client.walletbot
        days = max(1, min(180, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.screenshots.find(
            {
                "reviewed_at": {"$gte": since},
                "status": {"$in": ["approved", "rejected"]},
                "assigned_at": {"$exists": True}
            },
            {"_id": 0, "assigned_to": 1, "assigned_at": 1, "reviewed_at": 1}
        )
        from collections import defaultdict
        per = defaultdict(list)  # reviewer -> [minutes]
        overall = []
        async for s in cur:
            at = s.get("assigned_at")
            rt = s.get("reviewed_at")
            if not at or not rt:
                continue
            mins = max(0.0, (rt - at).total_seconds() / 60.0)
            who = s.get("assigned_to") or "unknown"
            per[who].append(mins)
            overall.append(mins)

        def pct(arr, p):
            if not arr: return 0.0
            a = sorted(arr)
            k = max(0, min(len(a)-1, int(round((p/100.0)*(len(a)-1)))))
            return round(a[k], 2)

        summary = {
            "count": len(overall),
            "p50": pct(overall, 50),
            "p90": pct(overall, 90),
            "p95": pct(overall, 95),
            "p99": pct(overall, 99),
            "avg": round(sum(overall)/len(overall), 2) if overall else 0.0
        }
        rows = []
        for r, arr in per.items():
            rows.append({
                "reviewer": r,
                "count": len(arr),
                "avg": round(sum(arr)/len(arr), 2) if arr else 0.0,
                "p50": pct(arr, 50),
                "p90": pct(arr, 90),
                "p95": pct(arr, 95),
                "p99": pct(arr, 99),
            })
        rows.sort(key=lambda x: x["p90"])
        return {"success": True, "data": {"summary": summary, "reviewers": rows, "window_days": days}}
    except Exception as e:
        logger.error(f"Time-on-task error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute time-on-task")

