@app.post("/api/admin/campaigns/priority")
async def campaigns_priority_set(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    """
    Sets campaign priority weights. Body: { "campaign_priority": { "camp123": 10, ... } }
    """
    try:
        db = db_client.walletbot
        pri = body.get("campaign_priority") or {}
        await db.bot_settings.update_one({"type": "main_config"}, {"$set": {"campaign_priority": pri, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("campaign_priority_set", username, {"keys": list(pri.keys())})
        return {"success": True}
    except Exception as e:
        logger.error(f"Priority set error: {e}")
        raise HTTPException(status_code=500, detail="Failed to save priority")

@app.get("/api/admin/mod/queue-priority")
async def mod_queue_priority(
    limit: int = 100,
    username: str = Depends(authenticate_admin)
):
    """
    Returns pending screenshots ordered by campaign weight (desc) then by created_at asc.
    """
    try:
        db = db_client.walletbot
        limit = max(1, min(300, int(limit)))
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
        pri = cfg.get("campaign_priority") or {}
        cur = db.screenshots.find({"status": "pending"}).sort([("created_at", 1)]).limit(2000)
        items = await cur.to_list(length=2000)
        def score(it):
            return float(pri.get(it.get("campaign_id"), 0))
        ordered = sorted(items, key=lambda x: (-score(x), x.get("created_at")))
        return {"success": True, "data": ordered[:limit], "weights": pri}
    except Exception as e:
        logger.error(f"Queue priority error: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch queue")

