# ---------- 3) Withdrawals SLA Breach Panel ----------
@app.get("/api/admin/withdrawals/breach")
async def withdrawals_breach(
    max_hours: int = 48,
    username: str = Depends(authenticate_admin)
):
    """
    Lists pending withdrawals older than max_hours and summary by method.
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        cutoff = now - timedelta(hours=max(1, min(240, int(max_hours))))
        cur = db.withdrawal_requests.find({"status": "pending"}, {"_id": 0, "request_id": 1, "user_id": 1, "amount": 1, "method": 1, "created_at": 1})
        from collections import defaultdict
        breaches = []
        by_method = defaultdict(lambda: {"count":0, "amount":0.0})
        async for w in cur:
            ct = w.get("created_at") or now
            age_h = max(0.0, (now - ct).total_seconds()/3600.0)
            if age_h >= max_hours:
                breaches.append({
                    "request_id": w.get("request_id"),
                    "user_id": w.get("user_id"),
                    "amount": round(float(w.get("amount", 0.0) or 0.0), 2),
                    "method": w.get("method"),
                    "age_hours": round(age_h, 1)
                })
                m = (w.get("method") or "unknown").lower()
                by_method[m]["count"] += 1
                by_method[m]["amount"] += float(w.get("amount", 0.0) or 0.0)
        for m in by_method:
            by_method[m]["amount"] = round(by_method[m]["amount"], 2)
        breaches.sort(key=lambda x: -x["age_hours"])
        return {"success": True, "data": {"breaches": breaches, "by_method": by_method, "threshold_hours": max_hours}}
    except Exception as e:
        logger.error(f"Withdrawals breach error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute breaches")

