@app.get("/api/admin/runbook/search")
async def runbook_search(
    q: str,
    limit: int = 50,
    username: str = Depends(authenticate_admin)
):
    """
    Simple case-insensitive substring search in title/content.
    """
    try:
        db = db_client.walletbot
        limit = max(1, min(200, int(limit)))
        query = (q or "").strip()
        if not query:
            return {"success": True, "data": []}
        regex = {"$regex": query, "$options": "i"}
        cur = db.admin_notes_pages.find(
            {"$or": [{"title": regex}, {"content": regex}]},
            {"_id": 0, "slug": 1, "title": 1, "updated_at": 1}
        ).sort("updated_at", -1).limit(limit)
        items = await cur.to_list(length=limit)
        return {"success": True, "data": items}
    except Exception as e:
        logger.error(f"Runbook search error: {e}")
        raise HTTPException(status_code=500, detail="Search failed")

