# ---------- 1) Reviewer Load Heatmap (hourly approvals/rejections) ----------
@app.get("/api/admin/reviewer/heatmap")
async def reviewer_heatmap(
    days: int = 14,
    username: str = Depends(authenticate_admin)
):
    """
    Builds an hourly heatmap: for each reviewer and hour(0-23), count approvals+rejections in window.
    """
    try:
        db = db_client.walletbot
        days = max(1, min(90, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.screenshots.find(
            {"reviewed_at": {"$gte": since}, "status": {"$in": ["approved", "rejected"]}},
            {"_id": 0, "assigned_to": 1, "admin_notes": 1, "reviewed_at": 1}
        )
        from collections import defaultdict
        grid = defaultdict(lambda: [0]*24)  # reviewer -> 
        async for s in cur:
            who = s.get("assigned_to")
            if not who:
                notes = s.get("admin_notes") or ""
                ix = notes.find("by:")
                if ix >= 0:
                    who = (notes[ix+3:].strip().split() or "")[:32]
            if not who:
                who = "unknown"
            t = s.get("reviewed_at") or datetime.utcnow()
            hr = getattr(t, "hour", 0)
            grid[who][hr] += 1
        rows = [{"reviewer": r, "hours": arr} for r, arr in grid.items()]
        rows.sort(key=lambda x: -sum(x["hours"]))
        return {"success": True, "data": {"rows": rows, "window_days": days}}
    except Exception as e:
        logger.error(f"Reviewer heatmap error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build heatmap")

