# ---------- 2) Campaign Anomaly Spikes (moving window std-dev) ----------
@app.get("/api/admin/campaigns/spikes")
async def campaigns_spikes(
    days: int = 30,
    window: int = 7,
    z: float = 2.5,
    username: str = Depends(authenticate_admin)
):
    """
    Flags campaigns whose latest day's submissions exceed mean+z*std of the previous window.
    """
    try:
        db = db_client.walletbot
        days = max(8, min(90, int(days)))
        window = max(3, min(14, int(window)))
        z = max(1.0, min(5.0, float(z)))
        since = datetime.utcnow() - timedelta(days=days)
        pipe = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {"_id": {"day": {"$dateToString": {"format":"%Y-%m-%d","date":"$created_at"}}, "campaign_id": "$campaign_id"}, "cnt": {"$sum": 1}}},
            {"$sort": {"_id.campaign_id": 1, "_id.day": 1}}
        ]
        daily = await db.screenshots.aggregate(pipe).to_list(length=10000)
        from collections import defaultdict, deque
        series = defaultdict(list)
        for r in daily:
            cid = r["_id"]["campaign_id"]
            day = r["_id"]["day"]
            series[cid].append((day, r["cnt"]))
        spikes = []
        import statistics
        for cid, arr in series.items():
            if len(arr) <= window: 
                continue
            vals = [v for _, v in arr]
            hist = deque(vals[:window], maxlen=window)
            for i in range(window, len(vals)):
                prev = list(hist)
                mean = sum(prev)/len(prev)
                std = statistics.pstdev(prev) if len(prev)>1 else 0.0
                latest = vals[i]
                if std == 0:
                    if latest > mean and latest >= mean + 5:
                        spikes.append({"campaign_id": cid, "day": arr[i][0], "value": latest, "mean": round(mean,2), "std": round(std,2), "z": None})
                else:
                    if latest > mean + z*std:
                        spikes.append({"campaign_id": cid, "day": arr[i], "value": latest, "mean": round(mean,2), "std": round(std,2), "z": round((latest-mean)/std,2)})
                hist.append(latest)
        spikes.sort(key=lambda x: -x["value"])
        return {"success": True, "data": {"spikes": spikes, "window": window, "z": z, "window_days": days}}
    except Exception as e:
        logger.error(f"Campaign spikes error: {e}")
        raise HTTPException(status_code=500, detail="Failed to detect spikes")

