@app.post("/api/admin/runbook/version/restore/{slug}")
async def runbook_version_restore(
    slug: str,
    saved_at_iso: str,
    username: str = Depends(authenticate_admin)
):
    """
    Restores a specific snapshot by saved_at ISO time (exact match).
    """
    try:
        db = db_client.walletbot
        snap = await db.admin_notes_versions.find_one({"slug": slug, "saved_at": saved_at_iso})
        if not snap:
            # fallback: parse ISO to datetime and search nearest
            from dateutil import parser
            try:
                dt = parser.parse(saved_at_iso)
                snap = await db.admin_notes_versions.find_one({"slug": slug, "saved_at": dt})
            except Exception:
                pass
        if not snap:
            raise HTTPException(status_code=404, detail="Snapshot not found")
        await db.admin_notes_pages.update_one(
            {"slug": slug},
            {"$set": {"title": snap.get("title"), "content": snap.get("content"), "updated_by": username, "updated_at": datetime.utcnow()}},
            upsert=True
        )
        await write_audit_log("runbook_version_restore", username, {"slug": slug, "saved_at": saved_at_iso})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Runbook version restore error: {e}")
        raise HTTPException(status_code=500, detail="Failed to restore version")

