# ---------- 1) Screenshot Reviewer Collision Guard ----------
@app.get("/api/admin/mod/collision-check/{submission_id}")
async def mod_collision_check(submission_id: str, username: str = Depends(authenticate_admin)):
    """
    Returns current assignment info for a screenshot to prevent accidental double-assignment.
    """
    try:
        db = db_client.walletbot
        s = await db.screenshots.find_one({"submission_id": submission_id}, {"_id": 0, "assigned_to": 1, "assigned_at": 1, "status": 1})
        if not s:
            raise HTTPException(status_code=404, detail="Submission not found")
        return {"success": True, "data": s}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Collision check error: {e}")
        raise HTTPException(status_code=500, detail="Failed to check assignment")

@app.post("/api/admin/mod/assign-safe/{submission_id}")
async def mod_assign_safe(submission_id: str, body: Dict[str, Any], auth_ctx: Dict[str, Any] = Depends(authenticate_any)):
    """
    Assigns only if unassigned or assigned_to == current user; else returns a warning.
    """
    try:
        require_admin(auth_ctx)
        db = db_client.walletbot
        who = auth_ctx.get("username", "admin")
        s = await db.screenshots.find_one({"submission_id": submission_id}, {"_id": 0, "assigned_to": 1, "status": 1})
        if not s:
            raise HTTPException(status_code=404, detail="Submission not found")
        current = (s.get("assigned_to") or "").strip()
        if current and current != who and s.get("status") == "pending":
            return {"success": False, "warning": f"Already assigned to {current}"}
        res = await db.screenshots.update_one(
            {"submission_id": submission_id, "status": "pending"},
            {"$set": {"assigned_to": who, "assigned_at": datetime.utcnow()}}
        )
        await write_audit_log("mod_assign_safe", who, {"submission_id": submission_id, "took_over": bool(current and current != who)})
        return {"success": getattr(res, "matched_count", 0) > 0, "assigned_to": who}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Assign-safe error: {e}")
        raise HTTPException(status_code=500, detail="Assign failed")

