# ---------- 2) Campaign Pacing Auto-Suggest ----------
@app.post("/api/admin/campaigns/pacing/suggest")
async def campaign_pacing_suggest(
    days: int = 14,
    multiplier: float = 1.1,
    username: str = Depends(authenticate_admin)
):
    """
    Suggests new per-campaign daily targets from recent daily averages * multiplier.
    Does not apply automatically—returns suggestion map.
    """
    try:
        db = db_client.walletbot
        days = max(7, min(60, int(days)))
        multiplier = max(0.5, min(3.0, float(multiplier)))
        since = datetime.utcnow() - timedelta(days=days)
        pipe = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {"_id": {"day": {"$dateToString": {"format":"%Y-%m-%d", "date": "$created_at"}}, "campaign_id": "$campaign_id"}, "cnt": {"$sum": 1}}},
            {"$group": {"_id": "$_id.campaign_id", "avg_per_day": {"$avg": "$cnt"}, "days": {"$sum": 1}}},
        ]
        agg = await db.screenshots.aggregate(pipe).to_list(length=5000)
        suggestions = {}
        for r in agg:
            cid = r["_id"]
            avg = float(r.get("avg_per_day", 0.0) or 0.0)
            suggestions[cid] = int(round(avg * multiplier))
        return {"success": True, "data": {"suggestions": suggestions, "window_days": days, "multiplier": multiplier}}
    except Exception as e:
        logger.error(f"Pacing suggest error: {e}")
        raise HTTPException(status_code=500, detail="Failed to suggest targets")

