# ---------- 3) Withdrawal Risk Scoring (simple weighted rules) ----------
def _risk_score_for_withdrawal(w: Dict[str, Any]) -> Dict[str, Any]:
    # Example heuristic scoring: base 0..100
    score = 0
    reasons = []
    amt = float(w.get("amount", 0.0) or 0.0)
    status = (w.get("status") or "").lower()
    method = (w.get("method") or "").lower()
    if amt >= 1000: score += 30; reasons.append("high_amount")
    elif amt >= 500: score += 18; reasons.append("medium_amount")
    if method == "upi" and amt >= 700: score += 10; reasons.append("upi_large")
    if status == "pending": score += 5; reasons.append("still_pending")
    # Add rule: if user has >=2 rejected last 30d -> +20
    return {"score": min(100, score), "reasons": reasons}

@app.get("/api/admin/withdrawals/risk")
async def withdrawals_risk(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Computes risk scores for recent withdrawals; returns top N by score with color badge.
    """
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(90, int(days))))
        cur = db.withdrawal_requests.find({"created_at": {"$gte": since}}, {"_id": 0, "request_id": 1, "user_id": 1, "amount": 1, "method": 1, "status": 1, "created_at": 1}).limit(5000)
        items = []
        async for w in cur:
            rs = _risk_score_for_withdrawal(w)
            badge = "green"
            if rs["score"] >= 70: badge = "red"
            elif rs["score"] >= 40: badge = "yellow"
            items.append({**w, "risk": rs["score"], "reasons": rs["reasons"], "badge": badge})
        items.sort(key=lambda x: -x["risk"])
        return {"success": True, "data": items[:500]}
    except Exception as e:
        logger.error(f"Withdrawals risk error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute risk")

