@app.post("/api/admin/mod/assign-takeover/{submission_id}")
async def mod_assign_takeover(
    submission_id: str,
    body: Dict[str, Any],
    auth_ctx: Dict[str, Any] = Depends(authenticate_any)
):
    """
    Force-assign with explicit takeover confirmation flag.
    Body: { confirm: true }
    """
    try:
        require_admin(auth_ctx)
        db = db_client.walletbot
        who = auth_ctx.get("username", "admin")
        if not bool(body.get("confirm")):
            raise HTTPException(status_code=400, detail="Confirmation required")
        res = await db.screenshots.update_one(
            {"submission_id": submission_id, "status": "pending"},
            {"$set": {"assigned_to": who, "assigned_at": datetime.utcnow()}}
        )
        await write_audit_log("mod_assign_takeover", who, {"submission_id": submission_id})
        return {"success": getattr(res, "matched_count", 0) > 0, "assigned_to": who}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Assign takeover error: {e}")
        raise HTTPException(status_code=500, detail="Takeover failed")

