@app.post("/api/admin/campaigns/pacing/apply")
async def campaign_pacing_apply(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Applies per_campaign targets into main_config.pacing.per_campaign.
    Body: { per_campaign: { "camp123": 120, ... }, overwrite: true/false }
    """
    try:
        db = db_client.walletbot
        inp = body.get("per_campaign") or {}
        overwrite = bool(body.get("overwrite", False))
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {"type":"main_config"}
        pacing = cfg.get("pacing") or {}
        existing = pacing.get("per_campaign") or {}
        merged = (inp if overwrite else {**existing, **inp})
        pacing["per_campaign"] = merged
        await db.bot_settings.update_one({"type":"main_config"}, {"$set": {"pacing": pacing, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("campaign_pacing_apply", username, {"count": len(inp), "overwrite": overwrite})
        return {"success": True, "applied_count": len(inp)}
    except Exception as e:
        logger.error(f"Pacing apply error: {e}")
        raise HTTPException(status_code=500, detail="Failed to apply pacing")

