# ---------- 3) Withdrawals Risk Filter + CSV Export ----------
@app.get("/api/admin/withdrawals/risk-filter")
async def withdrawals_risk_filter(
    min_score: int = 40,
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Returns withdrawals with risk>=min_score within window.
    """
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(90, int(days))))
        cur = db.withdrawal_requests.find({"created_at": {"$gte": since}}, {"_id": 0, "request_id": 1, "user_id": 1, "amount": 1, "method": 1, "status": 1, "created_at": 1})
        out = []
        async for w in cur:
            rs = _risk_score_for_withdrawal(w)
            if rs["score"] >= int(min_score):
                out.append({**w, "risk": rs["score"], "reasons": rs["reasons"]})
        out.sort(key=lambda x: -x["risk"])
        return {"success": True, "data": out[:2000]}
    except Exception as e:
        logger.error(f"Risk filter error: {e}")
        raise HTTPException(status_code=500, detail="Failed to filter")

@app.get("/api/admin/withdrawals/risk-export.csv")
async def withdrawals_risk_export_csv(
    min_score: int = 40,
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Streams CSV of high-risk withdrawals (admin-only).
    """
    try:
        j = await withdrawals_risk_filter(min_score=min_score, days=days, username=username)  # reuse
        data = j.get("data", [])
        rows = ["request_id,user_id,amount,method,status,risk,reasons,created_at\n"]
        for it in data:
            reasons = ";".join(it.get("reasons", []))
            rows.append(",".join([
                str(it.get("request_id","")),
                str(it.get("user_id","")),
                str(it.get("amount","")),
                str(it.get("method","")),
                str(it.get("status","")),
                str(it.get("risk","")),
                '"'+reasons.replace('"','""')+'"',
                str(it.get("created_at",""))
            ]) + "\n")
        blob = "".join(rows).encode("utf-8")
        headers = {"Content-Disposition": "attachment; filename=withdrawals_risk.csv"}
        return StreamingResponse(io.BytesIO(blob), media_type="text/csv", headers=headers)
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Risk export error: {e}")
        raise HTTPException(status_code=500, detail="Failed to export")

