# ---------- 1) Reviewer Takeover Analytics ----------
@app.get("/api/admin/reviewer/takeovers")
async def reviewer_takeovers(
    days: int = 60,
    username: str = Depends(authenticate_admin)
):
    """
    Aggregates 'mod_assign_takeover' audit log entries by reviewer and day.
    Expects audit_logs entries created via prior takeover endpoints.
    """
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(365, int(days))))
        cur = db.audit_logs.find(
            {"action": "mod_assign_takeover", "created_at": {"$gte": since}},
            {"_id": 0, "actor": 1, "created_at": 1, "meta": 1}
        )
        from collections import Counter, defaultdict
        total_by_user = Counter()
        daily = defaultdict(lambda: defaultdict(int))  # day -> actor -> count
        async for a in cur:
            who = a.get("actor") or "admin"
            day = a.get("created_at").date().isoformat() if hasattr(a.get("created_at"), "date") else str(a.get("created_at"))[:10]
            total_by_user[who] += 1
            daily[day][who] += 1
        totals = [{"reviewer": k, "count": v} for k, v in total_by_user.most_common()]
        series = []
        for d, m in sorted(daily.items()):
            row = {"day": d}
            for k, v in m.items():
                row[k] = v
            series.append(row)
        return {"success": True, "data": {"totals": totals, "series": series, "window_days": days}}
    except Exception as e:
        logger.error(f"Reviewer takeovers error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute takeovers")

