# ---------- 2) Pacing Drift Alerts ----------
@app.get("/api/admin/campaigns/pacing/drift")
async def campaign_pacing_drift(
    days: int = 14,
    threshold_pct: float = 30.0,
    username: str = Depends(authenticate_admin)
):
    """
    Compares actual average per-day to target for top active campaigns.
    Flags those with |drift| >= threshold_pct.
    """
    try:
        db = db_client.walletbot
        days = max(7, min(60, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
        targets = (cfg.get("pacing") or {}).get("per_campaign", {}) or {}
        pipe = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {"_id": "$campaign_id", "count": {"$sum": 1}}},
        ]
        totals = await db.screenshots.aggregate(pipe).to_list(length=5000)
        out = []
        for r in totals:
            cid = r["_id"]
            avg = r["count"]/days
            tgt = float(targets.get(cid, 0) or 0.0)
            if tgt > 0:
                drift_pct = ((avg - tgt) / tgt) * 100.0
                if abs(drift_pct) >= float(threshold_pct):
                    out.append({"campaign_id": cid, "avg_per_day": round(avg,2), "target": tgt, "drift_pct": round(drift_pct,1)})
        out.sort(key=lambda x: -abs(x["drift_pct"]))
        return {"success": True, "data": {"alerts": out, "window_days": days, "threshold_pct": threshold_pct}}
    except Exception as e:
        logger.error(f"Pacing drift error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute drift")

