@app.get("/api/admin/withdrawals/risk-preview")
async def risk_preview(
    min_score: int = 40,
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        rules = (cfg.get("risk_rules") or {}).get("withdrawals") or {}
        since = datetime.utcnow() - timedelta(days=max(1, min(90, int(days))))
        cur = db.withdrawal_requests.find({"created_at": {"$gte": since}}, {"_id": 0, "request_id": 1, "user_id": 1, "amount": 1, "method": 1, "status": 1, "created_at": 1})
        out = []
        async for w in cur:
            rs = _risk_score_with_rules(w, rules)
            if rs["score"] >= int(min_score):
                out.append({**w, "risk": rs["score"], "reasons": rs["reasons"]})
        out.sort(key=lambda x: -x["risk"])
        return {"success": True, "data": out[:2000], "rules": rules}
    except Exception as e:
        logger.error(f"Risk preview error: {e}")
        raise HTTPException(status_code=500, detail="Failed to preview")

