@app.get("/api/admin/quiet-hours/monitor")
async def quiet_hours_monitor_api(
    days: int = 3,
    username: str = Depends(authenticate_admin)
):
    """
    Returns recent per-hour submission counts for the given window.
    """
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(7, int(days))))
        pipe = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {"_id": {"hour": {"$dateToString": {"format":"%H","date":"$created_at"}}}, "count": {"$sum": 1}}},
            {"$sort": {"_id.hour": 1}}
        ]
        hourly = await db.screenshots.aggregate(pipe).to_list(length=1000)
        data = [{"hour": r["_id"]["hour"], "count": r["count"]} for r in hourly]
        return {"success": True, "data": data}
    except Exception as e:
        logger.error(f"Quiet hours monitor error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load monitor")

