# ---------- 3) Withdrawals Reconciliation Timeline ----------
# Merges: withdrawal_requests status changes + withdrawal_touch_log entries (if any)

@app.get("/api/admin/withdrawals/timeline/{request_id}")
async def withdrawals_timeline_api(request_id: str, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        req = await db.withdrawal_requests.find_one({"request_id": request_id}) or {}
        # status transitions might not be stored separately; so we present created_at and processed_time as milestones
        events = []
        if req.get("created_at"):
            events.append({"kind": "created", "at": req["created_at"], "by": req.get("created_by")})
        if req.get("processed_time"):
            events.append({"kind": req.get("status","processed"), "at": req["processed_time"], "by": req.get("processed_by"), "note": req.get("admin_notes")})
        # touches
        cur = db.withdrawal_touch_log.find({"request_id": request_id}, {"_id": 0}).sort("at", 1)
        touch = await cur.to_list(length=500)
        for t in touch:
            events.append({"kind": "touch", "at": t.get("at"), "by": t.get("by"), "note": t.get("note"), "action": t.get("action")})
        # sort by time
        def _ts(e):
            return e.get("at")
        events.sort(key=_ts)
        # compute age hours
        now = datetime.utcnow()
        age_h = None
        if req.get("created_at"):
            age_h = round((now - req["created_at"]).total_seconds()/3600.0, 1)
        return {"success": True, "data": {"request": {"request_id": request_id, "status": req.get("status"), "amount": req.get("amount"), "method": req.get("method")}, "events": events, "age_hours": age_h}}
    except Exception as e:
        logger.error(f"Withdrawals timeline error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build timeline")

