# ---------- 4) Runbook Broken Links Checker ----------
# Checks http(s) links in a page content; attempts HEAD then GET with short timeout.

@app.get("/api/admin/runbook/links/{slug}")
async def runbook_links_check_api(
    slug: str,
    max_links: int = 50,
    username: str = Depends(authenticate_admin)
):
    import re, asyncio
    try:
        db = db_client.walletbot
        doc = await db.admin_notes_pages.find_one({"slug": slug}) or {}
        content = doc.get("content") or ""
        # extract markdown links [text](url)
        links = re.findall(r"\[([^\]]+)\]\((https?://[^)]+)\)", content)[:max(1, min(200, int(max_links)))]
        urls = [u for _, u in links]

        async def check(url):
            import aiohttp
            try:
                timeout = aiohttp.ClientTimeout(total=6)
                async with aiohttp.ClientSession(timeout=timeout) as sess:
                    # Try HEAD
                    try:
                        async with sess.head(url, allow_redirects=True) as resp:
                            return {"url": url, "status": resp.status}
                    except Exception:
                        pass
                    # Fallback GET
                    async with sess.get(url, allow_redirects=True) as resp:
                        return {"url": url, "status": resp.status}
            except Exception as e:
                return {"url": url, "error": str(e)}

        results = []
        if urls:
            tasks = [check(u) for u in urls]
            results = await asyncio.gather(*tasks, return_exceptions=False)
        return {"success": True, "data": results}
    except Exception as e:
        logger.error(f"Runbook links check error: {e}")
        raise HTTPException(status_code=500, detail="Failed to check links")

