# ---------- 1) Full-Text Style Search: Screenshots + Audit Logs (regex + pagination) ----

@app.get("/api/admin/search/screenshots")
async def search_screenshots_api(
    q: str,
    page: int = 1,
    page_size: int = 50,
    username: str = Depends(authenticate_admin)
):
    """
    Regex search on screenshots filename, admin_notes, campaign_id (case-insensitive).
    """
    import re
    try:
        db = db_client.walletbot
        page = max(1, int(page))
        page_size = max(10, min(200, int(page_size)))
        pattern = {"$regex": q, "$options": "i"}
        cond = {"$or": [
            {"filename": pattern},
            {"admin_notes": pattern},
            {"campaign_id": pattern},
            {"submission_id": pattern}
        ]}
        cur = db.screenshots.find(cond, {"_id": 0}).sort("created_at", -1).skip((page-1)*page_size).limit(page_size)
        items = await cur.to_list(length=page_size)
        total = await db.screenshots.count_documents(cond)
        return {"success": True, "data": {"page": page, "page_size": page_size, "total": total, "items": items}}
    except Exception as e:
        logger.error(f"Search screenshots error: {e}")
        raise HTTPException(status_code=500, detail="Search failed")

@app.get("/api/admin/search/audits")
async def search_audits_api(
    q: str,
    page: int = 1,
    page_size: int = 50,
    username: str = Depends(authenticate_admin)
):
    """
    Regex search on audit_logs: action, actor, meta as stringified JSON.
    """
    import re, json
    try:
        db = db_client.walletbot
        page = max(1, int(page))
        page_size = max(10, min(200, int(page_size)))
        pattern = {"$regex": q, "$options": "i"}
        cond = {"$or": [
            {"action": pattern},
            {"actor": pattern},
            {"meta_str": pattern}
        ]}
        # materialize meta_str for search (lightweight cache technique)
        # On-the-fly: project meta to string
        pipe = [
            {"$addFields": {"meta_str": {"$convert": {"input": {"$toString": "$meta"}, "to": "string", "onError": ""}}}},
            {"$match": cond},
            {"$sort": {"created_at": -1}},
            {"$skip": (page-1)*page_size},
            {"$limit": page_size},
            {"$project": {"_id": 0, "action": 1, "actor": 1, "created_at": 1, "meta": 1}}
        ]
        items = await db.audit_logs.aggregate(pipe).to_list(length=page_size)
        # total estimate (without meta_str stage for performance, acceptable approximation)
        total_est = await db.audit_logs.count_documents({"$or": [{"action": pattern}, {"actor": pattern}]})
        return {"success": True, "data": {"page": page, "page_size": page_size, "total_estimate": total_est, "items": items}}
    except Exception as e:
        logger.error(f"Search audits error: {e}")
        raise HTTPException(status_code=500, detail="Search failed")

