@app.get("/api/admin/export/users.csv")
async def export_users_csv(
    min_balance: float = 0.0,
    created_since_days: int = 0,
    username: str = Depends(authenticate_admin)
):
    """
    Streams users filtered by wallet_balance and optional created_at window.
    """
    try:
        db = db_client.walletbot
        q = {"wallet_balance": {"$gte": float(min_balance)}}
        if created_since_days and int(created_since_days) > 0:
            since = datetime.utcnow() - timedelta(days=int(created_since_days))
            q["created_at"] = {"$gte": since}
        cur = db.users.find(q, {"_id": 0, "user_id": 1, "username": 1, "wallet_balance": 1, "created_at": 1})
        rows = ["user_id,username,wallet_balance,created_at\n"]
        async for u in cur:
            rows.append(",".join([
                str(u.get("user_id","")),
                '"'+str(u.get("username","")).replace('"','""')+'"',
                str(u.get("wallet_balance","")),
                str(u.get("created_at",""))
            ]) + "\n")
        blob = "".join(rows).encode("utf-8")
        headers = {"Content-Disposition": "attachment; filename=users_filtered.csv"}
        return StreamingResponse(io.BytesIO(blob), media_type="text/csv", headers=headers)
    except Exception as e:
        logger.error(f"Export users csv error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

@app.get("/api/admin/export/transactions.csv")
async def export_transactions_csv(
    min_amount: float = 0.0,
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    Streams transactions filtered by absolute amount threshold and created_at window.
    """
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(365, int(days))))
        cur = db.transactions.find(
            {"created_at": {"$gte": since}},
            {"_id": 0, "tx_id": 1, "user_id": 1, "amount": 1, "type": 1, "created_at": 1}
        )
        rows = ["tx_id,user_id,amount,type,created_at\n"]
        async for t in cur:
            amt = float(t.get("amount", 0.0) or 0.0)
            if abs(amt) < float(min_amount):
                continue
            rows.append(",".join([
                str(t.get("tx_id","")),
                str(t.get("user_id","")),
                str(amt),
                str(t.get("type","")),
                str(t.get("created_at",""))
            ]) + "\n")
        blob = "".join(rows).encode("utf-8")
        headers = {"Content-Disposition": "attachment; filename=transactions_filtered.csv"}
        return StreamingResponse(io.BytesIO(blob), media_type="text/csv", headers=headers)
    except Exception as e:
        logger.error(f"Export tx csv error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

