# ---------- 3) Lightweight RBAC Scaffold (roles + guards + simple UI) --------------------

# Roles stored in bot_settings.main_config.rbac:
# { "roles": { "alice": ["admin","reviewer"], "bob": ["reviewer"] }, "permissions": { "exports": ["admin"], "risk_tools": ["admin","operator"] } }

def has_role(auth_ctx: Dict[str, Any], role: str) -> bool:
    return role in (auth_ctx.get("roles") or [])

async def load_roles_map() -> Dict[str, Any]:
    db = db_client.walletbot
    cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
    return (cfg.get("rbac") or {}).get("roles") or {}

async def attach_roles(auth_ctx: Dict[str, Any]) -> Dict[str, Any]:
    # Augment auth_ctx with roles from settings
    try:
        roles_map = await load_roles_map()
        u = auth_ctx.get("username")
        auth_ctx["roles"] = roles_map.get(u, [])
    except Exception:
        auth_ctx["roles"] = auth_ctx.get("roles") or []
    return auth_ctx

