# ========================================================================================
#  CHUNK AD: Fine-grained Route Guards, Admin Sessions Viewer/Revoke,
#            Slow Query Sampler, Simple Backups Trigger/Download
#  Notes:
#    - Additive endpoints + pages; uses existing helpers: authenticate_admin, authenticate_any,
#      db_client, write_audit_log, HTMLResponse, HTTPException, Depends, StreamingResponse, datetime, io, json, os
# ========================================================================================

# ---------- 1) Fine-grained Route Guards (permission gates) ------------------------------

# Permissions config in bot_settings.main_config.rbac.permissions:
# Example:
# {
#   "exports": ["admin"],
#   "risk_tools": ["admin","operator"],
#   "backups": ["admin"],
#   "sessions": ["admin"],
#   "slow_queries": ["admin","operator"]
# }

async def _get_permissions_map() -> Dict[str, Any]:
    db = db_client.walletbot
    cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
    return (cfg.get("rbac") or {}).get("permissions") or {}

async def _user_roles(username: str) -> list:
    db = db_client.walletbot
    cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
    roles = (cfg.get("rbac") or {}).get("roles") or {}
    return roles.get(username, [])

async def require_permission(username: str, perm: str):
    perms = await _get_permissions_map()
    roles_need = perms.get(perm) or []
    if not roles_need:
        return  # open if not specified
    roles = await _user_roles(username)
    if any(r in roles for r in roles_need):
        return
    raise HTTPException(status_code=403, detail=f"Missing permission: {perm}")

# Example protected helper wrapper (use inside endpoints):
# await require_permission(username, "exports")

# ---------- 2) Admin Sessions Viewer + Revoke -------------------------------------------

# Sessions collection format (example best-effort):
# admin_sessions: { username, created_at, last_seen, ip, ua, token, active }

@app.get("/api/admin/sessions")
async def admin_sessions_list(username: str = Depends(authenticate_admin)):
    try:
        await require_permission(username, "sessions")
        db = db_client.walletbot
        cur = db.admin_sessions.find({}, {"_id": 0}).sort("last_seen", -1).limit(1000)
        items = await cur.to_list(length=1000)
        return {"success": True, "data": items}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Sessions list error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load sessions")

@app.post("/api/admin/sessions/revoke")
async def admin_sessions_revoke(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        await require_permission(username, "sessions")
        token = (body.get("token") or "").strip()
        if not token:
            raise HTTPException(status_code=400, detail="token required")
        db = db_client.walletbot
        res = await db.admin_sessions.update_one({"token": token}, {"$set": {"active": False, "revoked_at": datetime.utcnow(), "revoked_by": username}})
        await write_audit_log("admin_session_revoke", username, {"token": token, "matched": getattr(res, "matched_count", 0)})
        return {"success": getattr(res, "matched_count", 0) > 0}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Session revoke error: {e}")
        raise HTTPException(status_code=500, detail="Failed to revoke session")

