# ---------- 3) Slow Query Sampler (capture + viewer) ------------------------------------

# Lightweight in-memory sampler with optional DB persist

_slow_queries: list = []
_SLOW_MAX = 1000
_SLOW_THRESHOLD_MS = 200  # configurable by settings if desired

def record_slow_query(label: str, ms: int, meta: Dict[str, Any] = None):
    try:
        if ms < _SLOW_THRESHOLD_MS:
            return
        entry = {"label": label, "ms": ms, "meta": meta or {}, "ts": datetime.utcnow().isoformat()}
        _slow_queries.append(entry)
        if len(_slow_queries) > _SLOW_MAX:
            del _slow_queries[:len(_slow_queries)-_SLOW_MAX]
    except Exception:
        pass

@app.get("/api/admin/slow-queries")
async def slow_queries_api(username: str = Depends(authenticate_admin)):
    try:
        await require_permission(username, "slow_queries")
        return {"success": True, "data": list(reversed(_slow_queries[-500:]))}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Slow queries get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load slow queries")

