# ---------- 4) Simple Backups: Trigger + Download (JSON dumps) ---------------------------

# Dumps selected collections to JSON bundles and streams them

BACKUP_DIR = "backups"
os.makedirs(BACKUP_DIR, exist_ok=True)

async def _dump_collection_to_list(coll, projection=None, limit=None):
    cur = coll.find({}, projection or {})
    if limit: cur = cur.limit(int(limit))
    items = await cur.to_list(length=int(limit) if limit else 1000000)
    # remove _id for portability
    for it in items:
        it.pop("_id", None)
    return items

@app.post("/api/admin/backups/run")
async def backups_run(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        await require_permission(username, "backups")
        db = db_client.walletbot
        parts = body.get("collections") or ["bot_settings","users","screenshots","withdrawal_requests","transactions","audit_logs"]
        limit = body.get("limit")
        out = {"created_at": datetime.utcnow().isoformat(), "collections": {}}
        for name in parts:
            coll = getattr(db, name, None)
            if not coll:
                out["collections"][name] = {"error": "not found"}
                continue
            data = await _dump_collection_to_list(coll, projection=None, limit=limit)
            out["collections"][name] = {"count": len(data), "data": data}
        fname = f"backup_{datetime.utcnow().strftime('%Y%m%dT%H%M%S')}.json"
        path = os.path.join(BACKUP_DIR, fname)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(out, f, default=str)
        await write_audit_log("backup_run", username, {"file": fname, "parts": parts, "limit": limit})
        return {"success": True, "file": fname}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Backup run error: {e}")
        raise HTTPException(status_code=500, detail="Backup failed")

@app.get("/api/admin/backups/list")
async def backups_list(username: str = Depends(authenticate_admin)):
    try:
        await require_permission(username, "backups")
        files = []
        for fn in sorted(os.listdir(BACKUP_DIR), reverse=True):
            if fn.endswith(".json"):
                p = os.path.join(BACKUP_DIR, fn)
                files.append({"file": fn, "size": os.path.getsize(p)})
        return {"success": True, "data": files}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Backup list error: {e}")
        raise HTTPException(status_code=500, detail="List failed")

@app.get("/api/admin/backups/download/{fname}")
async def backups_download(fname: str, username: str = Depends(authenticate_admin)):
    try:
        await require_permission(username, "backups")
        safe = os.path.basename(fname)
        path = os.path.join(BACKUP_DIR, safe)
        if not os.path.exists(path):
            raise HTTPException(status_code=404, detail="Not found")
        blob = open(path, "rb")
        return StreamingResponse(blob, media_type="application/json", headers={"Content-Disposition": f"attachment; filename={safe}"})
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Backup download error: {e}")
        raise HTTPException(status_code=500, detail="Download failed")

