# ---------- 1) Alerts Webhooks (SLA breach/spikes) with toggles and rate limiting --------

# Settings structure stored in bot_settings.main_config.alerts:
# {
#   "enabled": true,
#   "url": "https://example.com/webhook",
#   "secret": "optional-shared-secret",
#   "types": { "withdrawal_sla": true, "campaign_spike": true },
#   "min_interval_sec": 300
# }
_alert_last_sent = {"withdrawal_sla": None, "campaign_spike": None}

async def _can_send_alert(kind: str, min_interval_sec: int) -> bool:
    from datetime import datetime, timedelta
    last = _alert_last_sent.get(kind)
    if not last:
        return True
    return (datetime.utcnow() - last).total_seconds() >= max(0, min_interval_sec)

async def _mark_alert_sent(kind: str):
    from datetime import datetime
    _alert_last_sent[kind] = datetime.utcnow()

async def _load_alert_config():
    db = db_client.walletbot
    cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
    return (cfg.get("alerts") or {})

async def _post_alert(url: str, payload: dict, secret: str = ""):
    import aiohttp
    try:
        timeout = aiohttp.ClientTimeout(total=6)
        headers = {"Content-Type": "application/json"}
        if secret:
            headers["X-Alert-Secret"] = secret
        async with aiohttp.ClientSession(timeout=timeout) as sess:
            async with sess.post(url, json=payload, headers=headers) as resp:
                return resp.status
    except Exception as e:
        logger.warning(f"Alert post failed: {e}")
        return None

@app.post("/api/admin/alerts/config")
async def alerts_set(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        await db.bot_settings.update_one({"type": "main_config"}, {"$set": {"alerts": body, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("alerts_config_set", username, {"keys": list((body or {}).keys())})
        return {"success": True}
    except Exception as e:
        logger.error(f"Alerts config set error: {e}")
        raise HTTPException(status_code=500, detail="Failed to save alerts config")

@app.get("/api/admin/alerts/config")
async def alerts_get(username: str = Depends(authenticate_admin)):
    try:
        conf = await _load_alert_config()
        return {"success": True, "data": conf}
    except Exception as e:
        logger.error(f"Alerts config get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load alerts config")

# Triggers (manual buttons). Real detections already exist in prior chunks; you can call these after detection.
@app.post("/api/admin/alerts/trigger/withdrawal_sla")
async def alerts_trigger_withdrawal_sla(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        conf = await _load_alert_config()
        if not conf.get("enabled") or not (conf.get("types") or {}).get("withdrawal_sla"):
            return {"success": False, "message": "disabled"}
        if not await _can_send_alert("withdrawal_sla", int(conf.get("min_interval_sec", 300))):
            return {"success": False, "message": "rate_limited"}
        payload = {"kind": "withdrawal_sla", "at": datetime.utcnow().isoformat(), "data": body or {}}
        st = await _post_alert(conf.get("url",""), payload, conf.get("secret",""))
        if st and 200 <= st < 300:
            await _mark_alert_sent("withdrawal_sla")
            await write_audit_log("alert_sent", username, {"kind":"withdrawal_sla"})
            return {"success": True}
        return {"success": False, "status": st}
    except Exception as e:
        logger.error(f"Alert trigger SLA error: {e}")
        raise HTTPException(status_code=500, detail="Trigger failed")

@app.post("/api/admin/alerts/trigger/campaign_spike")
async def alerts_trigger_campaign_spike(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        conf = await _load_alert_config()
        if not conf.get("enabled") or not (conf.get("types") or {}).get("campaign_spike"):
            return {"success": False, "message": "disabled"}
        if not await _can_send_alert("campaign_spike", int(conf.get("min_interval_sec", 300))):
            return {"success": False, "message": "rate_limited"}
        payload = {"kind": "campaign_spike", "at": datetime.utcnow().isoformat(), "data": body or {}}
        st = await _post_alert(conf.get("url",""), payload, conf.get("secret",""))
        if st and 200 <= st < 300:
            await _mark_alert_sent("campaign_spike")
            await write_audit_log("alert_sent", username, {"kind":"campaign_spike"})
            return {"success": True}
        return {"success": False, "status": st}
    except Exception as e:
        logger.error(f"Alert trigger spike error: {e}")
        raise HTTPException(status_code=500, detail="Trigger failed")

