# ---------- 2) Per-tenant Theming Overlays (base + overrides) ----------------------------

# Settings in bot_settings.main_config.theming:
# { "base": { "site_title": "...", "logo_text": "...", "accent": "#22c55e" }, "tenants": { "tenantA": { "accent": "#60a5fa" } } }

def _merge_theme(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(base or {})
    for k, v in (override or {}).items():
        out[k] = v
    return out

@app.get("/api/admin/theming")
async def theming_get(tenant: Optional[str] = None, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        th = (cfg.get("theming") or {})
        if tenant:
            merged = _merge_theme(th.get("base") or {}, (th.get("tenants") or {}).get(tenant) or {})
            return {"success": True, "data": {"effective": merged, "raw": th}}
        return {"success": True, "data": th}
    except Exception as e:
        logger.error(f"Theming get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load theming")

