@app.get("/api/admin/data-dictionary")
async def data_dictionary_api(username: str = Depends(authenticate_admin)):
    try:
        # Static+dynamic hybrid: known collections + field examples via one doc sample
        db = db_client.walletbot
        coll_names = ["users","screenshots","withdrawal_requests","transactions","audit_logs","admin_notes_pages","admin_notes_versions"]
        info = []
        for name in coll_names:
            coll = getattr(db, name, None)
            if not coll:
                continue
            sample = await coll.find({}, {"_id": 0}).limit(1).to_list(length=1)
            fields = sorted(list((sample[0].keys()) if sample else []))
            info.append({"collection": name, "fields_example": fields, "retention_hint_days": None})
        return {"success": True, "data": info}
    except Exception as e:
        logger.error(f"Data dictionary error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load dictionary")

