# ---------- 4) Error Log Viewer (levels + live tail toggle) ------------------------------

_error_log_buffer = []   # simple memory ring buffer for recent errors
_ERROR_MAX = 2000
_error_live_tail = True

def log_error_event(level: str, message: str, meta: Dict[str, Any] = None):
    try:
        entry = {"level": level.upper(), "message": message, "meta": meta or {}, "at": datetime.utcnow().isoformat()}
        _error_log_buffer.append(entry)
        if len(_error_log_buffer) > _ERROR_MAX:
            del _error_log_buffer[:len(_error_log_buffer)-_ERROR_MAX]
    except Exception:
        pass

@app.get("/api/admin/errors")
async def errors_list(level: Optional[str] = None, limit: int = 200, username: str = Depends(authenticate_admin)):
    try:
        lv = (level or "").upper()
        arr = list(reversed(_error_log_buffer[-min(_ERROR_MAX, max(1, limit)):]))
        if lv:
            arr = [x for x in arr if x.get("level") == lv]
        return {"success": True, "data": arr}
    except Exception as e:
        logger.error(f"Errors list error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load errors")

@app.post("/api/admin/errors/tail")
async def errors_tail_toggle(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        global _error_live_tail
        _error_live_tail = bool(body.get("enabled", True))
        return {"success": True, "enabled": _error_live_tail}
    except Exception as e:
        logger.error(f"Errors tail toggle error: {e}")
        raise HTTPException(status_code=500, detail="Failed to set tail")

