# ---------- 1) Alerts rate-limit counters (persisted in settings) ------------------------

# Extend alerts settings to persist counters:
# bot_settings.main_config.alerts.last_sent = { "withdrawal_sla": "2025-08-21T12:00:00Z", "campaign_spike": "..." }

async def _get_alert_last_sent() -> dict:
    db = db_client.walletbot
    cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
    return ((cfg.get("alerts") or {}).get("last_sent") or {})

async def _set_alert_last_sent(kind: str):
    db = db_client.walletbot
    key = f"alerts.last_sent.{kind}"
    await db.bot_settings.update_one({"type": "main_config"}, {"$set": {key: datetime.utcnow().isoformat()}}, upsert=True)

async def _can_send_alert_persisted(kind: str, min_interval_sec: int) -> bool:
    last_map = await _get_alert_last_sent()
    iso = last_map.get(kind)
    if not iso:
        return True
    try:
        from dateutil import parser
        last = parser.parse(iso)
    except Exception:
        return True
    return (datetime.utcnow() - last).total_seconds() >= max(0, min_interval_sec)

# Optional: two helper endpoints to view/reset counters

@app.get("/api/admin/alerts/last-sent")
async def alerts_last_sent(username: str = Depends(authenticate_admin)):
    try:
        return {"success": True, "data": await _get_alert_last_sent()}
    except Exception as e:
        logger.error(f"Alerts last-sent error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load last-sent")

@app.post("/api/admin/alerts/last-sent/reset")
async def alerts_last_sent_reset(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        kind = body.get("kind")
        if not kind:
            raise HTTPException(status_code=400, detail="kind required")
        db = db_client.walletbot
        await db.bot_settings.update_one({"type": "main_config"}, {"$unset": {f"alerts.last_sent.{kind}": ""}}, upsert=True)
        await write_audit_log("alerts_last_sent_reset", username, {"kind": kind})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Alerts last-sent reset error: {e}")
        raise HTTPException(status_code=500, detail="Failed to reset")

# Note: In your existing alert triggers, replace the in-memory rate-limit checks with:
# if not await _can_send_alert_persisted(kind, int(conf.get("min_interval_sec", 300))): ...
# and on success, call: await _set_alert_last_sent(kind)

