# ---------- 4) Structured Error Ingestion Hooks -----------------------------------------

# Public API for app code to push typed errors/warnings into central buffer
# Use from anywhere in your app: await admin_error_ingest("ERROR","payment_fail", {"ctx":"...","detail":"..."})

@app.post("/api/admin/errors/ingest")
async def admin_error_ingest(
    level: str,
    code: str,
    body: Dict[str, Any] = {},
    username: str = Depends(authenticate_admin)
):
    try:
        level_up = (level or "ERROR").upper()
        if level_up not in ("ERROR","WARN","INFO"):
            raise HTTPException(status_code=400, detail="level must be ERROR/WARN/INFO")
        meta = {"code": code, **(body or {})}
        log_error_event(level_up, f"code={code}", meta)  # pushes into in-memory buffer
        # Optional: persist last N into db for long-term
        try:
            db = db_client.walletbot
            await db.error_events.insert_one({"level": level_up, "meta": meta, "at": datetime.utcnow()})
        except Exception:
            pass
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error ingest error: {e}")
        raise HTTPException(status_code=500, detail="Ingest failed")

