# ---------- 1) Theme Bundles Import/Export (multi-tenant overlays) ----------------------

@app.get("/api/admin/theming/export.json")
async def theming_export(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        theming = cfg.get("theming") or {"base": {}, "tenants": {}}
        blob = json.dumps({"theming": theming, "exported_at": datetime.utcnow().isoformat()}, default=str).encode("utf-8")
        headers = {"Content-Disposition": "attachment; filename=theming_bundle.json"}
        return StreamingResponse(io.BytesIO(blob), media_type="application/json", headers=headers)
    except Exception as e:
        logger.error(f"Theming export error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

@app.post("/api/admin/theming/import")
async def theming_import(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        data = body.get("theming") or {}
        if not isinstance(data, dict) or "base" not in data:
            raise HTTPException(status_code=400, detail="Invalid bundle")
        db = db_client.walletbot
        await db.bot_settings.update_one({"type":"main_config"}, {"$set": {"theming": data, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("theming_import", username, {"tenants": list((data.get("tenants") or {}).keys())})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Theming import error: {e}")
        raise HTTPException(status_code=500, detail="Import failed")

