# ---------- 2) Schema Validators (simple field rules + validate API) ---------------------

# Store validators in bot_settings.main_config.validators:
# {
#   "users": { "required": ["user_id","username"], "types": { "user_id":"int", "wallet_balance":"float" } },
#   "withdrawal_requests": { "required": ["request_id","user_id","amount","status"], "types": { "amount":"float" } }
# }

def _type_ok(val, typ):
    if typ == "int":
        try: int(val); return True
        except: return False
    if typ == "float":
        try: float(val); return True
        except: return False
    if typ == "str":
        return isinstance(val, str)
    if typ == "bool":
        return isinstance(val, bool)
    return True

@app.get("/api/admin/validators")
async def validators_get(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        return {"success": True, "data": (cfg.get("validators") or {})}
    except Exception as e:
        logger.error(f"Validators get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load validators")

@app.post("/api/admin/validators")
async def validators_set(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        await db.bot_settings.update_one({"type":"main_config"}, {"$set": {"validators": body, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("validators_set", username, {"keys": list((body or {}).keys())})
        return {"success": True}
    except Exception as e:
        logger.error(f"Validators set error: {e}")
        raise HTTPException(status_code=500, detail="Failed to save validators")

@app.post("/api/admin/validators/validate")
async def validators_validate(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        coll = (body.get("collection") or "").strip()
        doc = body.get("doc") or {}
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        rules = (cfg.get("validators") or {}).get(coll) or {}
        errs = []
        for req in (rules.get("required") or []):
            if req not in doc:
                errs.append(f"Missing required: {req}")
        for k, typ in (rules.get("types") or {}).items():
            if k in doc and not _type_ok(doc[k], typ):
                errs.append(f"Type mismatch for {k}: expected {typ}")
        return {"success": len(errs)==0, "errors": errs}
    except Exception as e:
        logger.error(f"Validators validate error: {e}")
        raise HTTPException(status_code=500, detail="Validation failed")

