# ---------- 3) Alerts Batching/Aggregation (queue + manual flush) -----------------------

_alert_queue = []  # in-memory queue of events to batch-send

@app.post("/api/admin/alerts/queue")
async def alerts_queue(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        kind = (body.get("kind") or "").strip()
        data = body.get("data") or {}
        if not kind:
            raise HTTPException(status_code=400, detail="kind required")
        _alert_queue.append({"kind": kind, "data": data, "at": datetime.utcnow().isoformat()})
        return {"success": True, "queued": len(_alert_queue)}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Alerts queue error: {e}")
        raise HTTPException(status_code=500, detail="Queue failed")

@app.post("/api/admin/alerts/flush")
async def alerts_flush(username: str = Depends(authenticate_admin)):
    try:
        conf = await _load_alert_config()
        if not conf.get("enabled"):
            return {"success": False, "message": "alerts disabled"}
        url = conf.get("url","")
        secret = conf.get("secret","")
        # aggregate by kind
        by = {}
        for ev in list(_alert_queue):
            by.setdefault(ev["kind"], []).append(ev)
        sent = {}
        for k, arr in by.items():
            payload = {"kind": k, "batch": arr, "at": datetime.utcnow().isoformat()}
            st = await _post_alert(url, payload, secret)
            sent[k] = st
        _alert_queue.clear()
        await write_audit_log("alerts_flush", username, {"kinds": list(by.keys())})
        return {"success": True, "sent": sent}
    except Exception as e:
        logger.error(f"Alerts flush error: {e}")
        raise HTTPException(status_code=500, detail="Flush failed")

