@app.get("/api/admin/audits/filter")
async def audits_filter_api(
    actor: Optional[str] = None,
    action: Optional[str] = None,
    start: Optional[str] = None,
    end: Optional[str] = None,
    page: int = 1,
    page_size: int = 100,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        q = {}
        if actor: q["actor"] = actor
        if action: q["action"] = action
        if start or end:
            rng = {}
            if start: rng["$gte"] = datetime.fromisoformat(start)
            if end: rng["$lte"] = datetime.fromisoformat(end)
            q["created_at"] = rng
        page = max(1, int(page)); page_size = max(10, min(200, int(page_size)))
        cur = db.audit_logs.find(q, {"_id": 0}).sort("created_at", -1).skip((page-1)*page_size).limit(page_size)
        items = await cur.to_list(length=page_size)
        total = await db.audit_logs.count_documents(q)
        return {"success": True, "data": {"items": items, "page": page, "page_size": page_size, "total": total}}
    except Exception as e:
        logger.error(f"Audits filter error: {e}")
        raise HTTPException(status_code=500, detail="Filter failed")

