async def _ip_allowed(ip: str) -> bool:
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
        ipa = (cfg.get("ip_access") or {})
        allow = set(ipa.get("allow") or [])
        deny = set(ipa.get("deny") or [])
        if ip in deny:
            return False
        if allow:
            return ip in allow
        return True
    except Exception:
        return True

