# ---------- 2) Weekly Reviewer Heatmap (day-of-week × hour) -----------------------------

@app.get("/api/admin/reviewer/heatmap-weekly")
async def reviewer_heatmap_weekly(
    days: int = 28,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(7, min(90, int(days))))
        cur = db.screenshots.find(
            {"reviewed_at": {"$gte": since}, "status": {"$in": ["approved","rejected"]}},
            {"_id":0,"assigned_to":1,"admin_notes":1,"reviewed_at":1}
        )
        from collections import defaultdict
        grid = defaultdict(lambda: [[0]*24 for _ in range(7)])  # reviewer -> 
        async for s in cur:
            who = s.get("assigned_to")
            if not who:
                notes = s.get("admin_notes") or ""
                ix = notes.find("by:")
                if ix >= 0:
                    who = (notes[ix+3:].strip().split() or "")[:32]
            if not who:
                who = "unknown"
            t = s.get("reviewed_at") or datetime.utcnow()
            dow = getattr(t, "weekday", lambda: 0)()
            hr = getattr(t, "hour", 0)
            grid[who][dow][hr] += 1
        rows = [{"reviewer": r, "grid": g} for r,g in grid.items()]
        rows.sort(key=lambda x: -sum(sum(row) for row in x["grid"]))
        return {"success": True, "data": {"rows": rows, "window_days": days}}
    except Exception as e:
        logger.error(f"Weekly heatmap error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build heatmap")

