# ---------- 3) Transactions Anomalies (velocity + large-amount) -------------------------

@app.get("/api/admin/tx/anomalies")
async def tx_anomalies(
    days: int = 14,
    velocity_threshold: int = 50,
    amount_threshold: float = 1000.0,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(60, int(days))))
        cur = db.transactions.find({"created_at": {"$gte": since}}, {"_id":0,"tx_id":1,"user_id":1,"amount":1,"type":1,"created_at":1})
        from collections import defaultdict
        by_user = defaultdict(lambda: {"count":0, "large":0, "tx": []})
        async for t in cur:
            uid = t.get("user_id")
            amt = float(t.get("amount",0) or 0)
            by_user[uid]["count"] += 1
            if abs(amt) >= float(amount_threshold):
                by_user[uid]["large"] += 1
            if len(by_user[uid]["tx"]) < 10:
                by_user[uid]["tx"].append({"tx_id": t.get("tx_id"), "amount": amt, "type": t.get("type"), "at": t.get("created_at")})
        flags = []
        for uid, d in by_user.items():
            reasons = []
            if d["count"] >= int(velocity_threshold):
                reasons.append("high_velocity")
            if d["large"] >= 1:
                reasons.append("large_amount")
            if reasons:
                flags.append({"user_id": uid, "count": d["count"], "large_count": d["large"], "reasons": reasons, "sample": d["tx"]})
        flags.sort(key=lambda x: (-("large_amount" in x["reasons"]), -x["count"]))
        return {"success": True, "data": {"flags": flags, "window_days": days}}
    except Exception as e:
        logger.error(f"Tx anomalies error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute anomalies")

