# ---------- 1) Admin Session IP Binding --------------------------------------------------
# Store per-admin binding preference and bind IPs on session create, then verify on use.
# Settings (bot_settings.main_config.session_ip): { "enforce": true, "admins": { "alice": ["1.2.3.4"] } }

@app.get("/api/admin/session-ip")
async def session_ip_get(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        sess_ip = (cfg.get("session_ip") or {"enforce": False, "admins": {}})
        return {"success": True, "data": sess_ip}
    except Exception as e:
        logger.error(f"Session IP get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load")

@app.post("/api/admin/session-ip")
async def session_ip_set(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        await db.bot_settings.update_one(
            {"type":"main_config"},
            {"$set": {"session_ip": body, "updated_at": datetime.utcnow()}},
            upsert=True
        )
        await write_audit_log("session_ip_set", username, {"keys": list((body or {}).keys())})
        return {"success": True}
    except Exception as e:
        logger.error(f"Session IP set error: {e}")
        raise HTTPException(status_code=500, detail="Failed to save")

async def _session_ip_allowed(username: str, client_ip: str) -> bool:
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        sess_ip = (cfg.get("session_ip") or {})
        if not sess_ip.get("enforce"):
            return True
        admins = sess_ip.get("admins") or {}
        allowed = set(admins.get(username) or [])
        if not allowed:
            return True  # no explicit binding set for this admin
        return client_ip in allowed
    except Exception:
        return True

