# ---------- 2) Queue Depth Monitors -----------------------------------------------------
# Screenshots moderation queue depth, withdrawals pending queue depth, and optional per-campaign counts.

@app.get("/api/admin/queues/depth")
async def queues_depth(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        pending_mod = await db.screenshots.count_documents({"status": "pending"})
        pending_wd = await db.withdrawal_requests.count_documents({"status": "pending"})
        # per-campaign pending (top 20)
        pipe = [
            {"$match": {"status": "pending"}},
            {"$group": {"_id": "$campaign_id", "count": {"$sum": 1}}},
            {"$sort": {"count": -1}},
            {"$limit": 20}
        ]
        per_camp = await db.screenshots.aggregate(pipe).to_list(length=20)
        return {"success": True, "data": {"moderation_pending": pending_mod, "withdrawals_pending": pending_wd, "per_campaign": per_camp}}
    except Exception as e:
        logger.error(f"Queues depth error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load queue depth")

