@app.get("/api/admin/campaigns/sla/breaches")
async def campaign_sla_breaches(
    days: int = 7,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(1, min(60, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        sla = (cfg.get("campaign_sla") or {})
        # consider screenshots moderation SLA
        cur = db.screenshots.find({"created_at": {"$gte": since}}, {"_id":0, "submission_id":1, "campaign_id":1, "created_at":1, "reviewed_at":1, "status":1})
        breaches = []
        async for s in cur:
            cid = s.get("campaign_id")
            target_h = float((sla.get(cid) or {}).get("review_hours", 0) or 0)
            if target_h <= 0:
                continue
            start = s.get("created_at")
            end = s.get("reviewed_at")
            now = datetime.utcnow()
            elapsed_h = ((end or now) - start).total_seconds()/3600.0 if start else 0.0
            if (end is None and elapsed_h >= target_h) or (end is not None and elapsed_h > target_h):
                breaches.append({
                    "submission_id": s.get("submission_id"),
                    "campaign_id": cid,
                    "status": s.get("status"),
                    "elapsed_hours": round(elapsed_h,1),
                    "target_hours": target_h,
                    "closed": bool(end)
                })
        breaches.sort(key=lambda x: -x["elapsed_hours"])
        return {"success": True, "data": {"breaches": breaches, "window_days": days}}
    except Exception as e:
        logger.error(f"Campaign SLA breach error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute breaches")

