# ---------- 1) Error Logs: level filter + search + pagination ---------------------------

@app.get("/api/admin/errors/search")
async def errors_search_api(
    level: Optional[str] = None,       # ERROR|WARN|INFO
    q: Optional[str] = None,           # substring on message/meta.code
    start: Optional[str] = None,       # ISO
    end: Optional[str] = None,         # ISO
    page: int = 1,
    page_size: int = 100,
    username: str = Depends(authenticate_admin),
):
    """
    Search error_events (persisted in prior chunks) by level, substring, and date range.
    Falls back to in-memory buffer when DB empty.
    """
    try:
        db = db_client.walletbot
        page = max(1, int(page))
        page_size = max(10, min(200, int(page_size)))
        qf: Dict[str, Any] = {}
        if level:
            qf["level"] = level.upper()
        if start or end:
            rng = {}
            if start:
                try:
                    rng["$gte"] = datetime.fromisoformat(start)
                except Exception:
                    pass
            if end:
                try:
                    rng["$lte"] = datetime.fromisoformat(end)
                except Exception:
                    pass
            if rng:
                qf["at"] = rng
        # substring search on message/meta.code (basic)
        # project meta.code and do regex OR contains
        pipe = [
            {"$addFields": {"meta_code": {"$ifNull": ["$meta.code", ""]}}},
        ]
        if q:
            pipe += [
                {"$match": {"$or": [{"meta_code": {"$regex": q, "$options": "i"}},
                                    {"message": {"$regex": q, "$options": "i"}}]}},
            ]
        if qf:
            pipe = [{"$match": qf}] + pipe
        pipe += [
            {"$sort": {"at": -1}},
            {"$skip": (page-1)*page_size},
            {"$limit": page_size},
            {"$project": {"_id": 0, "level": 1, "message": 1, "meta": 1, "at": 1}}
        ]
        items = await db.error_events.aggregate(pipe).to_list(length=page_size)
        # total estimate (approximate without string pipeline match for performance)
        base_count = await db.error_events.count_documents({k:v for k,v in qf.items() if k!="meta_code"})
        return {"success": True, "data": {"items": items, "page": page, "page_size": page_size, "total_estimate": base_count}}
    except Exception as e:
        logger.error(f"Errors search API error: {e}")
        raise HTTPException(status_code=500, detail="Failed to search errors")

