# ---------- 3) Reviewer Workload Heatbands (load indicator) -----------------------------
# Shows per-reviewer pending assignments and last 24h reviewed volume. Useful for balancing.

@app.get("/api/admin/reviewer/workload")
async def reviewer_workload(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        # pending assigned per reviewer
        pipe_assigned = [
            {"$match": {"status": "pending", "assigned_to": {"$exists": True, "$ne": ""}}},
            {"$group": {"_id": "$assigned_to", "pending": {"$sum": 1}}}
        ]
        assigned = await db.screenshots.aggregate(pipe_assigned).to_list(length=1000)
        pend = {x["_id"]: x["pending"] for x in assigned}
        # last 24h reviewed per reviewer
        since = datetime.utcnow() - timedelta(hours=24)
        cur = db.screenshots.find({"reviewed_at": {"$gte": since}, "status": {"$in": ["approved","rejected"]}}, {"_id":0,"assigned_to":1,"admin_notes":1})
        from collections import Counter
        done = Counter()
        async for s in cur:
            who = s.get("assigned_to")
            if not who:
                notes = s.get("admin_notes") or ""
                ix = notes.find("by:")
                if ix >= 0:
                    who = (notes[ix+3:].strip().split()[0] or "")[:32]
            if who:
                done[who] += 1
        # merge sets
        names = set(list(pend.keys()) + list(done.keys()))
        out = []
        for n in names:
            p = int(pend.get(n, 0))
            d = int(done.get(n, 0))
            # workload band heuristic: green if p<=5, yellow if <=15, red otherwise
            band = "green" if p<=5 else ("yellow" if p<=15 else "red")
            out.append({"reviewer": n, "pending": p, "done_24h": d, "band": band})
        out.sort(key=lambda x: (-x["pending"], x["reviewer"]))
        return {"success": True, "data": out}
    except Exception as e:
        logger.error(f"Reviewer workload error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute workload")

