# ---------- 1) Reviewer Auto-Assign Guard (holiday/IP/workload aware) -------------------
# Uses existing reviewer_holidays, session_ip enforcement (optional), and workload snapshot
# to choose a safe reviewer or block auto-assign.

async def _load_reviewer_holidays() -> Dict[str, Any]:
    db = db_client.walletbot
    cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
    return (cfg.get("reviewer_holidays") or {})

async def _is_holiday_for(name: str) -> bool:
    try:
        hol = await _load_reviewer_holidays()
        today = datetime.utcnow().date().isoformat()
        return today in (hol.get(name) or [])
    except Exception:
        return False

async def _reviewer_workload_snapshot(hours: int = 24) -> Dict[str, Dict[str, int]]:
    from collections import Counter
    db = db_client.walletbot
    # pending assigned
    pipe_assigned = [
        {"$match": {"status": "pending", "assigned_to": {"$exists": True, "$ne": ""}}},
        {"$group": {"_id": "$assigned_to", "pending": {"$sum": 1}}}
    ]
    assigned = await db.screenshots.aggregate(pipe_assigned).to_list(length=2000)
    pend = {x["_id"]: int(x["pending"]) for x in assigned}
    # last N hours reviewed
    since = datetime.utcnow() - timedelta(hours=max(1, min(72, int(hours))))
    cur = db.screenshots.find({"reviewed_at": {"$gte": since}, "status": {"$in": ["approved","rejected"]}}, {"_id":0,"assigned_to":1,"admin_notes":1})
    done = Counter()
    async for s in cur:
        who = s.get("assigned_to")
        if not who:
            notes = s.get("admin_notes") or ""
            ix = notes.find("by:")
            if ix >= 0:
                who = (notes[ix+3:].strip().split()[0] or "")[:32]
        if who:
            done[who] += 1
    out = {}
    names = set(list(pend.keys()) + list(done.keys()))
    for n in names:
        out[n] = {"pending": int(pend.get(n, 0)), "done_hours": int(done.get(n, 0))}
    return out

@app.get("/api/admin/reviewer/auto-assign/guard")
async def reviewer_auto_assign_guard(
    candidate: Optional[str] = None,
    client_ip: Optional[str] = None,
    username: str = Depends(authenticate_admin)
):
    """
    Returns guard decision: ok/block, and suggests alternative reviewers sorted by light workload.
    - Blocks if candidate is on holiday, or (if session_ip enforcement active) candidate not allowed for given IP.
    - Provides workload snapshot to help choose reviewer.
    """
    try:
        # holiday check
        if candidate and await _is_holiday_for(candidate):
            reason = "holiday"
            wl = await _reviewer_workload_snapshot()
            suggestions = sorted(
                [{"reviewer": k, **v} for k, v in wl.items() if k != candidate],
                key=lambda x: (x["pending"], -x["done_hours"])
            )[:10]
            return {"success": True, "data": {"ok": False, "reason": reason, "suggestions": suggestions}}

        # IP enforcement check (if configured)
        if candidate and client_ip:
            # reuse existing session IP settings
            allowed = await _session_ip_allowed(candidate, client_ip)
            if not allowed:
                wl = await _reviewer_workload_snapshot()
                suggestions = sorted(
                    [{"reviewer": k, **v} for k, v in wl.items() if k != candidate],
                    key=lambda x: (x["pending"], -x["done_hours"])
                )[:10]
                return {"success": True, "data": {"ok": False, "reason": "ip_not_allowed", "suggestions": suggestions}}

        # workload context always included
        wl = await _reviewer_workload_snapshot()
        data = {"ok": True, "reason": None, "workload": wl}
        # suggest lightest 10
        data["suggestions"] = sorted(
            [{"reviewer": k, **v} for k, v in wl.items()],
            key=lambda x: (x["pending"], -x["done_hours"])
        )[:10]
        return {"success": True, "data": data}
    except Exception as e:
        logger.error(f"Auto-assign guard error: {e}")
        raise HTTPException(status_code=500, detail="Guard failed")

