# ---------- 2) Campaign Ops Dashboard (rollup KPIs) ------------------------------------
# KPIs: pending per campaign, last 24h completed, average review time (last 7d), SLA breach count (uses campaign_sla if present)

@app.get("/api/admin/campaigns/ops")
async def campaigns_ops(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        since_24h = now - timedelta(hours=24)
        since_7d = now - timedelta(days=7)

        # pending per campaign
        pipe_pending = [
            {"$match": {"status": "pending"}},
            {"$group": {"_id": "$campaign_id", "pending": {"$sum": 1}}}
        ]
        pending = await db.screenshots.aggregate(pipe_pending).to_list(length=5000)
        pend_map = {x["_id"]: int(x["pending"]) for x in pending}

        # completed last 24h per campaign
        pipe_24h = [
            {"$match": {"reviewed_at": {"$gte": since_24h}, "status": {"$in": ["approved","rejected"]}}},
            {"$group": {"_id": "$campaign_id", "done_24h": {"$sum": 1}}}
        ]
        done = await db.screenshots.aggregate(pipe_24h).to_list(length=5000)
        done_map = {x["_id"]: int(x["done_24h"]) for x in done}

        # avg review time last 7d
        cur = db.screenshots.find(
            {"created_at": {"$gte": since_7d}, "status": {"$in": ["approved","rejected"]}},
            {"_id":0, "campaign_id":1, "created_at":1, "reviewed_at":1}
        )
        from collections import defaultdict
        sums = defaultdict(float); cnts = defaultdict(int)
        async for s in cur:
            cid = s.get("campaign_id")
            ca = s.get("created_at"); ra = s.get("reviewed_at")
            if cid and ca and ra:
                mins = max(0.0, (ra - ca).total_seconds()/60.0)
                sums[cid] += mins; cnts[cid] += 1
        avg_map = {cid: round(sums[cid]/cnts[cid], 1) for cid in sums}

        # SLA breaches last 7d (if config present)
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        sla = (cfg.get("campaign_sla") or {})
        cur2 = db.screenshots.find({"created_at": {"$gte": since_7d}}, {"_id":0, "campaign_id":1, "created_at":1, "reviewed_at":1})
        breaches = defaultdict(int)
        async for s in cur2:
            cid = s.get("campaign_id")
            if not cid: 
                continue
            target_h = float((sla.get(cid) or {}).get("review_hours", 0) or 0)
            if target_h <= 0:
                continue
            ca = s.get("created_at"); ra = s.get("reviewed_at"); end = ra or now
            elapsed_h = (end - ca).total_seconds()/3600.0 if ca else 0.0
            if (ra is None and elapsed_h >= target_h) or (ra is not None and elapsed_h > target_h):
                breaches[cid] += 1

        # combine keys
        cids = set(list(pend_map.keys()) + list(done_map.keys()) + list(avg_map.keys()) + list(breaches.keys()))
        rows = []
        for cid in cids:
            rows.append({
                "campaign_id": cid,
                "pending": int(pend_map.get(cid, 0)),
                "done_24h": int(done_map.get(cid, 0)),
                "avg_review_min_7d": float(avg_map.get(cid, 0.0)),
                "sla_breaches_7d": int(breaches.get(cid, 0))
            })
        rows.sort(key=lambda x: (-x["pending"], -x["done_24h"]))
        return {"success": True, "data": rows, "generated_at": now.isoformat()}
    except Exception as e:
        logger.error(f"Campaigns ops error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute KPIs")

