# ---------- 3) Withdrawal SLA Root-Cause Tags -------------------------------------------
# Categorize SLA breaches into root causes via simple heuristics and allow overrides/tags.

def _classify_withdrawal_breach(w: Dict[str, Any], now: datetime, target_h: float) -> str:
    # Simple rules: very old -> backlog, large amount -> manual_review, method 'bank' -> banking_delay, else queue_delay
    try:
        created = w.get("created_at") or now
        age = (now - created).total_seconds()/3600.0
        amt = float(w.get("amount", 0.0) or 0.0)
        method = (w.get("method") or "").lower()
        if age >= target_h*2:
            return "backlog"
        if amt >= 1000:
            return "manual_review"
        if "bank" in method:
            return "banking_delay"
        return "queue_delay"
    except Exception:
        return "queue_delay"

@app.get("/api/admin/withdrawals/sla/rootcauses")
async def withdrawals_sla_rootcauses(
    hours: int = 48,
    username: str = Depends(authenticate_admin)
):
    """
    Lists pending withdrawals that breached SLA threshold and assigns a root-cause tag.
    Allows manual override via separate tagging endpoint.
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        thr = max(1, min(240, int(hours)))
        # optional overrides collection: withdrawal_sla_tags { request_id, tag, updated_at, updated_by }
        tags_cur = db.withdrawal_sla_tags.find({}, {"_id":0})
        override = {}
        async for t in tags_cur:
            override[str(t.get("request_id"))] = t.get("tag")

        cur = db.withdrawal_requests.find({"status": "pending"}, {"_id":0,"request_id":1,"user_id":1,"amount":1,"method":1,"created_at":1})
        out = []
        async for w in cur:
            created = w.get("created_at") or now
            age_h = (now - created).total_seconds()/3600.0
            if age_h < thr:
                continue
            rid = str(w.get("request_id"))
            tag = override.get(rid) or _classify_withdrawal_breach(w, now, thr)
            out.append({
                "request_id": rid,
                "user_id": w.get("user_id"),
                "amount": round(float(w.get("amount",0.0) or 0.0), 2),
                "method": w.get("method"),
                "age_hours": round(age_h,1),
                "tag": tag
            })
        out.sort(key=lambda x: (-x["age_hours"], x["tag"]))
        return {"success": True, "data": {"breaches": out, "threshold_hours": thr}}
    except Exception as e:
        logger.error(f"Withdrawals SLA rootcauses error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute root causes")

@app.post("/api/admin/withdrawals/sla/tag")
async def withdrawals_sla_tag(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Manually set/override a root-cause tag.
    Body: { request_id: "rid", tag: "queue_delay|manual_review|banking_delay|backlog|other" }
    """
    try:
        rid = (body.get("request_id") or "").strip()
        tag = (body.get("tag") or "").strip()
        if not rid or not tag:
            raise HTTPException(status_code=400, detail="request_id and tag required")
        db = db_client.walletbot
        await db.withdrawal_sla_tags.update_one(
            {"request_id": rid},
            {"$set": {"request_id": rid, "tag": tag, "updated_at": datetime.utcnow(), "updated_by": username}},
            upsert=True
        )
        await write_audit_log("withdrawals_sla_tag", username, {"request_id": rid, "tag": tag})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Withdrawals SLA tag error: {e}")
        raise HTTPException(status_code=500, detail="Failed to set tag")

