# ---------- 1) Reviewer Assignment Fairness (bias check + round-robin hints) ------------

@app.get("/api/admin/reviewer/fairness")
async def reviewer_fairness(
    days: int = 14,
    username: str = Depends(authenticate_admin)
):
    """
    Analyzes assignment distribution across reviewers:
    - Pulls assigned_to for pending and for approved/rejected in the last N days.
    - Computes share vs. equal-share baseline and highlights over/under assignment.
    """
    try:
        db = db_client.walletbot
        days = max(7, min(90, int(days)))
        since = datetime.utcnow() - timedelta(days=days)

        # Current pending per reviewer
        pipe_pend = [
            {"$match": {"status": "pending", "assigned_to": {"$exists": True, "$ne": ""}}},
            {"$group": {"_id": "$assigned_to", "pending": {"$sum": 1}}}
        ]
        pend = await db.screenshots.aggregate(pipe_pend).to_list(length=2000)
        pending_map = {x["_id"]: int(x["pending"]) for x in pend}

        # Completed in window per reviewer
        cur = db.screenshots.find(
            {"reviewed_at": {"$gte": since}, "status": {"$in": ["approved","rejected"]}},
            {"_id":0, "assigned_to":1, "admin_notes":1}
        )
        from collections import Counter
        done = Counter()
        async for s in cur:
            who = s.get("assigned_to")
            if not who:
                notes = s.get("admin_notes") or ""
                ix = notes.find("by:")
                if ix >= 0:
                    who = (notes[ix+3:].strip().split()[0] or "")[:32]
            if who:
                done[who] += 1

        reviewers = sorted(set(list(pending_map.keys()) + list(done.keys())))
        if not reviewers:
            return {"success": True, "data": {"rows": [], "window_days": days}}

        total_done = sum(done.values()) or 1
        equal_share = total_done / len(reviewers)
        rows = []
        for r in reviewers:
            d = int(done.get(r, 0))
            p = int(pending_map.get(r, 0))
            deviation = round(((d - equal_share) / equal_share)*100, 1) if equal_share > 0 else 0.0
            rows.append({"reviewer": r, "done_window": d, "pending": p, "deviation_pct": deviation})
        # Rank by deviation (over-assigned positive -> top)
        rows.sort(key=lambda x: -x["deviation_pct"])

        # Simple round-robin hint list: reviewers sorted by fewest pending then fewest done
        rr = sorted(
            [{"reviewer": r, "pending": int(pending_map.get(r, 0)), "done_window": int(done.get(r, 0))} for r in reviewers],
            key=lambda x: (x["pending"], x["done_window"])
        )

        return {"success": True, "data": {"rows": rows, "round_robin": rr, "window_days": days}}
    except Exception as e:
        logger.error(f"Reviewer fairness error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute fairness")

