# ---------- 2) Campaign Capacity Planner (targets vs throughput => reviewer count) ------

@app.get("/api/admin/campaigns/capacity")
async def campaigns_capacity(
    days: int = 14,
    reviewers_daily_capacity: int = 120,  # average items a reviewer can process per day
    username: str = Depends(authenticate_admin)
):
    """
    Suggests reviewers per campaign:
    - Reads pacing targets (per_campaign) if configured; else uses recent daily average demand.
    - Divides target by reviewers_daily_capacity to estimate required headcount.
    """
    try:
        db = db_client.walletbot
        days = max(7, min(60, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cfg = await db.bot_settings.find_one({"type": "main_config"}) or {}
        pacing = (cfg.get("pacing") or {}).get("per_campaign", {}) or {}

        # Recent daily demand per campaign
        pipe = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {"_id": {"day": {"$dateToString": {"format":"%Y-%m-%d", "date":"$created_at"}}, "campaign_id": "$campaign_id"}, "cnt": {"$sum": 1}}},
            {"$group": {"_id": "$_id.campaign_id", "avg_per_day": {"$avg": "$cnt"}}}
        ]
        agg = await db.screenshots.aggregate(pipe).to_list(length=5000)
        demand_map = {x["_id"]: float(x.get("avg_per_day", 0.0) or 0.0) for x in agg}

        # Build rows
        cids = sorted(set(list(demand_map.keys()) + list(pacing.keys())))
        rows = []
        cap = max(10, min(500, int(reviewers_daily_capacity)))
        for cid in cids:
            target = float(pacing.get(cid, 0) or 0.0) or float(demand_map.get(cid, 0.0))
            needed = int(max(1, round(target / cap))) if target > 0 else 0
            rows.append({"campaign_id": cid, "daily_target": round(target,1), "reviewer_capacity": cap, "suggested_reviewers": needed})
        rows.sort(key=lambda x: -x["daily_target"])
        return {"success": True, "data": rows, "window_days": days}
    except Exception as e:
        logger.error(f"Campaign capacity error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute capacity")

