# ---------- 3) Withdrawals Age Buckets (backlog visualization) --------------------------

@app.get("/api/admin/withdrawals/age-buckets")
async def withdrawals_age_buckets(
    buckets: str = "0-2,2-6,6-12,12-24,24-48,48-9999",  # hours ranges
    username: str = Depends(authenticate_admin)
):
    """
    Groups pending withdrawals into age buckets (hours).
    Query param 'buckets' is CSV of ranges a-b (inclusive lower, exclusive upper except last).
    """
    try:
        db = db_client.walletbot
        now = datetime.utcnow()
        # parse buckets
        parsed = []
        for part in (buckets or "").split(","):
            part = part.strip()
            if not part or "-" not in part: 
                continue
            a, b = part.split("-", 1)
            try:
                lo = float(a); hi = float(b)
                parsed.append((lo, hi))
            except Exception:
                continue
        if not parsed:
            parsed = [(0,2),(2,6),(6,12),(12,24),(24,48),(48,9999)]

        cur = db.withdrawal_requests.find({"status": "pending"}, {"_id":0, "request_id":1, "created_at":1, "amount":1, "method":1, "user_id":1})
        buckets_out = [{"range": f"{int(lo)}-{int(hi)}h", "count": 0, "total_amount": 0.0, "sample": []} for (lo,hi) in parsed]
        async for w in cur:
            created = w.get("created_at") or now
            age_h = (now - created).total_seconds()/3600.0
            for i, (lo,hi) in enumerate(parsed):
                within = (age_h >= lo) and (age_h < hi or (hi >= 9999 and age_h >= lo))
                if within:
                    buckets_out[i]["count"] += 1
                    buckets_out[i]["total_amount"] += float(w.get("amount", 0.0) or 0.0)
                    if len(buckets_out[i]["sample"]) < 5:
                        buckets_out[i]["sample"].append({"request_id": w.get("request_id"), "age_h": round(age_h,1), "amt": float(w.get("amount",0.0) or 0.0)})
                    break
        for b in buckets_out:
            b["total_amount"] = round(b["total_amount"], 2)
        return {"success": True, "data": {"buckets": buckets_out}}
    except Exception as e:
        logger.error(f"Withdrawals age buckets error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute buckets")

