# ---------- 1) Reviewer QoS Sampler (random spot-check queue) ---------------------------
# Pulls a random sample of recently approved items per reviewer for spot-checking.

import random

@app.get("/api/admin/reviewer/qos-sample")
async def reviewer_qos_sample(
    days: int = 7,
    per_reviewer: int = 5,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(1, min(60, int(days)))
        per_reviewer = max(1, min(50, int(per_reviewer)))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.screenshots.find(
            {"reviewed_at": {"$gte": since}, "status": "approved"},
            {"_id": 0, "submission_id": 1, "assigned_to": 1, "admin_notes": 1, "reviewed_at": 1, "user_id": 1, "campaign_id": 1}
        )
        by_reviewer = {}
        async for s in cur:
            who = s.get("assigned_to")
            if not who:
                notes = s.get("admin_notes") or ""
                ix = notes.find("by:")
                if ix >= 0:
                    who = (notes[ix+3:].strip().split()[0] or "")[:32]
            if not who:
                who = "unknown"
            by_reviewer.setdefault(who, []).append(s)
        sample = []
        for r, arr in by_reviewer.items():
            if not arr:
                continue
            k = min(per_reviewer, len(arr))
            sample.extend(random.sample(arr, k))
        # Shuffle overall for variety
        random.shuffle(sample)
        return {"success": True, "data": {"window_days": days, "items": sample}}
    except Exception as e:
        logger.error(f"QoS sample error: {e}")
        raise HTTPException(status_code=500, detail="Failed to sample")

