# ---------- 2) Campaign Notes (threaded, with mentions) ---------------------------------
# Collection: campaign_notes { campaign_id, notes: [{ id, parent_id, text, by, at, mentions: [users...] }], updated_at }

from uuid import uuid4

@app.get("/api/admin/campaigns/notes/{campaign_id}")
async def campaign_notes_get(campaign_id: str, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        doc = await db.campaign_notes.find_one({"campaign_id": campaign_id}, {"_id": 0})
        if not doc:
            doc = {"campaign_id": campaign_id, "notes": []}
        return {"success": True, "data": doc}
    except Exception as e:
        logger.error(f"Campaign notes get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load notes")

@app.post("/api/admin/campaigns/notes/{campaign_id}")
async def campaign_notes_post(
    campaign_id: str,
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        text = (body.get("text") or "").strip()
        if not text:
            raise HTTPException(status_code=400, detail="text required")
        parent_id = (body.get("parent_id") or "").strip() or None
        mentions = body.get("mentions") or []
        note = {
            "id": str(uuid4()),
            "parent_id": parent_id,
            "text": text,
            "by": username,
            "at": datetime.utcnow(),
            "mentions": [str(m) for m in mentions if m]
        }
        await db.campaign_notes.update_one(
            {"campaign_id": campaign_id},
            {"$push": {"notes": note}, "$set": {"updated_at": datetime.utcnow()}},
            upsert=True
        )
        await write_audit_log("campaign_note_add", username, {"campaign_id": campaign_id, "parent_id": parent_id})
        return {"success": True, "note": note}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Campaign notes post error: {e}")
        raise HTTPException(status_code=500, detail="Failed to add note")

@app.get("/admin/campaigns/notes/{campaign_id}")
async def campaign_notes_page(campaign_id: str):
    html = f"""
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8"><title>Campaign Notes – {campaign_id}</title>
  <link href="https://unpkg.com/tailwindcss@^2/dist/tailwind.min.css" rel="stylesheet">
  <style>
    body {{background:#0f172a;color:#e2e8f0}}
    .card{{background:#111827;border:1px solid rgba(148,163,184,.12)}}
    .mono{{font-family:ui-monospace,Menlo,Consolas,monospace}}
    .bubble{{border-left:2px solid #374151;padding-left:8px;margin-left:6px}}
  </style>
</head>
<body class="p-6">
  <div class="max-w-3xl mx-auto">
    <div class="flex items-center justify-between mb-3">
      <h1 class="text-2xl font-bold">Campaign Notes</h1>
      <a class="text-blue-400 underline" href="/admin/index-psi-prime">Back</a>
    </div>
    <div class="card rounded p-4 mb-3">
      <textarea id="text" rows="3" class="w-full bg-gray-900 text-sm p-3 rounded" placeholder="Write a note… Use @name for mentions"></textarea>
      <div class="grid grid-cols-1 md:grid-cols-5 gap-2 mt-2">
        <input id="parent" placeholder="parent note id (optional)" class="bg-gray-800 border border-gray-700 rounded px-3 py-2"/>
        <input id="mentions" placeholder="mentions CSV (optional)" class="bg-gray-800 border border-gray-700 rounded px-3 py-2"/>
        <button id="post" class="px-3 py-2 rounded bg-blue-600 text-white">Post</button>
      </div>
    </div>
    <div id="list"></div>
  </div>
  <script>
    function render(notes){{
      // Build threaded view: parent first, then children indented
      const byId = Object.fromEntries((notes||[]).map(n=>[n.id,n]));
      const children = {{}};
      (notes||[]).forEach(n=>{{ if(n.parent_id) (children[n.parent_id] ||= []).push(n); }});
      const roots = (notes||[]).filter(n=>!n.parent_id);
      roots.sort((a,b)=>new Date(b.at)-new Date(a.at));
      function block(n, depth){{
        let html = `
          <div class="rounded border border-gray-800 p-2 mb-2 ${'{'}depth>0?'bubble':''{'}'}">
            <div class="text-sm">${'{'}n.text{'}'}</div>
            <div class="text-xs text-gray-400">by ${'{'}n.by{'}'} • ${'{'}n.at{'}'} ${'{'}(n.mentions&&n.mentions.length)?('• @'+n.mentions.join(', ')) : ''{'}'}</div>
            <div class="text-xs mono">id: ${'{'}n.id{'}'}</div>
          </div>`;
        (children[n.id]||[]).sort((a,b)=>new Date(a.at)-new Date(b.at)).forEach(c=>{{ html += block(c, depth+1); }});
        return html;
      }}
      let out=''; roots.forEach(r=> out += block(r,0)); return out || '<div class="text-gray-400">No notes</div>';
    }}
    async function api(u,opts){{const a=sessionStorage.getItem('adminAuth');const r=await fetch(u,{{...opts,headers:{{'Authorization':'Basic '+a,...(opts&&opts.headers||{{}})}}}});return await r.json().catch(()=>({{}}));}}
    async function load(){{
      const j=await api('/api/admin/campaigns/notes/{campaign_id}');
      document.getElementById('list').innerHTML = render((j.data&&j.data.notes)||[]);
    }}
    async function post(){{
      const text=document.getElementById('text').value.trim(); if(!text){{alert('Note cannot be empty');return;}}
      const parent=document.getElementById('parent').value.trim()||null;
      const mCsv=document.getElementById('mentions').value.trim();
      const mentions=mCsv?mCsv.split(',').map(x=>x.trim()).filter(Boolean):[];
      const j=await api('/api/admin/campaigns/notes/{campaign_id}',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{ text, parent_id: parent, mentions }})}});
      if(j.success){{ document.getElementById('text').value=''; document.getElementById('parent').value=''; document.getElementById('mentions').value=''; load(); }}
      else alert('Post failed');
    }}
    document.getElementById('post').addEventListener('click', post);
    load();
  </script>
</body>
</html>
"""
    return HTMLResponse(content=html)

# ---------- 3) Withdrawals Batch Actions (multi-approve/reject) -------------------------
# Batch endpoint performs per-request updates with audit trail; UI includes confirmation.

@app.post("/api/admin/withdrawals/batch")
async def withdrawals_batch_action(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        action = (body.get("action") or "").strip().lower()  # approve|reject
        ids = body.get("request_ids") or []
        note = (body.get("note") or "").strip()
        if action not in ("approve","reject") or not isinstance(ids, list) or not ids:
            raise HTTPException(status_code=400, detail="Invalid action or request_ids")
        db = db_client.walletbot
        ok = 0; fail = 0
        for rid in ids:
            try:
                q = {"request_id": rid, "status": "pending"}
                upd = {"$set": {"status": "approved" if action=="approve" else "rejected", "processed_time": datetime.utcnow(), "admin_notes": note or f"batch-{action}"}}
                res = await db.withdrawal_requests.update_one(q, upd)
                if getattr(res, "modified_count", 0) > 0:
                    ok += 1
                else:
                    fail += 1
            except Exception:
                fail += 1
        await write_audit_log("withdrawals_batch_action", username, {"action": action, "ok": ok, "fail": fail})
        return {"success": True, "ok": ok, "fail": fail}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Withdrawals batch error: {e}")
        raise HTTPException(status_code=500, detail="Batch failed")

