from uuid import uuid4

# ---------- 1) Reviewer Calibration Pairs (blind re-review) -----------------------------
# Creates blind re-review tasks from recently approved/rejected items to measure agreement.
# Collections:
#   calibration_tasks { task_id, submission_id, original_reviewer, assigned_to, status: pending|done,
#                      created_at, completed_at, original_label, new_label, agreement }
# Admin flow: generate tasks -> reviewers re-review via link -> view agreement metrics.

@app.post("/api/admin/calibration/generate")
async def calibration_generate(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        days = max(1, min(30, int(body.get("days", 7))))
        per_reviewer = max(1, min(20, int(body.get("per_reviewer", 5))))
        reviewers = body.get("reviewers") or []  # optional subset to sample from
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=days)
        # pool of reviewed items
        q = {"reviewed_at": {"$gte": since}, "status": {"$in": ["approved","rejected"]}}
        if reviewers:
            q["assigned_to"] = {"$in": reviewers}
        cur = db.screenshots.find(q, {"_id":0, "submission_id":1, "assigned_to":1, "status":1}).limit(5000)
        pool = await cur.to_list(length=5000)
        # bucket by original reviewer
        from collections import defaultdict
        by = defaultdict(list)
        for s in pool:
            who = s.get("assigned_to") or "unknown"
            by[who].append(s)
        # generate tasks by sampling per reviewer and assigning to different reviewers
        tasks = []
        all_reviewers = list(by.keys())
        for orig, arr in by.items():
            import random
            random.shuffle(arr)
            sample = arr[:per_reviewer]
            # potential assignees (other than original)
            assignees = [r for r in all_reviewers if r != orig] or ["calibrator"]
            for s in sample:
                at = random.choice(assignees)
                t = {
                    "task_id": str(uuid4()),
                    "submission_id": s["submission_id"],
                    "original_reviewer": orig,
                    "assigned_to": at,
                    "status": "pending",
                    "created_at": datetime.utcnow(),
                    "original_label": s["status"],
                }
                tasks.append(t)
        if not tasks:
            return {"success": True, "created": 0}
        await db.calibration_tasks.insert_many(tasks)
        await write_audit_log("calibration_generate", username, {"days": days, "per_reviewer": per_reviewer, "created": len(tasks)})
        return {"success": True, "created": len(tasks)}
    except Exception as e:
        logger.error(f"Calibration generate error: {e}")
        raise HTTPException(status_code=500, detail="Failed to generate tasks")

@app.get("/api/admin/calibration/tasks")
async def calibration_tasks_list(
    reviewer: Optional[str] = None,
    status: Optional[str] = None,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        q: Dict[str, Any] = {}
        if reviewer:
            q["assigned_to"] = reviewer
        if status:
            q["status"] = status
        cur = db.calibration_tasks.find(q, {"_id":0}).sort("created_at", -1).limit(1000)
        items = await cur.to_list(length=1000)
        return {"success": True, "data": items}
    except Exception as e:
        logger.error(f"Calibration tasks list error: {e}")
        raise HTTPException(status_code=500, detail="Failed to list tasks")

@app.post("/api/admin/calibration/submit")
async def calibration_submit(
    body: Dict[str, Any],
    auth_ctx: Dict[str, Any] = Depends(authenticate_any)
):
    try:
        # reviewer submits label; compute agreement
        require_admin(auth_ctx)
        db = db_client.walletbot
        task_id = (body.get("task_id") or "").strip()
        new_label = (body.get("label") or "").strip().lower()  # approved|rejected
        who = auth_ctx.get("username")
        t = await db.calibration_tasks.find_one({"task_id": task_id})
        if not t or t.get("status") != "pending":
            raise HTTPException(status_code=404, detail="task not pending")
        if t.get("assigned_to") and t["assigned_to"] != who:
            # still allow, but note mismatch
            pass
        orig = (t.get("original_label") or "").lower()
        agree = (orig == new_label)
        await db.calibration_tasks.update_one(
            {"task_id": task_id},
            {"$set": {"status": "done", "completed_at": datetime.utcnow(), "new_label": new_label, "agreement": agree, "completed_by": who}}
        )
        return {"success": True, "agreement": agree}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Calibration submit error: {e}")
        raise HTTPException(status_code=500, detail="Failed to submit")

@app.get("/api/admin/calibration/metrics")
async def calibration_metrics(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(90, int(days))))
        cur = db.calibration_tasks.find({"created_at": {"$gte": since}, "status": "done"}, {"_id":0, "original_reviewer":1, "assigned_to":1, "agreement":1})
        from collections import defaultdict
        by_orig = defaultdict(lambda: {"n":0, "agree":0})
        by_assignee = defaultdict(lambda: {"n":0, "agree":0})
        async for x in cur:
            o = x.get("original_reviewer") or "unknown"
            a = x.get("assigned_to") or "unknown"
            ag = bool(x.get("agreement"))
            by_orig[o]["n"] += 1; by_orig[o]["agree"] += (1 if ag else 0)
            by_assignee[a]["n"] += 1; by_assignee[a]["agree"] += (1 if ag else 0)
        def fold(m):
            rows = []
            for k,v in m.items():
                pct = round((v["agree"]/v["n"])*100.0, 1) if v["n"]>0 else 0.0
                rows.append({"reviewer": k, "tasks": v["n"], "agreement_pct": pct})
            rows.sort(key=lambda x: -x["agreement_pct"])
            return rows
        return {"success": True, "data": {"by_original": fold(by_orig), "by_assignee": fold(by_assignee), "window_days": days}}
    except Exception as e:
        logger.error(f"Calibration metrics error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute metrics")

