# ---------- 3) Withdrawal Method Performance Stats --------------------------------------
# Summarize approval times and breach rates per method for last N days.

@app.get("/api/admin/withdrawals/method-stats")
async def withdrawals_method_stats(
    days: int = 30,
    threshold_h: float = 48.0,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(1, min(120, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.withdrawal_requests.find({"created_at": {"$gte": since}}, {"_id":0, "request_id":1, "method":1, "status":1, "created_at":1, "processed_time":1})
        from collections import defaultdict
        by = defaultdict(lambda: {"n":0, "done":0, "breach":0, "durations": []})
        async for w in cur:
            m = (w.get("method") or "unknown").lower()
            by[m]["n"] += 1
            ct = w.get("created_at")
            pt = w.get("processed_time")
            end = pt or datetime.utcnow()
            dur_h = ((end - ct).total_seconds()/3600.0) if ct else 0.0
            if pt:
                by[m]["done"] += 1
                by[m]["durations"].append(dur_h)
            if dur_h > float(threshold_h):
                by[m]["breach"] += 1
        rows = []
        for m, d in by.items():
            avg_h = round(sum(d["durations"])/len(d["durations"]), 2) if d["durations"] else 0.0
            breach_rate = round((d["breach"]/d["n"])*100.0, 1) if d["n"]>0 else 0.0
            rows.append({"method": m, "count": d["n"], "done": d["done"], "avg_hours_done": avg_h, "breach_rate_pct": breach_rate})
        rows.sort(key=lambda x: (-x["breach_rate_pct"], -x["count"]))
        return {"success": True, "data": {"rows": rows, "window_days": days, "threshold_h": threshold_h}}
    except Exception as e:
        logger.error(f"Withdrawal method stats error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute stats")

