# ---------- 1) Assignment Simulator (what-if reviewer count) -----------------------------
# Simulates ETA to drain pending queue under different reviewer counts and avg throughput.

@app.get("/api/admin/sim/assign")
async def assign_simulator(
    reviewer_count: int = 6,
    avg_per_reviewer_per_hour: float = 30.0,
    include_unassigned_only: bool = False,
    username: str = Depends(authenticate_admin)
):
    """
    Estimates time to drain pending queue:
    - reviewer_count: active reviewers in this what-if scenario
    - avg_per_reviewer_per_hour: assumed throughput
    - if include_unassigned_only=True, counts only unassigned pending; else all pending
    """
    try:
        db = db_client.walletbot
        q = {"status": "pending"}
        if include_unassigned_only:
            q["$or"] = [{"assigned_to": {"$exists": False}}, {"assigned_to": ""}]
        total_pending = await db.screenshots.count_documents(q)
        cap_per_hour = max(1.0, float(avg_per_reviewer_per_hour)) * max(1, int(reviewer_count))
        hours = total_pending / cap_per_hour if cap_per_hour > 0 else None
        return {"success": True, "data": {"pending": total_pending, "reviewers": reviewer_count, "throughput_per_reviewer_per_hour": avg_per_reviewer_per_hour, "estimated_hours": round(hours,2) if hours is not None else None}}
    except Exception as e:
        logger.error(f"Assign simulator error: {e}")
        raise HTTPException(status_code=500, detail="Simulation failed")

