# ---------- 2) Campaign SLA Trend Lines (daily breach rate over window) -----------------

@app.get("/api/admin/campaigns/sla/trends")
async def campaign_sla_trends(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    """
    For each campaign with SLA configured, returns daily breach rate (%) over last N days.
    Breach: reviewed time exceeding SLA hours or still pending past SLA.
    """
    try:
        db = db_client.walletbot
        days = max(7, min(120, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        sla = (cfg.get("campaign_sla") or {})
        # fetch screened items in window (created within window)
        cur = db.screenshots.find({"created_at": {"$gte": since}}, {"_id":0,"campaign_id":1,"created_at":1,"reviewed_at":1})
        from collections import defaultdict
        daily = defaultdict(lambda: defaultdict(lambda: {"total":0, "breach":0}))
        now = datetime.utcnow()
        async for s in cur:
            cid = s.get("campaign_id")
            if cid not in sla:
                continue
            key_day = s.get("created_at").date().isoformat() if s.get("created_at") else now.date().isoformat()
            target_h = float((sla.get(cid) or {}).get("review_hours", 0) or 0)
            if target_h <= 0:
                continue
            start = s.get("created_at") or now
            end = s.get("reviewed_at")
            elapsed_h = ((end or now) - start).total_seconds()/3600.0
            daily[cid][key_day]["total"] += 1
            if (end is None and elapsed_h >= target_h) or (end is not None and elapsed_h > target_h):
                daily[cid][key_day]["breach"] += 1
        # build result
        out = []
        for cid, days_map in daily.items():
            series = []
            for d in sorted(days_map.keys()):
                t = days_map[d]["total"]; b = days_map[d]["breach"]
                rate = round((b/t)*100.0, 1) if t>0 else 0.0
                series.append({"day": d, "breach_rate_pct": rate, "total": t})
            out.append({"campaign_id": cid, "series": series})
        return {"success": True, "data": {"trends": out, "window_days": days}}
    except Exception as e:
        logger.error(f"SLA trends error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute trends")

