# ---------- 3) Withdrawal Payer/Bank Latency Rollups ------------------------------------
# Assumes withdrawal_requests may include fields: payer (or provider), method, created_at, processed_time.

@app.get("/api/admin/withdrawals/latency-rollups")
async def withdrawals_latency_rollups(
    days: int = 30,
    group_by: str = "method",  # method|payer
    username: str = Depends(authenticate_admin)
):
    """
    Returns avg, p50, p90, p99 hours to completion by group (method or payer) for last N days.
    """
    try:
        db = db_client.walletbot
        days = max(1, min(120, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.withdrawal_requests.find({"created_at": {"$gte": since}}, {"_id":0, "method":1, "payer":1, "created_at":1, "processed_time":1})
        from collections import defaultdict
        by = defaultdict(list)
        async for w in cur:
            key = (w.get("payer") or "unknown") if group_by=="payer" else (w.get("method") or "unknown")
            ct = w.get("created_at"); pt = w.get("processed_time")
            if not ct or not pt: 
                continue
            h = (pt - ct).total_seconds()/3600.0
            by[key].append(h)
        def pct(arr, p):
            if not arr: return 0.0
            arr2 = sorted(arr)
            idx = min(len(arr2)-1, max(0, int(round((p/100.0)*(len(arr2)-1)))))
            return arr2[idx]
        rows = []
        for k, arr in by.items():
            rows.append({
                "group": k,
                "n": len(arr),
                "avg_h": round(sum(arr)/len(arr), 2),
                "p50_h": round(pct(arr,50),2),
                "p90_h": round(pct(arr,90),2),
                "p99_h": round(pct(arr,99),2)
            })
        rows.sort(key=lambda x: (-x["p90_h"], -x["n"]))
        return {"success": True, "data": {"rows": rows, "window_days": days, "group_by": group_by}}
    except Exception as e:
        logger.error(f"Latency rollups error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute rollups")

