# ---------- 4) Runbook Mention Graph (cross-ref links) ----------------------------------
# Parses admin_notes_pages content for markdown links to other runbook slugs and renders a simple adjacency list.

import re

@app.get("/api/admin/runbook/graph")
async def runbook_graph_api(username: str = Depends(authenticate_admin)):
    """
    Builds a lightweight graph: node per slug; edges when a page links to /admin/runbook/<slug> or [text](runbook:<slug>)
    """
    try:
        db = db_client.walletbot
        cur = db.admin_notes_pages.find({}, {"_id":0, "slug":1, "content":1, "title":1})
        nodes = []
        edges = []
        slug_re = re.compile(r"(?:/admin/runbook/([A-Za-z0-9\-\_]+)|\\(runbook:([A-Za-z0-9\-\_]+)\\))")
        async for p in cur:
            s = p.get("slug"); c = p.get("content") or ""; t = p.get("title") or s
            nodes.append({"id": s, "title": t})
            # find mentions
            hits = re.findall(r"\[.*?\]\((?:/admin/runbook/([A-Za-z0-9\-\_]+)|runbook:([A-Za-z0-9\-\_]+))\)", c)
            for a,b in hits:
                target = a or b
                if target and target != s:
                    edges.append({"from": s, "to": target})
        return {"success": True, "data": {"nodes": nodes, "edges": edges}}
    except Exception as e:
        logger.error(f"Runbook graph error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build graph")

