# ---------- 1) Access Keys Rotation Helper ----------------------------------------------
# Store service access keys and rotation history in settings:
# bot_settings.main_config.access_keys = {
#   "services": { "analytics": {"key":"...", "rotated_at": ISO, "note": ""}, ... },
#   "history":  [ { "service":"analytics", "old_tail":"...","new_tail":"...", "at": ISO, "by": "admin" } ]
# }

@app.get("/api/admin/keys")
async def access_keys_get(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        return {"success": True, "data": (cfg.get("access_keys") or {"services":{}, "history":[]})}
    except Exception as e:
        logger.error(f"Keys get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load keys")

@app.post("/api/admin/keys/rotate")
async def access_keys_rotate(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Rotate key for a service.
    Body: { service: "analytics", new_key: "..." (optional, auto-generate if missing), note: "..." }
    """
    try:
        service = (body.get("service") or "").strip()
        if not service:
            raise HTTPException(status_code=400, detail="service required")
        new_key = (body.get("new_key") or "").strip() or str(uuid4()) + str(uuid4())
        note = (body.get("note") or "").strip()
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {"type":"main_config"}
        keys = cfg.get("access_keys") or {"services":{}, "history":[]}
        old = (keys["services"].get(service) or {}).get("key", "")
        old_tail = old[-6:] if old else ""
        new_tail = new_key[-6:]
        keys["services"][service] = {"key": new_key, "rotated_at": datetime.utcnow(), "note": note}
        keys.setdefault("history", []).append({"service": service, "old_tail": old_tail, "new_tail": new_tail, "at": datetime.utcnow(), "by": username})
        await db.bot_settings.update_one({"type":"main_config"}, {"$set": {"access_keys": keys, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("access_key_rotate", username, {"service": service, "new_tail": new_tail})
        return {"success": True, "new_tail": new_tail}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Keys rotate error: {e}")
        raise HTTPException(status_code=500, detail="Failed to rotate key")

