def _dict_diff(a: Dict[str, Any], b: Dict[str, Any], path=""):
    diffs = []
    ka = set(a.keys()); kb = set(b.keys())
    for k in sorted(ka | kb):
        pa = path + k
        if k not in b:
            diffs.append({"path": pa, "type": "only_in_a", "a": a[k]})
        elif k not in a:
            diffs.append({"path": pa, "type": "only_in_b", "b": b[k]})
        else:
            va, vb = a[k], b[k]
            if isinstance(va, dict) and isinstance(vb, dict):
                diffs += _dict_diff(va, vb, pa + ".")
            elif va != vb:
                diffs.append({"path": pa, "type": "changed", "a": va, "b": vb})
    return diffs

@app.get("/api/admin/config/diff")
async def config_diff_api(
    a: str,
    b: str,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        snaps = (cfg.get("config_snapshots") or {})
        if a not in snaps or b not in snaps:
            raise HTTPException(status_code=400, detail="unknown snapshot key")
        diffs = _dict_diff(snaps[a] or {}, snaps[b] or {})
        return {"success": True, "data": {"a": a, "b": b, "diffs": diffs}}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Config diff error: {e}")
        raise HTTPException(status_code=500, detail="Failed to diff")

