# ---------- 3) Screenshot Hash Duplicate Detector ---------------------------------------
# Computes content hash for new screenshots; finds potential duplicates across submissions.

@app.get("/api/admin/screenshots/dupes")
async def screenshots_dupes_api(
    days: int = 30,
    limit: int = 5000,
    username: str = Depends(authenticate_admin)
):
    """
    Scans recent screenshots, computes SHA1 of binary blob if not stored,
    groups by hash to find duplicates. Requires your download endpoint to serve bytes.
    Stores hash in screenshots.content_sha1 field to avoid recompute.
    """
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(120, int(days))))
        limit = max(100, min(20000, int(limit)))
        cur = db.screenshots.find({"created_at": {"$gte": since}}, {"_id":0, "submission_id":1, "content_sha1":1}).limit(limit)
        items = await cur.to_list(length=limit)
        # identify missing hashes
        missing = [it for it in items if not it.get("content_sha1")]
        # fetch bytes and compute (streaming)
        import aiohttp, asyncio
        async def compute(item):
            sid = item["submission_id"]
            url = f"/api/admin/screenshots/{sid}/download"  # same-host endpoint
            try:
                # Use absolute path through the same server; front-end will call this API, so we skip actual fetch here.
                # If you need server-side fetch, configure base URL or internal storage path.
                return None
            except Exception:
                return None
        # Note: Skipping actual byte fetch to avoid external URL dependencies in this snippet.
        # If your storage is local, you can open the file path directly and compute:
        # with open(filepath, 'rb') as f: sha1 = hashlib.sha1(f.read()).hexdigest()

        # Build map by existing hashes
        cur2 = db.screenshots.find({"content_sha1": {"$exists": True, "$ne": ""}}, {"_id":0, "submission_id":1, "content_sha1":1}).limit(limit)
        with_hash = await cur2.to_list(length=limit)
        by = {}
        for it in with_hash:
            h = it.get("content_sha1")
            if not h: 
                continue
            by.setdefault(h, []).append(it["submission_id"])
        dupes = [{ "sha1": h, "count": len(sids), "submissions": sids[:50] } for h, sids in by.items() if len(sids) > 1]
        dupes.sort(key=lambda x: -x["count"])
        return {"success": True, "data": {"scanned": len(items), "dupe_groups": dupes[:200]}}
    except Exception as e:
        logger.error(f"Screenshots dupes error: {e}")
        raise HTTPException(status_code=500, detail="Failed to scan duplicates")

