from uuid import uuid4

# ---------- 1) Reviewer Incentives Report (scorecards) ----------------------------------
# Score formula (editable via settings recommended; here a simple baseline):
# score = 1*approved - 1*rejected - 2*reversed + 0.5*speed_bonus
# where speed_bonus is scaled by median review time inverse (faster => higher)

@app.get("/api/admin/reviewer/incentives")
async def reviewer_incentives(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(7, min(120, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        # Gather approvals/rejections, and reversed decisions if tracked in audit_logs
        cur = db.screenshots.find(
            {"reviewed_at": {"$gte": since}, "status": {"$in": ["approved","rejected"]}},
            {"_id":0, "assigned_to":1, "status":1, "created_at":1, "reviewed_at":1}
        )
        from collections import defaultdict
        stats = defaultdict(lambda: {"approved":0, "rejected":0, "durations_min": []})
        async for s in cur:
            who = s.get("assigned_to") or "unknown"
            st = (s.get("status") or "").lower()
            if st == "approved":
                stats[who]["approved"] += 1
            elif st == "rejected":
                stats[who]["rejected"] += 1
            ca, ra = s.get("created_at"), s.get("reviewed_at")
            if ca and ra:
                stats[who]["durations_min"].append((ra - ca).total_seconds()/60.0)
        # reversed decisions (optional heuristic via audit logs)
        rev = defaultdict(int)
        cur2 = db.audit_logs.find(
            {"action": {"$in": ["review_decision_reversed","appeal_approved","appeal_rejected"]},
             "created_at": {"$gte": since}},
            {"_id":0,"actor":1}
        )
        async for a in cur2:
            who = a.get("actor") or "unknown"
            rev[who] += 1

        def median(arr):
            if not arr: return 0.0
            arr = sorted(arr)
            n = len(arr); mid = n//2
            return (arr[mid] if n%2==1 else (arr[mid-1]+arr[mid])/2.0)

        rows = []
        for user, d in stats.items():
            appr = d["approved"]; rej = d["rejected"]; revs = rev.get(user, 0)
            med = median(d["durations_min"])
            # speed bonus inversely proportional to median (cap to avoid outliers)
            speed_bonus = 0.0
            if med > 0:
                speed_bonus = min(20.0, max(0.0, 10.0 * (30.0/med)))  # 30min baseline
            score = 1.0*appr - 1.0*rej - 2.0*revs + 0.5*speed_bonus
            rows.append({
                "reviewer": user,
                "approved": appr,
                "rejected": rej,
                "reversed": revs,
                "median_minutes": round(med,1),
                "speed_bonus": round(speed_bonus,1),
                "score": round(score,1)
            })
        rows.sort(key=lambda x: (-x["score"], -x["approved"], x["median_minutes"]))
        return {"success": True, "data": {"rows": rows, "window_days": days}}
    except Exception as e:
        logger.error(f"Incentives error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute incentives")

