# ---------- 2) Campaign Cohort Charts (weekly throughput/retention-style) ---------------
# Cohort by week-of-created; metrics: submissions that week, reviewed within 24h/48h/7d.

@app.get("/api/admin/campaigns/cohorts")
async def campaign_cohorts(
    weeks: int = 12,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        weeks = max(4, min(52, int(weeks)))
        since = datetime.utcnow() - timedelta(weeks=weeks)
        cur = db.screenshots.find(
            {"created_at": {"$gte": since}},
            {"_id":0,"campaign_id":1,"created_at":1,"reviewed_at":1}
        )
        from collections import defaultdict
        import math
        # key: (campaign_id, iso_year_week)
        cohorts = defaultdict(lambda: {"total":0, "24h":0, "48h":0, "7d":0})
        async for s in cur:
            cid = s.get("campaign_id") or "unknown"
            ca = s.get("created_at")
            if not ca:
                continue
            y, w, _ = ca.isocalendar()  # (year, week, weekday)
            key = (cid, f"{y}-W{w:02d}")
            cohorts[key]["total"] += 1
            ra = s.get("reviewed_at")
            if ra:
                dt_h = (ra - ca).total_seconds()/3600.0
                if dt_h <= 24: cohorts[key]["24h"] += 1
                if dt_h <= 48: cohorts[key]["48h"] += 1
                if dt_h <= 24*7: cohorts[key]["7d"] += 1
        rows = []
        for (cid, wk), d in cohorts.items():
            t = max(1, d["total"])
            rows.append({
                "campaign_id": cid,
                "week": wk,
                "total": d["total"],
                "within_24h_pct": round(d["24h"]/t*100.0, 1),
                "within_48h_pct": round(d["48h"]/t*100.0, 1),
                "within_7d_pct": round(d["7d"]/t*100.0, 1),
            })
        rows.sort(key=lambda x: (x["campaign_id"], x["week"]))
        return {"success": True, "data": {"rows": rows, "window_weeks": weeks}}
    except Exception as e:
        logger.error(f"Cohorts error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute cohorts")

