# ---------- 3) Withdrawal Retry Matrix (attempts × outcomes) ----------------------------
# Assumes withdrawal_requests may track retry_count and last_error.

@app.get("/api/admin/withdrawals/retry-matrix")
async def withdrawals_retry_matrix(
    days: int = 60,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(7, min(180, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.withdrawal_requests.find({"created_at": {"$gte": since}}, {"_id":0,"retry_count":1,"status":1,"last_error":1})
        from collections import defaultdict, Counter
        mat = defaultdict(lambda: {"total":0, "success":0, "fail":0, "errors": Counter()})
        async for w in cur:
            k = int(w.get("retry_count", 0) or 0)
            st = (w.get("status") or "").lower()
            mat[k]["total"] += 1
            if st == "approved":
                mat[k]["success"] += 1
            elif st in ("rejected","failed","error"):
                mat[k]["fail"] += 1
                err = (w.get("last_error") or "unknown").split(":")[0][:80]
                mat[k]["errors"][err] += 1
        rows = []
        for k, d in mat.items():
            succ = d["success"]; tot = max(1, d["total"])
            rows.append({
                "retries": k,
                "total": d["total"],
                "success": succ,
                "success_rate_pct": round((succ/tot)*100.0, 1),
                "top_errors": [{"error": e, "count": c} for e,c in d["errors"].most_common(5)]
            })
        rows.sort(key=lambda x: x["retries"])
        return {"success": True, "data": {"rows": rows, "window_days": days}}
    except Exception as e:
        logger.error(f"Retry matrix error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute matrix")

