# ---------- 1) Data Retention Executors (dry-run + execute) -----------------------------
# Uses policies from main_config.retention, e.g.:
# { "screenshots": { "days": 365, "note": "raw images" }, "audit_logs": { "days": 730 } }

@app.post("/api/admin/retention/dry-run")
async def retention_dry_run(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Dry-run retention: counts documents older than policy across listed collections.
    Body: { collections: ["screenshots","audit_logs"] } (optional -> all with policies)
    """
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        pol = (cfg.get("retention") or {})
        cols = body.get("collections") or list(pol.keys())
        out = []
        now = datetime.utcnow()
        for name in cols:
            rule = pol.get(name) or {}
            days = int(rule.get("days", 0) or 0)
            if days <= 0:
                out.append({"collection": name, "eligible": 0, "skipped": True, "reason": "no_days"})
                continue
            cutoff = now - timedelta(days=days)
            coll = getattr(db, name, None)
            if not coll:
                out.append({"collection": name, "eligible": 0, "skipped": True, "reason": "not_found"})
                continue
            # heuristic field precedence: created_at, reviewed_at, at, ts
            cond = {"$or": [
                {"created_at": {"$lt": cutoff}},
                {"reviewed_at": {"$lt": cutoff}},
                {"at": {"$lt": cutoff}},
                {"ts": {"$lt": cutoff}},
            ]}
            eligible = await coll.count_documents(cond)
            out.append({"collection": name, "eligible": eligible, "cutoff": cutoff.isoformat(), "note": rule.get("note")})
        return {"success": True, "data": out}
    except Exception as e:
        logger.error(f"Retention dry-run error: {e}")
        raise HTTPException(status_code=500, detail="Dry-run failed")

@app.post("/api/admin/retention/execute")
async def retention_execute(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Execute retention deletes in batches (safety: max_delete_per_coll optional).
    Body: { collections: ["screenshots"], max_delete_per_coll: 5000 }
    """
    try:
        db = db_client.walletbot
        max_del = int(body.get("max_delete_per_coll", 5000))
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        pol = (cfg.get("retention") or {})
        cols = body.get("collections") or list(pol.keys())
        now = datetime.utcnow()
        res = []
        for name in cols:
            rule = pol.get(name) or {}
            days = int(rule.get("days", 0) or 0)
            if days <= 0:
                res.append({"collection": name, "deleted": 0, "skipped": True, "reason": "no_days"})
                continue
            cutoff = now - timedelta(days=days)
            coll = getattr(db, name, None)
            if not coll:
                res.append({"collection": name, "deleted": 0, "skipped": True, "reason": "not_found"})
                continue
            cond = {"$or": [
                {"created_at": {"$lt": cutoff}},
                {"reviewed_at": {"$lt": cutoff}},
                {"at": {"$lt": cutoff}},
                {"ts": {"$lt": cutoff}},
            ]}
            # deleteMany with limit emulation: fetch ids then remove
            cur = coll.find(cond, {"_id": 1}).limit(max_del)
            ids = [doc["_id"] async for doc in cur]
            if not ids:
                res.append({"collection": name, "deleted": 0})
                continue
            del_res = await coll.delete_many({"_id": {"$in": ids}})
            count = getattr(del_res, "deleted_count", 0)
            res.append({"collection": name, "deleted": count})
        await write_audit_log("retention_execute", username, {"collections": cols, "max_del": max_del})
        return {"success": True, "data": res}
    except Exception as e:
        logger.error(f"Retention execute error: {e}")
        raise HTTPException(status_code=500, detail="Execute failed")

