# ---------- 2) PII Redaction Checker -----------------------------------------------------
# Scans sample docs in selected collections for likely PII patterns (emails, phone numbers, PAN-like, card-like).
# Heuristic-only; does not modify data—report-only.

import re

PII_PATTERNS = {
    "email": re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", re.IGNORECASE),
    "phone": re.compile(r"(?:\+?\d[\d -]{7,}\d)"),
    "card_like": re.compile(r"\b(?:\d[ -]*?){13,19}\b"),
    "pan_like": re.compile(r"\b[A-Z]{5}\d{4}[A-Z]\b"),  # India PAN format heuristic
}

def _walk_strings(obj):
    if obj is None:
        return []
    if isinstance(obj, str):
        return [obj]
    if isinstance(obj, dict):
        out = []
        for v in obj.values():
            out.extend(_walk_strings(v))
        return out
    if isinstance(obj, list):
        out = []
        for v in obj:
            out.extend(_walk_strings(v))
        return out
    return []

@app.get("/api/admin/pii/check")
async def pii_check_api(
    collection: str,
    sample: int = 200,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        coll = getattr(db, collection, None)
        if not coll:
            raise HTTPException(status_code=404, detail="unknown collection")
        sample = max(10, min(2_000, int(sample)))
        cur = coll.find({}, {"_id": 0}).limit(sample)
        hits = {"email": 0, "phone": 0, "card_like": 0, "pan_like": 0}
        examples = {"email": [], "phone": [], "card_like": [], "pan_like": []}
        async for doc in cur:
            texts = _walk_strings(doc)
            for t in texts:
                for k, rx in PII_PATTERNS.items():
                    if rx.search(t):
                        hits[k] += 1
                        if len(examples[k]) < 5:
                            examples[k].append(t[:200])
        return {"success": True, "data": {"collection": collection, "scanned": sample, "hits": hits, "examples": examples}}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"PII check error: {e}")
