# ---------- 3) Error Budget Tracker (daily SLO with burn alerts) ------------------------
# Define an SLO in settings: main_config.error_budget = { "period_days": 30, "target_uptime_pct": 99.9, "burn_alerts": { "fast": 2.0, "slow": 1.0 } }
# We approximate "errors" using error_events (level=ERROR) per day vs baseline request volume proxy (screenshots/day).

@app.get("/api/admin/error-budget")
async def error_budget_api(
    days: int = 30,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(7, min(120, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        slo = (cfg.get("error_budget") or {"period_days": days, "target_uptime_pct": 99.9, "burn_alerts": {"fast": 2.0, "slow": 1.0}})
        # errors/day
        pipe_err = [
            {"$match": {"level": "ERROR", "at": {"$gte": since}}},
            {"$group": {"_id": {"day": {"$dateToString": {"format":"%Y-%m-%d", "date":"$at"}}}, "errors": {"$sum": 1}}}
        ]
        err = await db.error_events.aggregate(pipe_err).to_list(length=2000)
        err_map = {x["_id"]["day"]: x["errors"] for x in err}
        # proxy requests/day
        pipe_req = [
            {"$match": {"created_at": {"$gte": since}}},
            {"$group": {"_id": {"day": {"$dateToString": {"format":"%Y-%m-%d", "date":"$created_at"}}}, "req": {"$sum": 1}}}
        ]
        req = await db.screenshots.aggregate(pipe_req).to_list(length=2000)
        req_map = {x["_id"]["day"]: x["req"] for x in req}
        # compute daily error rate and cumulative burn
        days_list = [ (since + timedelta(days=i)).date().isoformat() for i in range(days) ]
        series = []
        budget_total = 1.0 - float(slo.get("target_uptime_pct", 99.9))/100.0  # allowed error fraction over period
        budget_left = budget_total
        burn_alerts = slo.get("burn_alerts") or {"fast": 2.0, "slow": 1.0}
        alerts = []
        for d in days_list:
            e = float(err_map.get(d, 0))
            r = float(req_map.get(d, 0) or 1.0)
            err_rate = e / r  # very rough
            burn = err_rate / (budget_total/days if budget_total > 0 else 1.0) if budget_total > 0 else 0.0
            budget_left = max(0.0, budget_left - err_rate)
            series.append({"day": d, "errors": int(e), "requests": int(r), "error_rate": round(err_rate,4), "burn": round(burn,2), "budget_left": round(budget_left,4)})
            # alert if burn exceeds thresholds
            if burn >= float(burn_alerts.get("fast", 2.0)):
                alerts.append({"day": d, "kind": "fast_burn", "burn": round(burn,2)})
            elif burn >= float(burn_alerts.get("slow", 1.0)):
                alerts.append({"day": d, "kind": "slow_burn", "burn": round(burn,2)})
        return {"success": True, "data": {"series": series, "budget_total": round(budget_total,4), "alerts": alerts, "slo": slo}}
    except Exception as e:
        logger.error(f"Error budget API error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute error budget")

