# Helper: get weighted order and apply cooldowns (to be used in assigners)
async def _weighted_reviewer_list(campaign_id: str) -> list:
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        rl = (cfg.get("review_load") or {})
        weights = ((rl.get("campaign_weights") or {}).get(campaign_id) or {})
        if not weights:
            # fallback: recent workload info
            pipe = [
                {"$match": {"status": "pending", "campaign_id": campaign_id, "assigned_to": {"$exists": True, "$ne": ""}}},
                {"$group": {"_id": "$assigned_to", "pending": {"$sum": 1}}}
            ]
            agg = await db.screenshots.aggregate(pipe).to_list(length=200)
            arr = sorted([{"name": x["_id"], "w": max(1, 10 - int(x["pending"]))} for x in agg], key=lambda z: -z["w"])
            return [x["name"] for x in arr]
        # expand by weights
        bag = []
        for name, w in weights.items():
            for _ in range(int(max(0, w))):
                bag.append(name)
        if not bag:
            return []
        import random
        random.shuffle(bag)
        # cooldown filter (optional; expecting you keep last_assigned_at map somewhere)
        return bag
    except Exception:
        return []

