@app.post("/api/admin/campaigns/export")
async def campaigns_export(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        cids = body.get("campaign_ids") or []
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        out = {"exported_at": datetime.utcnow().isoformat(), "campaigns": {}}
        for cid in cids:
            out["campaigns"][cid] = {
                "sla": (cfg.get("campaign_sla") or {}).get(cid),
                "freeze": (cfg.get("campaign_freeze") or {}).get(cid),
                "pacing": ((cfg.get("pacing") or {}).get("per_campaign") or {}).get(cid),
                "theme": ((cfg.get("theming") or {}).get("tenants") or {}).get(cid)  # if tenant=campaign mapping used
            }
        blob = json.dumps(out, default=str).encode("utf-8")
        headers = {"Content-Disposition": "attachment; filename=campaign_bundle.json"}
        return StreamingResponse(io.BytesIO(blob), media_type="application/json", headers=headers)
    except Exception as e:
        logger.error(f"Campaign export error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

@app.post("/api/admin/campaigns/import")
async def campaigns_import(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        data = (body.get("campaigns") or {})
        if not isinstance(data, dict):
            raise HTTPException(status_code=400, detail="invalid bundle")
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        # merge maps
        def merge_map(root: dict, path: list, values: dict):
            cur = root
            for k in path[:-1]:
                cur = cur.setdefault(k, {})
            leaf = path[-1]
            cur.setdefault(leaf, {})
            for cid, val in (values or {}).items():
                if val is not None:
                    cur[leaf][cid] = val
        root = cfg
        # Collect per-key maps from the bundle
        sla_map, freeze_map, pacing_map, theme_map = {}, {}, {}, {}
        for cid, obj in data.items():
            if obj.get("sla") is not None: sla_map[cid] = obj["sla"]
            if obj.get("freeze") is not None: freeze_map[cid] = obj["freeze"]
            if obj.get("pacing") is not None:
                root.setdefault("pacing", {})
                root["pacing"].setdefault("per_campaign", {})
                root["pacing"]["per_campaign"][cid] = obj["pacing"]
            if obj.get("theme") is not None:
                root.setdefault("theming", {})
                root["theming"].setdefault("tenants", {})
                root["theming"]["tenants"][cid] = obj["theme"]
        root.setdefault("campaign_sla", {}); root["campaign_sla"].update(sla_map)
        root.setdefault("campaign_freeze", {}); root["campaign_freeze"].update(freeze_map)
        await db.bot_settings.update_one({"type":"main_config"}, {"$set": root, "$currentDate": {"updated_at": True}}, upsert=True)
        await write_audit_log("campaigns_import", username, {"count": len(data)})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Campaign import error: {e}")
        raise HTTPException(status_code=500, detail="Import failed")

