# ---------- 4) Admin CSV Import Validator (dry-run + commit) ----------------------------
# Validates rows against simple schema before insert/update.
# Settings: main_config.csv_importers = {
#   "users_upsert": {
#     "collection": "users",
#     "key": "user_id",
#     "columns": { "user_id": "int", "username": "str", "wallet_balance": "float" },
#     "mode": "upsert"  # insert|upsert
#   }
# }

def _coerce(val: str, typ: str):
    if typ == "int":
        return int(val)
    if typ == "float":
        return float(val)
    if typ == "bool":
        lv = val.strip().lower()
        return lv in ("1","true","yes","y","on")
    return str(val)

@app.get("/api/admin/csv/importers")
async def csv_importers_get(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        return {"success": True, "data": (cfg.get("csv_importers") or {})}
    except Exception as e:
        logger.error(f"CSV importers get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load importers")

@app.post("/api/admin/csv/dry-run")
async def csv_dry_run(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Body: { importer_key: "users_upsert", csv_text: "user_id,username,..." }
    Returns parsed rows, type errors, and upsert plan counts.
    """
    try:
        importer_key = (body.get("importer_key") or "").strip()
        csv_text = body.get("csv_text") or ""
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        imp = (cfg.get("csv_importers") or {}).get(importer_key)
        if not imp:
            raise HTTPException(status_code=400, detail="unknown importer")
        coll_name = imp.get("collection")
        key_field = imp.get("key")
        cols = imp.get("columns") or {}
        mode = (imp.get("mode") or "upsert").lower()

        rdr = csv.DictReader(io.StringIO(csv_text))
        parsed = []
        errors = []
        for i, row in enumerate(rdr, start=1):
            obj = {}
            try:
                for col, typ in cols.items():
                    if col not in row:
                        raise ValueError(f"missing column {col}")
                    obj[col] = _coerce(row[col], typ)
            except Exception as ex:
                errors.append({"line": i, "error": str(ex)})
                continue
            parsed.append(obj)
        # plan upsert/insert counts
        exists = set()
        if key_field:
            q = {key_field: {"$in": [r.get(key_field) for r in parsed if key_field in r]}}
            cur = getattr(db, coll_name).find(q, {key_field: 1, "_id":0})
            async for doc in cur:
                exists.add(doc.get(key_field))
        inserts = sum(1 for r in parsed if key_field and r.get(key_field) not in exists)
        updates = len(parsed) - inserts if mode == "upsert" else 0
        return {"success": True, "data": {"rows_ok": len(parsed), "errors": errors, "plan": {"inserts": inserts, "updates": updates}}}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"CSV dry-run error: {e}")
        raise HTTPException(status_code=500, detail="Dry-run failed")

@app.post("/api/admin/csv/commit")
async def csv_commit(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Body: { importer_key: "users_upsert", csv_text: "..." }
    Performs inserts/upserts per importer definition.
    """
    try:
        importer_key = (body.get("importer_key") or "").strip()
        csv_text = body.get("csv_text") or ""
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        imp = (cfg.get("csv_importers") or {}).get(importer_key)
        if not imp:
            raise HTTPException(status_code=400, detail="unknown importer")
        coll = getattr(db, imp.get("collection"), None)
        if not coll:
            raise HTTPException(status_code=400, detail="unknown collection")
        key_field = imp.get("key")
        cols = imp.get("columns") or {}
        mode = (imp.get("mode") or "upsert").lower()

        rdr = csv.DictReader(io.StringIO(csv_text))
        ok = 0; fail = 0
        async def upsert_one(obj):
            if mode == "insert":
                await coll.insert_one(obj)
            else:
                if key_field not in obj:
                    raise ValueError(f"key {key_field} missing")
                await coll.update_one({key_field: obj[key_field]}, {"$set": obj}, upsert=True)

        for row in rdr:
            try:
                obj = {col: _coerce(row[col], typ) for col, typ in cols.items()}
                await upsert_one(obj)
                ok += 1
            except Exception:
                fail += 1
        await write_audit_log("csv_commit", username, {"importer": importer_key, "ok": ok, "fail": fail})
        return {"success": True, "ok": ok, "fail": fail}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"CSV commit error: {e}")
        raise HTTPException(status_code=500, detail="Commit failed")

