@app.post("/api/admin/anomaly-rules/preset")
async def anomaly_rules_apply_preset(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        name = (body.get("preset") or "").strip()
        if not name:
            raise HTTPException(status_code=400, detail="preset required")
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        rules = cfg.get("anomaly_rules") or {}
        preset_map = (rules.get("presets") or {}).get(name) or {}
        if not preset_map:
            raise HTTPException(status_code=404, detail="preset not found")
        # Apply leaf overrides like "transactions.large_amount.threshold": 1200
        import copy
        new_rules = copy.deepcopy(rules)
        for path, val in preset_map.items():
            cur = new_rules
            parts = path.split(".")
            for p in parts[:-1]:
                cur = cur.setdefault(p, {})
            cur[parts[-1]] = val
        await db.bot_settings.update_one({"type":"main_config"}, {"$set": {"anomaly_rules": new_rules, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("anomaly_rules_preset", username, {"preset": name})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Anomaly preset error: {e}")
        raise HTTPException(status_code=500, detail="Failed to apply preset")

@app.post("/api/admin/anomaly-rules/suppress")
async def anomaly_rules_suppress(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        # Body: { path: "transactions.velocity", minutes: 60 }
        path = (body.get("path") or "").strip()
        minutes = int(body.get("minutes", 60))
        if not path:
            raise HTTPException(status_code=400, detail="path required")
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        rules = cfg.get("anomaly_rules") or {}
        cur = rules
        parts = path.split(".")
        for p in parts[:-1]:
            cur = cur.setdefault(p, {})
        leaf = cur.setdefault(parts[-1], {})
        leaf["suppress_until"] = (datetime.utcnow() + timedelta(minutes=max(1, minutes))).isoformat()
        await db.bot_settings.update_one({"type":"main_config"}, {"$set": {"anomaly_rules": rules, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("anomaly_rules_suppress", username, {"path": path, "minutes": minutes})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Anomaly suppress error: {e}")
        raise HTTPException(status_code=500, detail="Failed to suppress")

