# ---------- 2) Per-campaign Pause Timers with Auto-Resume --------------------------------
# Settings: main_config.campaign_pause = { "CAMP_A": { "paused": true, "resume_at": "ISO", "note": "reason" }, ... }

@app.get("/api/admin/campaigns/pause")
async def campaign_pause_get(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        out = (cfg.get("campaign_pause") or {})
        # auto-clear expired pauses
        changed = False
        now = datetime.utcnow()
        for cid, obj in list(out.items()):
            ra = obj.get("resume_at")
            if ra:
                try:
                    ra_dt = datetime.fromisoformat(ra.replace("Z","+00:00")) if "Z" in ra else datetime.fromisoformat(ra)
                    if now >= ra_dt:
                        obj["paused"] = False
                        obj["resume_at"] = None
                        changed = True
                except Exception:
                    pass
        if changed:
            await db.bot_settings.update_one({"type":"main_config"}, {"$set": {"campaign_pause": out, "updated_at": datetime.utcnow()}}, upsert=True)
        return {"success": True, "data": out}
    except Exception as e:
        logger.error(f"Pause get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load pause map")

