@app.post("/api/admin/services/ping")
async def services_ping(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        # Body: { "names": ["PaymentsAPI"] } optional => ping all
        import aiohttp, time
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        all_svcs = (cfg.get("service_pingers") or {}).get("services") or []
        sel = set(body.get("names") or [s.get("name") for s in all_svcs])
        svcs = [s for s in all_svcs if s.get("name") in sel]
        out = []
        async with aiohttp.ClientSession() as sess:
            for s in svcs:
                url = s.get("url"); to = int(s.get("timeout_sec", 5))
                t0 = time.perf_counter()
                ok = False; sc = None
                try:
                    async with sess.get(url, timeout=to) as resp:
                        sc = resp.status
                        ok = 200 <= sc < 400
                except Exception:
                    ok = False
                ms = int((time.perf_counter() - t0)*1000)
                out.append({"name": s.get("name"), "ok": ok, "ms": ms, "status_code": sc})
                try:
                    await db.service_ping_history.insert_one({"name": s.get("name"), "ts": datetime.utcnow(), "ok": ok, "ms": ms, "status_code": sc})
                except Exception:
                    pass
        # trim history beyond retention
        try:
            days = int((cfg.get("service_pingers") or {}).get("history_days", 7))
            cutoff = datetime.utcnow() - timedelta(days=max(1, min(60, days)))
            await db.service_ping_history.delete_many({"ts": {"$lt": cutoff}})
        except Exception:
            pass
        return {"success": True, "data": out}
    except Exception as e:
        logger.error(f"Services ping error: {e}")
        raise HTTPException(status_code=500, detail="Ping failed")

@app.get("/api/admin/services/history")
async def services_history(name: str, days: int = 7, username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(60, int(days))))
        cur = db.service_ping_history.find({"name": name, "ts": {"$gte": since}}, {"_id":0}).sort("ts", -1).limit(2000)
        items = await cur.to_list(length=2000)
        return {"success": True, "data": items}
    except Exception as e:
        logger.error(f"Services history error: {e}")
        raise HTTPException(status_code=500, detail="History failed")

