@app.post("/api/admin/reviewer/nudges/run")
async def reviewer_nudges_run(username: str = Depends(authenticate_admin)):
    try:
        # Heuristic: for each reviewer with pending >= min_pending and not nudged within cooldown, record a "nudge".
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        nud = (cfg.get("reviewer_nudges") or {})
        if not nud.get("enabled"):
            return {"success": True, "nudged": []}
        min_pending = int(nud.get("min_pending", 10))
        cooldown = int(nud.get("cooldown_min", 120))
        since = datetime.utcnow() - timedelta(minutes=max(15, cooldown))

        # pending by reviewer
        pipe = [
            {"$match": {"status": "pending", "assigned_to": {"$exists": True, "$ne": ""}}},
            {"$group": {"_id": "$assigned_to", "pending": {"$sum": 1}}}
        ]
        agg = await db.screenshots.aggregate(pipe).to_list(length=1000)
        out = []
        for x in agg:
            who = x["_id"]; p = int(x["pending"])
            if p < min_pending: 
                continue
            last = await db.reviewer_nudges_sent.find_one({"reviewer": who, "at": {"$gte": since}}, {"_id":0})
            if last:
                continue
            await db.reviewer_nudges_sent.insert_one({"reviewer": who, "at": datetime.utcnow(), "pending": p})
            await write_audit_log("reviewer_nudge", username, {"reviewer": who, "pending": p})
            out.append({"reviewer": who, "pending": p})
        return {"success": True, "nudged": out}
    except Exception as e:
        logger.error(f"Nudges run error: {e}")
        raise HTTPException(status_code=500, detail="Run failed")

