@app.get("/api/admin/maintenance/regions/status")
async def maintenance_regions_status(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        doc = await db.bot_settings.find_one({"type":"main_config"}) or {}
        conf = (doc.get("maintenance_regions") or {})
        now = datetime.utcnow()
        out = []
        for r in (conf.get("regions") or []):
            s = r.get("start_iso"); e = r.get("end_iso")
            active = False; upcoming_min = None
            try:
                sdt = datetime.fromisoformat(s.replace("Z","+00:00")) if s else None
                edt = datetime.fromisoformat(e.replace("Z","+00:00")) if e else None
                if sdt and edt:
                    active = (now >= sdt and now <= edt)
                    if now < sdt:
                        upcoming_min = int((sdt - now).total_seconds()//60)
            except Exception:
                pass
            out.append({"name": r.get("name"), "message": r.get("message"), "level": r.get("level", "info"), "active": active, "upcoming_min": upcoming_min, "start_iso": s, "end_iso": e})
        return {"success": True, "data": {"now": now.isoformat(), "regions": out, "announce_minutes_before": conf.get("announce_minutes_before", 30)}}
    except Exception as e:
        logger.error(f"Maintenance regions status error: {e}")
        raise HTTPException(status_code=500, detail="Failed to compute status")

