# ---------- 3) Reviewer Weekly Recap Generator (HTML snippet) ---------------------------
# Builds a simple HTML recap for a reviewer: totals, median review time, and recent highlights.

@app.get("/api/admin/reviewer/weekly-recap")
async def reviewer_weekly_recap(
    reviewer: str,
    days: int = 7,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(7, min(14, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.screenshots.find(
            {"reviewed_at": {"$gte": since}, "status": {"$in": ["approved","rejected"]}, "assigned_to": reviewer},
            {"_id":0,"status":1,"created_at":1,"reviewed_at":1,"submission_id":1,"campaign_id":1}
        )
        total = 0; appr = 0; rej = 0; durs = []; recent: List[Dict[str,Any]] = []
        async for s in cur:
            total += 1
            if s.get("status") == "approved": appr += 1
            else: rej += 1
            ca, ra = s.get("created_at"), s.get("reviewed_at")
            if ca and ra:
                durs.append((ra - ca).total_seconds()/60.0)
            if len(recent) < 10:
                recent.append({"submission_id": s.get("submission_id"), "campaign_id": s.get("campaign_id"), "status": s.get("status")})
        def median(arr):
            if not arr: return 0.0
            arr = sorted(arr)
            n = len(arr); m = n//2
            return arr[m] if n%2 else (arr[m-1]+arr[m])/2.0
        med = round(median(durs),1)
        rate = round((appr/(total or 1))*100.0,1)
        html = f"""
<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#0f172a">
  <h2 style="margin:0 0 8px 0">Weekly Recap — {reviewer}</h2>
  <div>Total: <b>{total}</b> • Approved: <b>{appr}</b> • Rejected: <b>{rej}</b> • Approval rate: <b>{rate}%</b></div>
  <div>Median review time: <b>{med} min</b></div>
  <div style="margin-top:8px">Recent:</div>
  <ul>
    {"".join([f"<li>#{x.get('submission_id')} — {x.get('campaign_id')} — {x.get('status')}</li>" for x in recent])}
  </ul>
</div>
"""
        return {"success": True, "data": {"reviewer": reviewer, "window_days": days, "html": html}}
    except Exception as e:
        logger.error(f"Weekly recap error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build recap")

