# ---------- 4) Admin Audit Digest Builder (summary) -------------------------------------
# Summarizes notable admin actions for a given window: top actors, frequent actions, sensitive changes.

SENSITIVE_ACTIONS = {"rate_limits_set","access_key_rotate","campaign_sla_set","retention_execute","ops_roster_set","maintenance_set","maintenance_regions_set"}

@app.get("/api/admin/audit/digest")
async def audit_digest(
    days: int = 7,
    top_n: int = 10,
    username: str = Depends(authenticate_admin)
):
    try:
        db = db_client.walletbot
        days = max(1, min(30, int(days)))
        top_n = max(3, min(50, int(top_n)))
        since = datetime.utcnow() - timedelta(days=days)
        cur = db.audit_logs.find({"created_at": {"$gte": since}}, {"_id":0,"action":1,"actor":1,"created_at":1,"meta":1})
        from collections import Counter, defaultdict
        by_actor = Counter(); by_action = Counter(); sensitive = []
        total = 0
        async for a in cur:
            total += 1
            by_actor[a.get("actor") or "unknown"] += 1
            act = a.get("action") or "unknown"
            by_action[act] += 1
            if act in SENSITIVE_ACTIONS:
                sensitive.append({"at": a.get("created_at"), "action": act, "actor": a.get("actor"), "meta": a.get("meta")})
        top_actors = [{"actor": k, "count": v} for k,v in by_actor.most_common(top_n)]
        top_actions = [{"action": k, "count": v} for k,v in by_action.most_common(top_n)]
        # Build a compact text digest
        lines = []
        lines.append(f"Audit Digest (last {days} days)")
        lines.append(f"Total events: {total}")
        lines.append("Top actors: " + ", ".join([f"{x['actor']}({x['count']})" for x in top_actors]))
        lines.append("Top actions: " + ", ".join([f"{x['action']}({x['count']})" for x in top_actions]))
        if sensitive:
            lines.append("Sensitive changes:")
            for s in sensitive[:top_n]:
                lines.append(f"- {s['at']} • {s['actor']} • {s['action']} • {str(s.get('meta'))[:140]}")
        digest_text = "\n".join(lines)
        return {"success": True, "data": {"total": total, "top_actors": top_actors, "top_actions": top_actions, "sensitive": sensitive[:top_n], "digest_text": digest_text}}
    except Exception as e:
        logger.error(f"Audit digest error: {e}")
        raise HTTPException(status_code=500, detail="Failed to build digest")

