# ---------- 1) Quick CSV Exports: Anomalies (TX) and SLA Breaches (Screens) --------------

@app.get("/api/admin/export/anomalies.csv")
async def export_anomalies_csv(
    days: int = 14,
    velocity_threshold: int = 50,
    amount_threshold: float = 1000.0,
    username: str = Depends(authenticate_admin)
):
    """
    Exports recent transaction anomalies to CSV using simple thresholds.
    """
    try:
        db = db_client.walletbot
        since = datetime.utcnow() - timedelta(days=max(1, min(60, int(days))))
        cur = db.transactions.find({"created_at": {"$gte": since}}, {"_id":0,"tx_id":1,"user_id":1,"amount":1,"type":1,"created_at":1})
        from collections import defaultdict
        by_user = defaultdict(lambda: {"count":0, "large":0})
        rows = []
        async for t in cur:
            uid = t.get("user_id")
            amt = float(t.get("amount",0) or 0)
            by_user[uid]["count"] += 1
            if abs(amt) >= float(amount_threshold):
                by_user[uid]["large"] += 1
            # include a few rows directly for context
            if abs(amt) >= float(amount_threshold):
                rows.append({
                    "user_id": uid, "tx_id": t.get("tx_id"), "amount": amt,
                    "type": t.get("type"), "created_at": t.get("created_at")
                })
        flagged = {u: d for u,d in by_user.items() if d["count"] >= int(velocity_threshold) or d["large"] >= 1}
        out = io.StringIO()
        w = csv.writer(out)
        w.writerow(["user_id","reason","count","large_count","sample_tx_id","sample_amount","sample_type","sample_created_at"])
        for u, d in flagged.items():
            reason = ",".join([r for r,cond in [("high_velocity", d["count"]>=int(velocity_threshold)), ("large_amount", d["large"]>=1)] if cond]) or "flagged"
            # find a matching sample row if any
            sample = next((r for r in rows if r["user_id"]==u), None)
            w.writerow([
                u, reason, d["count"], d["large"],
                (sample or {}).get("tx_id",""),
                (sample or {}).get("amount",""),
                (sample or {}).get("type",""),
                (sample or {}).get("created_at","")
            ])
        blob = out.getvalue().encode("utf-8")
        headers = {"Content-Disposition": "attachment; filename=tx_anomalies.csv"}
        return StreamingResponse(io.BytesIO(blob), media_type="text/csv", headers=headers)
    except Exception as e:
        logger.error(f"Export anomalies CSV error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

@app.get("/api/admin/export/sla-breaches.csv")
async def export_sla_breaches_csv(
    days: int = 7,
    username: str = Depends(authenticate_admin)
):
    """
    Exports SLA breaches for screenshots moderation as CSV (using campaign_sla config).
    """
    try:
        db = db_client.walletbot
        days = max(1, min(60, int(days)))
        since = datetime.utcnow() - timedelta(days=days)
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        sla = (cfg.get("campaign_sla") or {})
        cur = db.screenshots.find({"created_at": {"$gte": since}}, {"_id":0, "submission_id":1, "campaign_id":1, "created_at":1, "reviewed_at":1, "status":1})
        out = io.StringIO()
        w = csv.writer(out)
        w.writerow(["submission_id","campaign_id","status","elapsed_hours","target_hours","closed","created_at","reviewed_at"])
        now = datetime.utcnow()
        async for s in cur:
            cid = s.get("campaign_id")
            target_h = float((sla.get(cid) or {}).get("review_hours", 0) or 0)
            if target_h <= 0:
                continue
            start = s.get("created_at"); end = s.get("reviewed_at")
            elapsed_h = ((end or now) - start).total_seconds()/3600.0 if start else 0.0
            breach = (end is None and elapsed_h >= target_h) or (end is not None and elapsed_h > target_h)
            if breach:
                w.writerow([
                    s.get("submission_id"), cid, s.get("status"),
                    round(elapsed_h,1), target_h, bool(end),
                    start, end
                ])
        blob = out.getvalue().encode("utf-8")
        headers = {"Content-Disposition": "attachment; filename=sla_breaches.csv"}
        return StreamingResponse(io.BytesIO(blob), media_type="text/csv", headers=headers)
    except Exception as e:
        logger.error(f"Export SLA CSV error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

