# ---------- 2) Webhook Tester (signing + replay) ----------------------------------------

# Settings: main_config.webhook_test = {
#   "url": "https://webhook.site/... (or internal endpoint)",
#   "secret": "shared-secret",
#   "algo": "sha256",      # sha256|sha1
#   "header": "X-Signature"  # header to send the HMAC
# }

def _sign_payload(secret: str, payload: bytes, algo: str) -> str:
    algo = (algo or "sha256").lower()
    if algo not in ("sha256","sha1"):
        algo = "sha256"
    digestmod = hashlib.sha256 if algo=="sha256" else hashlib.sha1
    sig = hmac.new(secret.encode("utf-8"), payload, digestmod).hexdigest()
    return sig

@app.get("/api/admin/webhook/test/config")
async def webhook_test_get(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        cfg = await db.bot_settings.find_one({"type":"main_config"}) or {}
        return {"success": True, "data": (cfg.get("webhook_test") or {"url":"", "secret":"", "algo":"sha256", "header":"X-Signature"})}
    except Exception as e:
        logger.error(f"Webhook test get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load")

@app.post("/api/admin/webhook/test/config")
async def webhook_test_set(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        await db.bot_settings.update_one({"type":"main_config"}, {"$set": {"webhook_test": body, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("webhook_test_set", username, {"keys": list((body or {}).keys())})
        return {"success": True}
    except Exception as e:
        logger.error(f"Webhook test set error: {e}")
        raise HTTPException(status_code=500, detail="Failed to save")

@app.post("/api/admin/webhook/test/send")
async def webhook_test_send(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Body: { payload: {...}, override_url?: "...", override_secret?: "...", override_algo?: "sha256", override_header?: "X-Signature" }
    """
    try:
        cfgdb = db_client.walletbot
        cfgdoc = await cfgdb.bot_settings.find_one({"type":"main_config"}) or {}
        base = (cfgdoc.get("webhook_test") or {})
        url = (body.get("override_url") or base.get("url") or "").strip()
        secret = (body.get("override_secret") or base.get("secret") or "").strip()
        algo = (body.get("override_algo") or base.get("algo") or "sha256").strip()
        header = (body.get("override_header") or base.get("header") or "X-Signature").strip()
        if not url:
            raise HTTPException(status_code=400, detail="Missing webhook URL")
        payload_obj = body.get("payload") or {"ping": datetime.utcnow().isoformat()}
        payload = json.dumps(payload_obj, default=str).encode("utf-8")
        sig = _sign_payload(secret, payload, algo) if secret else None

        # Send
        import aiohttp
        async with aiohttp.ClientSession() as sess:
            headers = {"Content-Type": "application/json"}
            if sig:
                headers[header] = sig
            async with sess.post(url, data=payload, headers=headers) as resp:
                status = resp.status
                try:
                    resp_text = await resp.text()
                except Exception:
                    resp_text = ""
        await write_audit_log("webhook_test_send", username, {"url": url, "status": status})
        return {"success": True, "status": status, "signature": sig, "response": (resp_text or "")[:1000]}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Webhook test send error: {e}")
        raise HTTPException(status_code=500, detail="Send failed")

