@app.post("/api/admin/playbooks/run")
async def playbooks_run(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Body: { key: "drain_and_alert" }
    Executes each step sequentially (server-side HTTP calls to local app paths).
    """
    try:
        key = (body.get("key") or "").strip()
        if not key:
            raise HTTPException(status_code=400, detail="key required")
        cfg = await db_client.walletbot.bot_settings.find_one({"type":"main_config"}) or {}
        pb = (cfg.get("playbooks") or {}).get(key)
        if not pb:
            raise HTTPException(status_code=404, detail="unknown playbook")
        steps: List[Dict[str,Any]] = pb.get("steps") or []
        # execute steps via internal calls
        import aiohttp
        results = []
        # Use same-origin base. If running behind a proxy, configure INTERNAL_BASE_URL in settings and use that.
        base = ""
        async with aiohttp.ClientSession() as sess:
            for st in steps:
                method = (st.get("kind") or "GET").upper()
                path = (st.get("path") or "/").strip()
                url = base + path
                try:
                    if method == "GET":
                        async with sess.get(url) as resp:
                            txt = await resp.text()
                            results.append({"path": path, "status": resp.status, "len": len(txt)})
                    else:
                        data = json.dumps(st.get("body") or {}).encode("utf-8")
                        async with sess.post(url, data=data, headers={"Content-Type": "application/json"}) as resp:
                            txt = await resp.text()
                            results.append({"path": path, "status": resp.status, "len": len(txt)})
                except Exception as ex:
                    results.append({"path": path, "error": str(ex)})
        await write_audit_log("playbook_run", username, {"key": key, "steps": len(steps)})
        return {"success": True, "results": results}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Playbooks run error: {e}")
        raise HTTPException(status_code=500, detail="Run failed")

