from typing import List, Dict, Any, Optional

# ---------- 1) Lightweight Job Scheduler (cron-like JSON + run-now) ---------------------
# Settings: main_config.jobs = {
#   "timezone": "UTC",
#   "items": [
#     { "key": "flush_alerts", "cron": "*/15 * * * *", "method": "POST", "path": "/api/admin/alerts/flush", "enabled": true },
#     { "key": "sla_breach_scan", "cron": "0 * * * *", "method": "GET",  "path": "/api/admin/campaigns/sla/breaches?days=1", "enabled": true }
#   ]
# }
# Note: This is a config + manual-run helper; actual periodic execution should be wired to your process manager/cron.

CRON_RE = re.compile(r"^(\*|([0-5]?\d)(?:-([0-5]?\d))?(?:/([1-9]\d?))?|\*/([1-9]\d?))\s+(\*|([01]?\d|2[0-3])(?:-(?\d|2[0-3]))?(?:/([1-9]\d?))?|\*/([1-9]\d?))\s+(\*|(?\d|2[0-9]|3[0-1])(?:-(?\d|2[0-9]|3[0-1]))?(?:/([1-9]\d?))?|\*/([1-9]\d?))\s+(\*|(1[0-2]|0?[1-9])(?:-(1[0-2]|0?[1-9]))?(?:/([1-9]\d?))?|\*/([1-9]\d?))\s+(\*|([0-6])(?:-([0-6]))?(?:/([1-9]\d?))?|\*/([1-9]\d?))$")

@app.get("/api/admin/jobs")
async def jobs_get(username: str = Depends(authenticate_admin)):
    try:
        cfg = await db_client.walletbot.bot_settings.find_one({"type":"main_config"}) or {}
        return {"success": True, "data": (cfg.get("jobs") or {"timezone": "UTC", "items": []})}
    except Exception as e:
        logger.error(f"Jobs get error: {e}")
        raise HTTPException(status_code=500, detail="Failed to load jobs")

@app.post("/api/admin/jobs")
async def jobs_set(body: Dict[str, Any], username: str = Depends(authenticate_admin)):
    try:
        # light validation for cron strings
        for it in (body.get("items") or []):
            if it.get("enabled"):
                c = (it.get("cron") or "").strip()
                if not CRON_RE.match(c):
                    raise HTTPException(status_code=400, detail=f"Invalid cron for {it.get('key')}: {c}")
        await db_client.walletbot.bot_settings.update_one({"type":"main_config"}, {"$set": {"jobs": body, "updated_at": datetime.utcnow()}}, upsert=True)
        await write_audit_log("jobs_set", username, {"count": len(body.get("items") or [])})
        return {"success": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Jobs set error: {e}")
        raise HTTPException(status_code=500, detail="Failed to save jobs")

@app.post("/api/admin/jobs/run")
async def jobs_run_now(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    """
    Body: { key: "flush_alerts" }
    Performs a same-origin HTTP call to the configured path/method once.
    """
    try:
        key = (body.get("key") or "").strip()
        if not key:
            raise HTTPException(status_code=400, detail="key required")
        cfg = await db_client.walletbot.bot_settings.find_one({"type":"main_config"}) or {}
        jobs = (cfg.get("jobs") or {}).get("items") or []
        job = next((j for j in jobs if j.get("key")==key), None)
        if not job:
            raise HTTPException(status_code=404, detail="job not found")
        import aiohttp
        method = (job.get("method") or "GET").upper()
        path = (job.get("path") or "/").strip()
        # Empty base => same host
        async with aiohttp.ClientSession() as sess:
            if method == "GET":
                async with sess.get(path) as resp:
                    txt = await resp.text()
                    st = resp.status
            else:
                async with sess.post(path) as resp:
                    txt = await resp.text()
                    st = resp.status
        await write_audit_log("jobs_run", username, {"key": key, "status": st})
        return {"success": True, "status": st, "response_len": len(txt)}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Jobs run error: {e}")
        raise HTTPException(status_code=500, detail="Run failed")

