# ---------- 2) Ops Notepad → Markdown Export --------------------------------------------
# Exports combined ops notes (from admin_scratchpads and campaign_notes) into a single .md

@app.get("/api/admin/ops-notes/export.md")
async def ops_notes_export_md(username: str = Depends(authenticate_admin)):
    try:
        db = db_client.walletbot
        # gather scratchpads
        sp_cur = db.admin_scratchpads.find({}, {"_id":0,"username":1,"text":1,"updated_at":1})
        scratch = await sp_cur.to_list(length=1000)
        # gather campaign notes
        cn_cur = db.campaign_notes.find({}, {"_id":0,"campaign_id":1,"notes":1,"updated_at":1})
        camp = await cn_cur.to_list(length=5000)
        out = io.StringIO()
        out.write("# Ops Notes Export\n\n")
        out.write("## Scratchpads\n\n")
        for s in scratch:
            out.write(f"### @{s.get('username')}\n\n")
            out.write((s.get("text") or "").strip() + "\n\n")
        out.write("## Campaign Notes\n\n")
        for c in camp:
            out.write(f"### Campaign {c.get('campaign_id')}\n\n")
            for n in (c.get("notes") or []):
                ts = n.get("at"); by = n.get("by"); txt = (n.get("text") or "").replace("\n","  \n")
                out.write(f"- {ts} • @{by}: {txt}\n")
            out.write("\n")
        blob = out.getvalue().encode("utf-8")
        headers = {"Content-Disposition": "attachment; filename=ops_notes_export.md"}
        return StreamingResponse(io.BytesIO(blob), media_type="text/markdown", headers=headers)
    except Exception as e:
        logger.error(f"Ops notes export error: {e}")
        raise HTTPException(status_code=500, detail="Export failed")

