# ---------- 3) Safe-Config Linter (flags missing/invalid keys) ---------------------------
# Define a minimal schema of required keys/types; lint current main_config and report warnings.

REQUIRED_CONFIG_SCHEMA = {
    "ip_access": {"allow": list, "deny": list},
    "session_ip": {"enforce": bool, "admins": dict},
    "campaign_sla": dict,
    "rate_limits": dict,
    "access_keys": {"services": dict, "history": list},
    "review_load": {"campaign_weights": dict, "cooldowns": dict},
    "error_budget": {"period_days": int, "target_uptime_pct": (int,float), "burn_alerts": dict},
}

def _lint_type(val, typ_spec):
    if isinstance(typ_spec, tuple):
        return isinstance(val, typ_spec)
    if isinstance(typ_spec, type):
        return isinstance(val, typ_spec)
    if isinstance(typ_spec, dict):
        if not isinstance(val, dict):
            return False
        for k, t in typ_spec.items():
            if k not in val or not _lint_type(val[k], t):
                return False
        return True
    return True

@app.get("/api/admin/config/lint")
async def config_lint(username: str = Depends(authenticate_admin)):
    try:
        cfgdoc = await db_client.walletbot.bot_settings.find_one({"type":"main_config"}) or {}
        issues = []
        for key, spec in REQUIRED_CONFIG_SCHEMA.items():
            val = cfgdoc.get(key)
            if val is None:
                issues.append({"key": key, "level": "error", "msg": "missing"})
                continue
            if not _lint_type(val, spec):
                issues.append({"key": key, "level": "error", "msg": "invalid type/shape"})
        # light sanity checks
        rl = cfgdoc.get("rate_limits") or {}
        if rl:
            for k in ["api_burst","api_sustained_per_min"]:
                if k in rl and (not isinstance(rl[k], (int,float)) or rl[k] <= 0):
                    issues.append({"key": f"rate_limits.{k}", "level": "warn", "msg": "non-positive or non-numeric"})
        return {"success": True, "data": {"issues": issues, "checked_keys": list(REQUIRED_CONFIG_SCHEMA.keys())}}
    except Exception as e:
        logger.error(f"Config lint error: {e}")
        raise HTTPException(status_code=500, detail="Lint failed")

