# ---------- 1) Smoke-Test Harness -------------------------------------------------------
# Pings selected admin pages/APIs and reports status. Extend the default list as needed.

_SMOKE_URLS = [
  "/admin/index-omicron-plus",
  "/admin/index-pi-prime",
  "/admin/index-sigma-prime",
  "/admin/index-tau-prime",
  "/admin/index-upsilon-prime",
  "/admin/index-chi-prime",
  "/admin/index-psi-prime",
  "/admin/index-omega-prime",
  "/admin/index-omega-double-prime",
  "/admin/index-alpha-prime",
  "/admin/index-beta-prime",
  "/admin/index-gamma-prime",
  "/admin/index-delta-prime",
  "/admin/index-epsilon-prime",
  "/admin/index-zeta-prime",
  "/admin/index-eta-prime",
  "/admin/index-theta-prime",
  "/admin/index-iota-prime",
  "/api/admin/queues/depth",
  "/api/admin/errors/search",
  "/api/admin/reviewer/workload",
  "/api/admin/campaigns/ops",
  "/api/admin/campaigns/sla/breaches",
  "/api/admin/withdrawals/latency-rollups",
  "/api/admin/retention/dry-run"
]

@app.post("/api/admin/smoke/run")
async def smoke_run(
    body: Dict[str, Any] = {},
    username: str = Depends(authenticate_admin)
):
    try:
        urls = body.get("urls") or _SMOKE_URLS
        import aiohttp, asyncio, time
        out = []
        async with aiohttp.ClientSession() as sess:
            for u in urls:
                t0 = time.perf_counter()
                status = None; err = None
                try:
                    async with sess.get(u) as resp:
                        status = resp.status
                        # read minimal body to avoid load
                        _ = await resp.text()
                except Exception as e:
                    err = str(e)[:200]
                ms = int((time.perf_counter() - t0)*1000)
                out.append({"url": u, "status": status, "ms": ms, "error": err})
        passed = sum(1 for r in out if r["status"] and r["status"] < 500)
        await write_audit_log("smoke_run", username, {"count": len(urls), "passed": passed})
        return {"success": True, "summary": {"total": len(urls), "passed": passed}, "results": out}
    except Exception as e:
        logger.error(f"Smoke run error: {e}")
        raise HTTPException(status_code=500, detail="Smoke test failed")

