@app.post("/api/admin/restores/run")
async def restores_run(
    body: Dict[str, Any],
    username: str = Depends(authenticate_admin)
):
    try:
        # Body: { label: "snapshot-2025-08-21", include: ["collections"...], dry_run: true }
        label = (body.get("label") or "").strip()
        if not label:
            raise HTTPException(status_code=400, detail="label required")
        include = body.get("include") or []
        dry = bool(body.get("dry_run", True))
        await write_audit_log("restore_trigger", username, {"label": label, "include": include, "dry_run": dry})
        return {"success": True, "message": "Restore trigger recorded. Integrate with worker to execute."}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Restore trigger error: {e}")
        raise HTTPException(status_code=500, detail="Restore trigger failed")

